window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["2SA"]={"book":"2SA","editions":{"fin-biblia1776":[[1,1,"Ja tapahtui Saulin kuoleman jälkeen, kuin David oli palannut Amalekilaisten taposta, oli David Ziklagissa kaksi päivää.","Ja tapahtui Saulin kuoleman jälkeen, kuin David oli palannut Amalekilaisten taposta, oli David Ziklagissa kaksi päivää."],[1,2,"Katso, kolmantena päivänä tuli yksi mies Saulin leiristä reväistyillä vaatteilla ja multaa päänsä päällä. Ja kuin hän tuli Davidin tykö, lankesi hän maahan ja kumarsi.","Katso, kolmantena päivänä tuli yksi mies Saulin leiristä reväistyillä vaatteilla ja multaa päänsä päällä. Ja kuin hän tuli Davidin tykö, lankesi hän maahan ja kumarsi."],[1,3,"David sanoi hänelle: kustas tulet? Ja hän sanoi hänelle: minä olen paennut Israelin leiristä.","David sanoi hänelle: kustas tulet? Ja hän sanoi hänelle: minä olen paennut Israelin leiristä."],[1,4,"David sanoi hänelle: sanos minulle, mitä siellä on tapahtunut? Hän vastasi: väki on paennut sodasta, ja paljo väkeä on langennut ja kuollut, ja myös Saul ja hänen poikansa Jonatan ovat kuolleet.","David sanoi hänelle: sanos minulle, mitä siellä on tapahtunut? Hän vastasi: väki on paennut sodasta, ja paljo väkeä on langennut ja kuollut, ja myös Saul ja hänen poikansa Jonatan ovat kuolleet."],[1,5,"David sanoi nuorukaiselle, joka näitä ilmoitti: mistä sinä tiedät Saulin ja hänen poikansa Jonatanin kuolleeksi?","David sanoi nuorukaiselle, joka näitä ilmoitti: mistä sinä tiedät Saulin ja hänen poikansa Jonatanin kuolleeksi?"],[1,6,"Nuorukainen, joka hänelle sitä ilmoitti, sanoi: minä tulin tapaturmasta Gilboan vuorelle, ja katso, Saul oli langennut omaan keihääseensä, ja katso, rattaat ja hevosmiehet ajoivat häntä takaa.","Nuorukainen, joka hänelle sitä ilmoitti, sanoi: minä tulin tapaturmasta Gilboan vuorelle, ja katso, Saul oli langennut omaan keihääseensä, ja katso, rattaat ja hevosmiehet ajoivat häntä takaa."],[1,7,"Ja sitte hän käänsi hänensä, ja näki minun ja kutsui tykönsä, ja minä sanoin: tässä minä olen.","Ja sitte hän käänsi hänensä, ja näki minun ja kutsui tykönsä, ja minä sanoin: tässä minä olen."],[1,8,"Hän sanoi minulle: kuka sinä olet? Minä vastasin: minä olen Amalekilainen.","Hän sanoi minulle: kuka sinä olet? Minä vastasin: minä olen Amalekilainen."],[1,9,"Ja hän sanoi minulle: tules minun tyköni ja tapa minua; sillä minä ahdistetaan kovin ja minun henkeni on vielä kokonainen minussa.","Ja hän sanoi minulle: tules minun tyköni ja tapa minua; sillä minä ahdistetaan kovin ja minun henkeni on vielä kokonainen minussa."],[1,10,"Niin minä menin hänen tykönsä ja tapoin hänen; sillä minä tiesin, ettei hän olisi kuitenkaan sen lankeemisen jälkeen elänyt. Ja minä otin kruunun hänen päästänsä ja käsirenkaat hänen kädestänsä ja toin ne tänne minun herralleni.","Niin minä menin hänen tykönsä ja tapoin hänen; sillä minä tiesin, ettei hän olisi kuitenkaan sen lankeemisen jälkeen elänyt. Ja minä otin kruunun hänen päästänsä ja käsirenkaat hänen kädestänsä ja toin ne tänne minun herralleni."],[1,11,"Silloin tarttui David vaatteisiinsa ja repäisi ne; niin myös joka mies, joka hänen kanssansa oli,","Silloin tarttui David vaatteisiinsa ja repäisi ne; niin myös joka mies, joka hänen kanssansa oli,"],[1,12,"Ja valittivat ja itkivät, ja paastosivat ehtoosen asti, Saulin ja hänen poikansa Jonatanin tähden, ja Herran kansan tähden, ja Israelin huoneen tähden, että ne miekan kautta langenneet olivat.","Ja valittivat ja itkivät, ja paastosivat ehtoosen asti, Saulin ja hänen poikansa Jonatanin tähden, ja Herran kansan tähden, ja Israelin huoneen tähden, että ne miekan kautta langenneet olivat."],[1,13,"Ja David sanoi nuorukaiselle, joka näitä hänelle ilmoitti: kusta sinä olet? Hän sanoi: minä olen muukalaisen Amalekilaisen poika.","Ja David sanoi nuorukaiselle, joka näitä hänelle ilmoitti: kusta sinä olet? Hän sanoi: minä olen muukalaisen Amalekilaisen poika."],[1,14,"David sanoi hänelle: miksi et peljännyt laskea kättäs tappamaan Herran voideltua?","David sanoi hänelle: miksi et peljännyt laskea kättäs tappamaan Herran voideltua?"],[1,15,"Ja David kutsui yhden palvelioistansa ja sanoi: tule tänne ja lyö häntä. Ja hän löi hänen kuoliaaksi.","Ja David kutsui yhden palvelioistansa ja sanoi: tule tänne ja lyö häntä. Ja hän löi hänen kuoliaaksi."],[1,16,"Niin sanoi David hänelle: sinun veres olkoon sinun pääs päällä; sillä sinun suus on todistanut itse sinuas vastaan ja sanonut: minä olen Herran voidellun tappanut.","Niin sanoi David hänelle: sinun veres olkoon sinun pääs päällä; sillä sinun suus on todistanut itse sinuas vastaan ja sanonut: minä olen Herran voidellun tappanut."],[1,17,"Ja David valitti tämän valituksen Saulin ja Jonatanin hänen poikansa ylitse,","Ja David valitti tämän valituksen Saulin ja Jonatanin hänen poikansa ylitse,"],[1,18,"Ja käski opettaa Juudan lapsia Joutsivirren: katso, se on kirjoitettu Hurskasten kirjassa.","Ja käski opettaa Juudan lapsia Joutsivirren: katso, se on kirjoitettu Hurskasten kirjassa."],[1,19,"O Israelin kunnia! sinun kukkuloillas ovat surmatut: kuinka sankarit ovat langenneet?","O Israelin kunnia! sinun kukkuloillas ovat surmatut: kuinka sankarit ovat langenneet?"],[1,20,"Älkäät sanoko sitä Gatissa, älkäät myös ilmoittako Askalonin kaduilla, ettei Philistealaisten tyttäret iloitsisi eikä ympärileikkaamattomain tyttäret riemuitsisi.","Älkäät sanoko sitä Gatissa, älkäät myös ilmoittako Askalonin kaduilla, ettei Philistealaisten tyttäret iloitsisi eikä ympärileikkaamattomain tyttäret riemuitsisi."],[1,21,"Te Gilboan vuoret, älköön tulko kaste eikä sade teidän päällenne, älköön myös olko pellot, joista ylennysuhri tulee; sillä siellä on väkeväin kilpi lyöty maahan, Saulin kilpi, niinkuin ei hän olisikaan ollut öljyllä voideltu.","Te Gilboan vuoret, älköön tulko kaste eikä sade teidän päällenne, älköön myös olko pellot, joista ylennysuhri tulee; sillä siellä on väkeväin kilpi lyöty maahan, Saulin kilpi, niinkuin ei hän olisikaan ollut öljyllä voideltu."],[1,22,"Jonatanin joutsi ei harhaillut tapettuin verestä ja voimallisten lihavuudesta, ja Saulin miekka ei palajanut tyhjänä.","Jonatanin joutsi ei harhaillut tapettuin verestä ja voimallisten lihavuudesta, ja Saulin miekka ei palajanut tyhjänä."],[1,23,"Saul ja Jonatan, rakkaat ja suloiset eläissänsä, ei ole myös kuollessansa eroitetut: liukkaammat kuin kotka ja väkevämmät kuin jalopeurat.","Saul ja Jonatan, rakkaat ja suloiset eläissänsä, ei ole myös kuollessansa eroitetut: liukkaammat kuin kotka ja väkevämmät kuin jalopeurat."],[1,24,"Te Israelin tyttäret, itkekäät Saulia, joka teidän vaatetti tulipunaisilla koriasti ja kaunisti teidän vaatteenne kultaisella kaunistuksella.","Te Israelin tyttäret, itkekäät Saulia, joka teidän vaatetti tulipunaisilla koriasti ja kaunisti teidän vaatteenne kultaisella kaunistuksella."],[1,25,"Kuinka sankarit ovat langenneet sodassa? Jonatan on myös tapettu sinun kukkuloillas.","Kuinka sankarit ovat langenneet sodassa? Jonatan on myös tapettu sinun kukkuloillas."],[1,26,"Minä suren suuresti sinun tähtes, minun veljeni Jonatan. Sinä olit minulle juuri rakas: sinun rakkautes oli suurempi minulle kuin vaimoin rakkaus.","Minä suren suuresti sinun tähtes, minun veljeni Jonatan. Sinä olit minulle juuri rakas: sinun rakkautes oli suurempi minulle kuin vaimoin rakkaus."],[1,27,"Kuinka ovat sankarit langenneet, ja sota-aseet tulleet pois?","Kuinka ovat sankarit langenneet, ja sota-aseet tulleet pois?"],[2,1,"Sittenkuin nämä olivat tapahtuneet, kysyi David Herralta, sanoen: menenkö minä johonkuhun Juudan kaupungeista? Ja Herra sanoi hänelle: mene. David sanoi: kuhunka minun pitää menemän? Hän sanoi: Hebroniin.","Sittenkuin nämä olivat tapahtuneet, kysyi David Herralta, sanoen: menenkö minä johonkuhun Juudan kaupungeista? Ja Herra sanoi hänelle: mene. David sanoi: kuhunka minun pitää menemän? Hän sanoi: Hebroniin."],[2,2,"Niin David meni sinne ja kaksi hänen emäntäänsä, Ahinoam Jisreeliläinen ja Abigail Nabalin emäntä Karmelista,","Niin David meni sinne ja kaksi hänen emäntäänsä, Ahinoam Jisreeliläinen ja Abigail Nabalin emäntä Karmelista,"],[2,3,"Niin myös miehet, jotka olivat hänen kanssansa, vei David myötänsä jokaisen huoneinensa. Ja he asuivat Hebronin kaupungeissa.","Niin myös miehet, jotka olivat hänen kanssansa, vei David myötänsä jokaisen huoneinensa. Ja he asuivat Hebronin kaupungeissa."],[2,4,"Ja Juudan miehet tulivat ja voitelivat siellä Davidin Juudan huoneen kuninkaaksi. Ja kuin Davidille ilmoitettiin Jabeksen miehet Gileadissa haudanneen Saulin,","Ja Juudan miehet tulivat ja voitelivat siellä Davidin Juudan huoneen kuninkaaksi. Ja kuin Davidille ilmoitettiin Jabeksen miehet Gileadissa haudanneen Saulin,"],[2,5,"Lähetti hän heille sanan ja antoi sanoa heille: siunatut olette te Herralta, että te tämän laupiuden teitte Saulille teidän herrallenne ja olette haudanneet hänen.","Lähetti hän heille sanan ja antoi sanoa heille: siunatut olette te Herralta, että te tämän laupiuden teitte Saulille teidän herrallenne ja olette haudanneet hänen."],[2,6,"Niin tehköön Herra teille laupiuden ja totuuden, ja minä teen myös teille hyvää, että te tämän teitte.","Niin tehköön Herra teille laupiuden ja totuuden, ja minä teen myös teille hyvää, että te tämän teitte."],[2,7,"Vahvistakaat siis nyt teidän kätenne ja olkaat väkevät; sillä teidän herranne Saul on kuollut, ja Juudan huone on myös minun voidellut hänellensä kuninkaaksi.","Vahvistakaat siis nyt teidän kätenne ja olkaat väkevät; sillä teidän herranne Saul on kuollut, ja Juudan huone on myös minun voidellut hänellensä kuninkaaksi."],[2,8,"Mutta Abner, Nerin poika, Saulin sodanpäämies, otti Isbosetin Saulin pojan, ja vei hänen Mahanaimiin,","Mutta Abner, Nerin poika, Saulin sodanpäämies, otti Isbosetin Saulin pojan, ja vei hänen Mahanaimiin,"],[2,9,"Ja asetti hänen Gileadin, Assurin, Jisreelin, Ephraimin, BenJaminin ja kaiken Israelin kuninkaaksi.","Ja asetti hänen Gileadin, Assurin, Jisreelin, Ephraimin, BenJaminin ja kaiken Israelin kuninkaaksi."],[2,10,"Ja Isboset Saulin poika oli neljänkymmenen ajastaikainen, kuin hän tuli Israelin kuninkaaksi, ja hallitsi kaksi ajastaikaa; ainoastaan Juudan huone piti Davidin kanssa.","Ja Isboset Saulin poika oli neljänkymmenen ajastaikainen, kuin hän tuli Israelin kuninkaaksi, ja hallitsi kaksi ajastaikaa; ainoastaan Juudan huone piti Davidin kanssa."],[2,11,"Ja se aika, jonka David oli Hebronissa Juudan huoneen kuninkaana, oli seitsemän ajastaikaa ja kuusi kuukautta.","Ja se aika, jonka David oli Hebronissa Juudan huoneen kuninkaana, oli seitsemän ajastaikaa ja kuusi kuukautta."],[2,12,"Ja Abner Nerin poika läksi ulos Isbosetin Saulin pojan palveliain kanssa Mahanaimista Gibeoniin.","Ja Abner Nerin poika läksi ulos Isbosetin Saulin pojan palveliain kanssa Mahanaimista Gibeoniin."],[2,13,"Ja Joab, Zerujan poika, ja Davidin palveliat läksivät ulos, ja he kohtasivat toisensa Gibeonin lammikon tykönä, ja seisoivat toinen toistansa vastaan, nämät tällä puolella ja toiset toisella puolella lammikkoa.","Ja Joab, Zerujan poika, ja Davidin palveliat läksivät ulos, ja he kohtasivat toisensa Gibeonin lammikon tykönä, ja seisoivat toinen toistansa vastaan, nämät tällä puolella ja toiset toisella puolella lammikkoa."],[2,14,"Ja Abner sanoi Joabille: nouskaan nuorukaiset meidän eteemme leikitsemään. Joab sanoi: tehkään niin.","Ja Abner sanoi Joabille: nouskaan nuorukaiset meidän eteemme leikitsemään. Joab sanoi: tehkään niin."],[2,15,"Niin he nousivat ja kävivät kaksitoistakymmentä BenJaminin luvusta Isbosetin Saulin pojan puolelta, ja kaksitoistakymmentä Davidin palvelioista edes.","Niin he nousivat ja kävivät kaksitoistakymmentä BenJaminin luvusta Isbosetin Saulin pojan puolelta, ja kaksitoistakymmentä Davidin palvelioista edes."],[2,16,"Ja jokainen heistä otti toinen toisensa kiinni kaulasta, ja pistivät miekkansa kylkiin, ja lankesivat toinen toisensa kanssa maahan. Siitä kutsutaan se paikka Helkat-Hatsurim, joka on Gibeonissa.","Ja jokainen heistä otti toinen toisensa kiinni kaulasta, ja pistivät miekkansa kylkiin, ja lankesivat toinen toisensa kanssa maahan. Siitä kutsutaan se paikka Helkat-Hatsurim, joka on Gibeonissa."],[2,17,"Ja sangen kova sota nousi sinä päivänä; mutta Abner ja Israelin miehet lyötiin Davidin palvelioilta takaperin.","Ja sangen kova sota nousi sinä päivänä; mutta Abner ja Israelin miehet lyötiin Davidin palvelioilta takaperin."],[2,18,"Ja kolme ZeruJan poikaa oli siellä: Joab, Abisai ja Asahel; mutta Asahel oli nopia juoksemaan, niinkuin metsävuohi kedolla.","Ja kolme ZeruJan poikaa oli siellä: Joab, Abisai ja Asahel; mutta Asahel oli nopia juoksemaan, niinkuin metsävuohi kedolla."],[2,19,"Hän ajoi Abneria takaa, ja ei poikennut oikialle eikä vasemmalle puolelle ajamasta Abneria takaa.","Hän ajoi Abneria takaa, ja ei poikennut oikialle eikä vasemmalle puolelle ajamasta Abneria takaa."],[2,20,"Niin Abner katsoi taaksensa ja sanoi: etkö sinä ole Asahel? Hän sanoi: olen.","Niin Abner katsoi taaksensa ja sanoi: etkö sinä ole Asahel? Hän sanoi: olen."],[2,21,"Ja Abner sanoi: pakene minun tyköäni oikialle eli vasemmalle puolelle, ja käsitä sinulles yksi noista nuorukaisista, ja ota sen ase. Mutta Asahel ei tahtonut luopua hänestä.","Ja Abner sanoi: pakene minun tyköäni oikialle eli vasemmalle puolelle, ja käsitä sinulles yksi noista nuorukaisista, ja ota sen ase. Mutta Asahel ei tahtonut luopua hänestä."],[2,22,"Niin Abner taas puhui Asahelille: pakene minun takaani: miksis tahdot minua lyömään sinuas? ja kuinka minä sitte tohdin nostaa kasvoni Joabin sinun veljes edessä?","Niin Abner taas puhui Asahelille: pakene minun takaani: miksis tahdot minua lyömään sinuas? ja kuinka minä sitte tohdin nostaa kasvoni Joabin sinun veljes edessä?"],[2,23,"Mutta hän ei paennut; ja Abner pisti häntä takamaisella puolella keihäästä hänen vatsaansa, niin että keihäs kävi takaa ulos, ja hän lankesi siihen ja kuoli hänen eteensä. Ja jokainen, joka siihen paikkaan tuli, kussa Asahel kaatunut ja kuolleena oli, seisahti siihen.","Mutta hän ei paennut; ja Abner pisti häntä takamaisella puolella keihäästä hänen vatsaansa, niin että keihäs kävi takaa ulos, ja hän lankesi siihen ja kuoli hänen eteensä. Ja jokainen, joka siihen paikkaan tuli, kussa Asahel kaatunut ja kuolleena oli, seisahti siihen."],[2,24,"Mutta Joab ja Abisai ajoivat Abneria takaa siihen asti kuin päivä laski. Ja kuin he tulivat Amman kukkulalle, joka on Gian tykönä, Gibeonin korven tiellä,","Mutta Joab ja Abisai ajoivat Abneria takaa siihen asti kuin päivä laski. Ja kuin he tulivat Amman kukkulalle, joka on Gian tykönä, Gibeonin korven tiellä,"],[2,25,"Silloin tulivat BenJaminin lapset Abnerin takaa kokoon ja kokosivat itsensä yhteen joukkoon, ja seisahtivat mäen kukkulalle.","Silloin tulivat BenJaminin lapset Abnerin takaa kokoon ja kokosivat itsensä yhteen joukkoon, ja seisahtivat mäen kukkulalle."],[2,26,"Ja Abner huusi Joabia ja sanoi: pitääkö miekan syömän ilman lakkaamata? Etkös tiedä, että siitä tulee enempi katkeruutta? Kuinka kauvan et sinä tahdo sanoa kansalle, että he lakkaisivat vainoomasta veljiänsä?","Ja Abner huusi Joabia ja sanoi: pitääkö miekan syömän ilman lakkaamata? Etkös tiedä, että siitä tulee enempi katkeruutta? Kuinka kauvan et sinä tahdo sanoa kansalle, että he lakkaisivat vainoomasta veljiänsä?"],[2,27,"Joab vastasi: niin totta kuin Jumala elää, jos sinä olisit (ennen) niin sanonut, niin olis kansa tänäpänä jo varhain lakannut vainoomasta kukin veljeänsä!","Joab vastasi: niin totta kuin Jumala elää, jos sinä olisit (ennen) niin sanonut, niin olis kansa tänäpänä jo varhain lakannut vainoomasta kukin veljeänsä!"],[2,28,"Ja Joab puhalsi torveen, ja kaikki kansa seisahti alallensa, ja ei enää ajaneet Israelia takaa eikä myös enää sotineet.","Ja Joab puhalsi torveen, ja kaikki kansa seisahti alallensa, ja ei enää ajaneet Israelia takaa eikä myös enää sotineet."],[2,29,"Mutta Abner ja hänen miehensä kävivät kaiken yötä lakialla kedolla ja menivät Jordanin ylitse, vaelsivat kaiken Bitronin lävitse ja tulivat Mahanaimiin.","Mutta Abner ja hänen miehensä kävivät kaiken yötä lakialla kedolla ja menivät Jordanin ylitse, vaelsivat kaiken Bitronin lävitse ja tulivat Mahanaimiin."],[2,30,"Ja Joab käänsi itsensä Abnerista ja kokosi kaiken kansan; ja siinä kaivattiin Davidin palvelioista yhdeksäntoistakymmentä miestä ja Asahel.","Ja Joab käänsi itsensä Abnerista ja kokosi kaiken kansan; ja siinä kaivattiin Davidin palvelioista yhdeksäntoistakymmentä miestä ja Asahel."],[2,31,"Mutta Davidin palveliat olivat lyöneet BenJaminilta ja niistä miehistä, jotka olivat Abnerin kanssa, kolmesataa ja kuusikymmentä miestä, jotka kuolivat.","Mutta Davidin palveliat olivat lyöneet BenJaminilta ja niistä miehistä, jotka olivat Abnerin kanssa, kolmesataa ja kuusikymmentä miestä, jotka kuolivat."],[2,32,"Ja he ottivat Asahelin ja hautasivat Betlehemiin, hänen isänsä hautaan; ja Joab kävi miehinensä kaiken sen yön ja tuli päivän valjetessa Hebroniin.","Ja he ottivat Asahelin ja hautasivat Betlehemiin, hänen isänsä hautaan; ja Joab kävi miehinensä kaiken sen yön ja tuli päivän valjetessa Hebroniin."],[3,1,"Ja pitkällinen sota oli Saulin huoneen ja Davidin huoneen vaiheella; mutta David kasvoi ja menestyi, ja Saulin huone hävisi ja väheni.","Ja pitkällinen sota oli Saulin huoneen ja Davidin huoneen vaiheella; mutta David kasvoi ja menestyi, ja Saulin huone hävisi ja väheni."],[3,2,"Ja Davidille syntyi lapsia Hebronissa; hänen esikoisensa oli Amnon Ahinoamista Jisreeliläisestä.","Ja Davidille syntyi lapsia Hebronissa; hänen esikoisensa oli Amnon Ahinoamista Jisreeliläisestä."],[3,3,"Toinen Kileab Abigailista Nabalin emännästä, joka oli Karmelista; kolmas Absalom Maakan poika kuninkaan Talmain tyttären Gessurista;","Toinen Kileab Abigailista Nabalin emännästä, joka oli Karmelista; kolmas Absalom Maakan poika kuninkaan Talmain tyttären Gessurista;"],[3,4,"Neljäs Adonia Haggitin poika; viides Sephatja Abitalin poika;","Neljäs Adonia Haggitin poika; viides Sephatja Abitalin poika;"],[3,5,"Kuudes Jitream Eglasta Davidin emännästä; nämä syntyivät Davidille Hebronissa.","Kuudes Jitream Eglasta Davidin emännästä; nämä syntyivät Davidille Hebronissa."],[3,6,"Kuin sota oli Saulin huoneeen ja Davidin huoneen vaiheella, vahvisti Abner itsensä Saulin huoneessa.","Kuin sota oli Saulin huoneeen ja Davidin huoneen vaiheella, vahvisti Abner itsensä Saulin huoneessa."],[3,7,"Ja Saulilla oli ollut jalkavaimo, Ritspa nimeltä, Aijan tytär, ja (Isboset) sanoi Abnerille: miksis olet mennyt isäni jalkavaimon tykö?","Ja Saulilla oli ollut jalkavaimo, Ritspa nimeltä, Aijan tytär, ja (Isboset) sanoi Abnerille: miksis olet mennyt isäni jalkavaimon tykö?"],[3,8,"Niin Abner vihastui suuresti Isbosetin sanoista ja sanoi: olenko minä koiran pää, joka Juudaa vastaan tein tänäpänä laupiuden sinun isäs Saulin huoneelle, ja hänen veljillensä ja ystävillensä, ja en ole antanut sinua Davidin käsiin! ja sinä soimaat minua tänäpänä vaimon tähden pahantekiäksi?","Niin Abner vihastui suuresti Isbosetin sanoista ja sanoi: olenko minä koiran pää, joka Juudaa vastaan tein tänäpänä laupiuden sinun isäs Saulin huoneelle, ja hänen veljillensä ja ystävillensä, ja en ole antanut sinua Davidin käsiin! ja sinä soimaat minua tänäpänä vaimon tähden pahantekiäksi?"],[3,9,"Jumala tehköön Abnerin kanssa sen ja sen, jos minä en tee, niinkuin Herra on vannonut Davidille:","Jumala tehköön Abnerin kanssa sen ja sen, jos minä en tee, niinkuin Herra on vannonut Davidille:"],[3,10,"Että minä otan kuninkaan valtakunnan Saulin huoneesta pois, ja ylennän Davidin istuimen Israelin ja Juudan ylitse, Danista Bersebaan asti.","Että minä otan kuninkaan valtakunnan Saulin huoneesta pois, ja ylennän Davidin istuimen Israelin ja Juudan ylitse, Danista Bersebaan asti."],[3,11,"Ja ei hän taitanut Abneria enää vastata yhtään sanaa; sillä hän pelkäsi häntä.","Ja ei hän taitanut Abneria enää vastata yhtään sanaa; sillä hän pelkäsi häntä."],[3,12,"Ja Abner lähetti sanansaattajat edellänsä Davidin tykö, sanoen: kenenkä maa oma on? ja sanoi: tee liitto minun kanssani, ja katso, minun käteni on sinun kanssas, kääntämään kaikkea Israelia sinun tykös.","Ja Abner lähetti sanansaattajat edellänsä Davidin tykö, sanoen: kenenkä maa oma on? ja sanoi: tee liitto minun kanssani, ja katso, minun käteni on sinun kanssas, kääntämään kaikkea Israelia sinun tykös."],[3,13,"Hän sanoi: oikein, minä teen liiton sinun kanssas; mutta yhtä anon minä sinulta, sanoen: ei pidä sinun tuleman minun näkyviini ennen kuin sinä tuot Mikalin Saulin tyttären minun tyköni, tullessas katsomaan kasvojani.","Hän sanoi: oikein, minä teen liiton sinun kanssas; mutta yhtä anon minä sinulta, sanoen: ei pidä sinun tuleman minun näkyviini ennen kuin sinä tuot Mikalin Saulin tyttären minun tyköni, tullessas katsomaan kasvojani."],[3,14,"Lähetti myös David sanansaattajat Isbosetin Saulin pojan tykö ja antoi hänelle sanoa: anna minulle minun emäntäni Mikal, jonka minä kihlasin minulleni sadalla Philistealaisten esinahalla.","Lähetti myös David sanansaattajat Isbosetin Saulin pojan tykö ja antoi hänelle sanoa: anna minulle minun emäntäni Mikal, jonka minä kihlasin minulleni sadalla Philistealaisten esinahalla."],[3,15,"Isboset lähetti matkaan ja antoi ottaa hänen mieheltänsä Paltielilta Laiksen pojalta pois.","Isboset lähetti matkaan ja antoi ottaa hänen mieheltänsä Paltielilta Laiksen pojalta pois."],[3,16,"Ja hänen miehensä meni hänen kanssansa, hän kävi ja itki hänen jälissänsä hamaan Bahurimiin asti. Niin sanoi Abner hänelle: palaja ja mene matkaas. Ja hän palasi.","Ja hänen miehensä meni hänen kanssansa, hän kävi ja itki hänen jälissänsä hamaan Bahurimiin asti. Niin sanoi Abner hänelle: palaja ja mene matkaas. Ja hän palasi."],[3,17,"Ja Abner puhui Israelin vanhimmille ja sanoi: te olette jo kauvan aikaa halunneet Davidia kuninkaaksenne.","Ja Abner puhui Israelin vanhimmille ja sanoi: te olette jo kauvan aikaa halunneet Davidia kuninkaaksenne."],[3,18,"Niin tehkäät nyt se; sillä Herra on sanonut Davidista; minä vapahdan minun kansani Israelin palveliani Davidin käden kautta Philistealaisten kädestä ja kaikkein heidän vihollistensa kädestä.","Niin tehkäät nyt se; sillä Herra on sanonut Davidista; minä vapahdan minun kansani Israelin palveliani Davidin käden kautta Philistealaisten kädestä ja kaikkein heidän vihollistensa kädestä."],[3,19,"Puhui myös Abner BenJaminin korvain kuullen, ja meni myös puhumaan Davidin korville Hebroniin kaikkia mikä Israelille ja kaikelle BenJaminin huoneelle kelpasi.","Puhui myös Abner BenJaminin korvain kuullen, ja meni myös puhumaan Davidin korville Hebroniin kaikkia mikä Israelille ja kaikelle BenJaminin huoneelle kelpasi."],[3,20,"Kuin Abner tuli Davidin tykö Hebroniin ja kaksikymmentä miestä hänen kanssansa, teki David pidot Abnerille ja niille miehille, jotka hänen kanssansa olivat.","Kuin Abner tuli Davidin tykö Hebroniin ja kaksikymmentä miestä hänen kanssansa, teki David pidot Abnerille ja niille miehille, jotka hänen kanssansa olivat."],[3,21,"Ja Abner sanoi Davidille: minä nousen ja menen kokoomaan kaiken Israelin herrani kuninkaan tykö, että he tekisivät liiton sinun kanssas, ja sinä olisit kuningas niinkuin sinun sielus halajaa. Niin David päästi Abnerin menemään rauhassa.","Ja Abner sanoi Davidille: minä nousen ja menen kokoomaan kaiken Israelin herrani kuninkaan tykö, että he tekisivät liiton sinun kanssas, ja sinä olisit kuningas niinkuin sinun sielus halajaa. Niin David päästi Abnerin menemään rauhassa."],[3,22,"Ja katso, Davidin palveliat ja Joab tulivat sotaväen tyköä ja toivat kanssansa suuren saaliin; mutta Abner ei ollut silloin Davidin tykönä Hebronissa, sillä hän oli päästänyt hänen menemään rauhassa.","Ja katso, Davidin palveliat ja Joab tulivat sotaväen tyköä ja toivat kanssansa suuren saaliin; mutta Abner ei ollut silloin Davidin tykönä Hebronissa, sillä hän oli päästänyt hänen menemään rauhassa."],[3,23,"Kuin Joab ja kaikki sotajoukko olivat tulleet, sanottiin Joabille, sanoen: Abner Nerin poika on tullut kuninkaan tykö, ja hän on päästänyt hänet rauhassa menemään.","Kuin Joab ja kaikki sotajoukko olivat tulleet, sanottiin Joabille, sanoen: Abner Nerin poika on tullut kuninkaan tykö, ja hän on päästänyt hänet rauhassa menemään."],[3,24,"Niin meni Joab kuninkaan tykö ja sanoi: mitäs olet tehnyt? Katso, Abner on tullut sinun tykös: miksis olet hänen päästänyt vapaasti menemään?","Niin meni Joab kuninkaan tykö ja sanoi: mitäs olet tehnyt? Katso, Abner on tullut sinun tykös: miksis olet hänen päästänyt vapaasti menemään?"],[3,25,"Etkös tunne Abneria Nerin poikaa? Hän on tullut sinua pettämään tiedustellaksensa ulos- ja sisällekäymistäs ja koetellaksensa kaikkia, mitäs teet.","Etkös tunne Abneria Nerin poikaa? Hän on tullut sinua pettämään tiedustellaksensa ulos- ja sisällekäymistäs ja koetellaksensa kaikkia, mitäs teet."],[3,26,"Ja kuin Joab läksi Davidin tyköä, lähetti hän sanansaattajat Abnerin perään, ja he toivat hänen Borhasirasta; ja ei David siitä mitään tietänyt.","Ja kuin Joab läksi Davidin tyköä, lähetti hän sanansaattajat Abnerin perään, ja he toivat hänen Borhasirasta; ja ei David siitä mitään tietänyt."],[3,27,"Kuin Abner tuli Hebroniin jälleen, vei Joab hänet keskelle porttia puhutellaksensa häntä erinänsä, ja pisti siellä häntä vatsaan, niin että hän kuoli, veljensä Asahelin veren tähden.","Kuin Abner tuli Hebroniin jälleen, vei Joab hänet keskelle porttia puhutellaksensa häntä erinänsä, ja pisti siellä häntä vatsaan, niin että hän kuoli, veljensä Asahelin veren tähden."],[3,28,"Kuin David sai sen tietää, sanoi hän: minä olen viatoin ja minun valtakuntani Herran edessä ijankaikkisesti Abnerin Nerin pojan verestä.","Kuin David sai sen tietää, sanoi hän: minä olen viatoin ja minun valtakuntani Herran edessä ijankaikkisesti Abnerin Nerin pojan verestä."],[3,29,"Mutta tulkoon se Joabin pään päälle ja kaiken hänen isänsä huoneen, ja älköön puuttuko Joabin huoneessa se, jolla juoksu ja spitali on, ja joka sauvalla käy ja miekalla kaatuu, ja jolta leipä puuttuu.","Mutta tulkoon se Joabin pään päälle ja kaiken hänen isänsä huoneen, ja älköön puuttuko Joabin huoneessa se, jolla juoksu ja spitali on, ja joka sauvalla käy ja miekalla kaatuu, ja jolta leipä puuttuu."],[3,30,"Ja näin tappoivat Joab ja hänen veljensä Abisai Abnerin, että hän löi kuoliaaksi Asahelin heidän veljensä sodassa Gibeonin tykönä.","Ja näin tappoivat Joab ja hänen veljensä Abisai Abnerin, että hän löi kuoliaaksi Asahelin heidän veljensä sodassa Gibeonin tykönä."],[3,31,"Mutta David sanoi Joabille ja kaikelle kansalle, jotka olivat hänen kanssansa: reväiskää vaatteenne rikki, ja puettakaat teitänne säkeillä, ja valittakaat Abnerin tähden. Ja kuningas David kävi paarien perässä.","Mutta David sanoi Joabille ja kaikelle kansalle, jotka olivat hänen kanssansa: reväiskää vaatteenne rikki, ja puettakaat teitänne säkeillä, ja valittakaat Abnerin tähden. Ja kuningas David kävi paarien perässä."],[3,32,"Ja he hautasivat Abnerin Hebronissa, ja kuningas koroitti äänensä ja itki Abnerin haudan tykönä; itki myös kaikki kansa.","Ja he hautasivat Abnerin Hebronissa, ja kuningas koroitti äänensä ja itki Abnerin haudan tykönä; itki myös kaikki kansa."],[3,33,"Ja kuningas valitti Abneria ja sanoi: onko Abner kuollut, niinkuin tyhmä kuolee?","Ja kuningas valitti Abneria ja sanoi: onko Abner kuollut, niinkuin tyhmä kuolee?"],[3,34,"Sinun kätes ei olleet sidotut, sinun jalkas ei olleet vaskikahleissa: sinä olet kaatunut, niinkuin se, joka pahantekiäin edessä lankee. Ja kaikki kansa itki vielä enemmin häntä.","Sinun kätes ei olleet sidotut, sinun jalkas ei olleet vaskikahleissa: sinä olet kaatunut, niinkuin se, joka pahantekiäin edessä lankee. Ja kaikki kansa itki vielä enemmin häntä."],[3,35,"Ja kaikki kansa tuli Davidin kanssa rualle, kuin vielä valkia päivä oli; ja David vannoi ja sanoi: Jumala tehköön minulle sen ja sen, jos minä leipää taikka jotakin muuta maistan, ennenkuin aurinko laskee.","Ja kaikki kansa tuli Davidin kanssa rualle, kuin vielä valkia päivä oli; ja David vannoi ja sanoi: Jumala tehköön minulle sen ja sen, jos minä leipää taikka jotakin muuta maistan, ennenkuin aurinko laskee."],[3,36,"Ja kaikki kansa ymmärsi sen, ja se kelpasi heille, ja kaikki se hyvä minkä kuningas oli tehnyt kaiken kansan silmäin edessä.","Ja kaikki kansa ymmärsi sen, ja se kelpasi heille, ja kaikki se hyvä minkä kuningas oli tehnyt kaiken kansan silmäin edessä."],[3,37,"Ja kaikki kansa ja koko Israel ymmärsivät sinä päivänä, ettei se ollut kuninkaalta, että Abner Nerin poika oli tapettu.","Ja kaikki kansa ja koko Israel ymmärsivät sinä päivänä, ettei se ollut kuninkaalta, että Abner Nerin poika oli tapettu."],[3,38,"Ja kuningas sanoi palvelioillensa: ettekö te tiedä, että tänäpänä on yksi päämies, ja tosin suuri mies kaatunut Israelissa?","Ja kuningas sanoi palvelioillensa: ettekö te tiedä, että tänäpänä on yksi päämies, ja tosin suuri mies kaatunut Israelissa?"],[3,39,"Ja minä olen vielä heikko ja voideltu kuningas, mutta ne miehet ZeruJan pojat ovat kovemmat minua: Herra maksakoon sille, joka pahaa tekee, hänen pahuutensa jälkeen!","Ja minä olen vielä heikko ja voideltu kuningas, mutta ne miehet ZeruJan pojat ovat kovemmat minua: Herra maksakoon sille, joka pahaa tekee, hänen pahuutensa jälkeen!"],[4,1,"Kuin Saulin poika kuuli Abnerin kuolleeksi Hebronissa, väsyivät hänen kätensä, ja koko Israel hämmästyi.","Kuin Saulin poika kuuli Abnerin kuolleeksi Hebronissa, väsyivät hänen kätensä, ja koko Israel hämmästyi."],[4,2,"Ja Saulin pojalla oli kaksi sotaväen päämiestä, toisen nimi oli Baana ja toisen Rekab, Rimmonin Berotilaisen pojat, BenJaminin lapsista; sillä Berot oli myös luettu BenJaminin sukukuntaan.","Ja Saulin pojalla oli kaksi sotaväen päämiestä, toisen nimi oli Baana ja toisen Rekab, Rimmonin Berotilaisen pojat, BenJaminin lapsista; sillä Berot oli myös luettu BenJaminin sukukuntaan."],[4,3,"Ja Berotilaiset olivat paenneet Gittaimiin, ja olivat siellä muukalaisina tähän päivään asti.","Ja Berotilaiset olivat paenneet Gittaimiin, ja olivat siellä muukalaisina tähän päivään asti."],[4,4,"Oli myös Jonatanilla Saulin pojalla yksi poika, joka oli saattamatoin jaloista, ja oli jo viiden ajastaikainen, kuin sanoma Saulista ja Jonatanista tuli Jisreelistä; ja hänen imettäjänsä otti hänen ja pakeni. Ja koska hän kiiruusti pakeni, lankesi hän ja tuli saattamattomaksi, ja hänen nimensä oli MephiBoset.","Oli myös Jonatanilla Saulin pojalla yksi poika, joka oli saattamatoin jaloista, ja oli jo viiden ajastaikainen, kuin sanoma Saulista ja Jonatanista tuli Jisreelistä; ja hänen imettäjänsä otti hänen ja pakeni. Ja koska hän kiiruusti pakeni, lankesi hän ja tuli saattamattomaksi, ja hänen nimensä oli MephiBoset."],[4,5,"Niin menivät Berotilaisen Rimmonin pojat Rekab ja Baana, ja tulivat Isbosetin huoneesen, kuin päivä oli palavimmallansa; ja hän lepäsi vuoteessansa puolipäivän aikana.","Niin menivät Berotilaisen Rimmonin pojat Rekab ja Baana, ja tulivat Isbosetin huoneesen, kuin päivä oli palavimmallansa; ja hän lepäsi vuoteessansa puolipäivän aikana."],[4,6,"Ja he tulivat keskelle huonetta nisuja ottamaan ja pistivät häntä vatsaan; ja Rekab ja Baana hänen veljensä pakenivat;","Ja he tulivat keskelle huonetta nisuja ottamaan ja pistivät häntä vatsaan; ja Rekab ja Baana hänen veljensä pakenivat;"],[4,7,"Sillä koska he huoneesen tulivat, lepäsi hän vuoteessansa, makaushuoneessansa. Ja he pistivät hänen kuoliaaksi, ja hakkasivat hänen päänsä pois, ja ottivat hänen päänsä ja menivät pois lakian kedon tien kautta koko sen yön,","Sillä koska he huoneesen tulivat, lepäsi hän vuoteessansa, makaushuoneessansa. Ja he pistivät hänen kuoliaaksi, ja hakkasivat hänen päänsä pois, ja ottivat hänen päänsä ja menivät pois lakian kedon tien kautta koko sen yön,"],[4,8,"Ja toivat Isbosetin pään Davidille, joka oli Hebronissa, ja sanoivat kuninkaalle: katso, tässä on Isbosetin Saulin pojan pää, sinun vihollises, joka sinun sielus perään seisoi: ja Herra on tänäpänä kostanut Saulille ja hänen siemenellensä herrani kuninkaan puolesta.","Ja toivat Isbosetin pään Davidille, joka oli Hebronissa, ja sanoivat kuninkaalle: katso, tässä on Isbosetin Saulin pojan pää, sinun vihollises, joka sinun sielus perään seisoi: ja Herra on tänäpänä kostanut Saulille ja hänen siemenellensä herrani kuninkaan puolesta."],[4,9,"Niin vastasi David Rekabia ja Baanaa, hänen veljeänsä, Rimmnonin Berotilaisen poikia, ja sanoi heille: niin totta kuin Herra elää, joka minun sieluni on vapahtanut kaikesta surusta;","Niin vastasi David Rekabia ja Baanaa, hänen veljeänsä, Rimmnonin Berotilaisen poikia, ja sanoi heille: niin totta kuin Herra elää, joka minun sieluni on vapahtanut kaikesta surusta;"],[4,10,"Sen joka minulle ilmoitti ja sanoi: Saul on kuollut, ja luuli itsensä hyväksi sanansaattajaksi, sen minä otin kiinni ja tapoin Ziklagissa, jolle minun piti antaman sanansaattajan palkan;","Sen joka minulle ilmoitti ja sanoi: Saul on kuollut, ja luuli itsensä hyväksi sanansaattajaksi, sen minä otin kiinni ja tapoin Ziklagissa, jolle minun piti antaman sanansaattajan palkan;"],[4,11,"Ja nämät jumalattomat miehet ovat tappaneet hurskaan miehen huoneessansa ja omassa vuoteessansa: eikö siis minun pitäisi nyt vaatiman hänen vertansa teidän kädestänne ja ottaman teitä pois maan päältä?","Ja nämät jumalattomat miehet ovat tappaneet hurskaan miehen huoneessansa ja omassa vuoteessansa: eikö siis minun pitäisi nyt vaatiman hänen vertansa teidän kädestänne ja ottaman teitä pois maan päältä?"],[4,12,"Ja David käski nuorukaisiansa, ja he tappoivat heidät, ja hakkasivat kädet ja jalat poikki, ja ripustivat heidät lammikon tykö Hebronissa. Mutta Isbosetin pään he ottivat ja hautasivat Abnerin hautaan Hebroniin.","Ja David käski nuorukaisiansa, ja he tappoivat heidät, ja hakkasivat kädet ja jalat poikki, ja ripustivat heidät lammikon tykö Hebronissa. Mutta Isbosetin pään he ottivat ja hautasivat Abnerin hautaan Hebroniin."],[5,1,"Ja Israelin kaikki sukukunnat tulivat Davidin tykö Hebroniin, ja puhuivat sanoen: katso, sinun luus ja lihas me olemme.","Ja Israelin kaikki sukukunnat tulivat Davidin tykö Hebroniin, ja puhuivat sanoen: katso, sinun luus ja lihas me olemme."],[5,2,"Ja aina ennen, kuin Saul oli meidän kuninkaamme, johdatit sinä Israelin ulos ja sisälle, ja Herra on sinulle sanonut: sinun pitää minun kansaani Israelia kaitseman ja Israelin päämiehen oleman.","Ja aina ennen, kuin Saul oli meidän kuninkaamme, johdatit sinä Israelin ulos ja sisälle, ja Herra on sinulle sanonut: sinun pitää minun kansaani Israelia kaitseman ja Israelin päämiehen oleman."],[5,3,"Ja kaikki kansan vanhimmat Israelista tulivat kuninkaan tykö Hebroniin, ja kuningas David teki heidän kanssansa liiton Herran edessä Hebronissa; ja he voitelivat Davidin Israelin kuninkaaksi.","Ja kaikki kansan vanhimmat Israelista tulivat kuninkaan tykö Hebroniin, ja kuningas David teki heidän kanssansa liiton Herran edessä Hebronissa; ja he voitelivat Davidin Israelin kuninkaaksi."],[5,4,"Ja David oli kolmenkymmenen ajastaikainen tullessansa kuninkaaksi, ja hän hallitsi neljäkymmentä ajastaikaa.","Ja David oli kolmenkymmenen ajastaikainen tullessansa kuninkaaksi, ja hän hallitsi neljäkymmentä ajastaikaa."],[5,5,"Hebronissa hän hallitsi Juudaa seitsemän vuotta ja kuusi kuukautta; mutta Jerusalemissa hän hallitsi kaikkea Israelia ja Juudaa kolmeneljättäkymmentä vuotta.","Hebronissa hän hallitsi Juudaa seitsemän vuotta ja kuusi kuukautta; mutta Jerusalemissa hän hallitsi kaikkea Israelia ja Juudaa kolmeneljättäkymmentä vuotta."],[5,6,"Ja kuningas meni ja hänen miehensä Jerusalemiin Jebusilaisia vastaan, jotka maalla asuivat. Ja he sanoivat Davidille: ei sinun pidä tänne tuleman, vaan sokiat ja ontuvat pitää sinun täältä pois ajaman; ja he ajattelivat, ettei Davidin pitänyt sinne tuleman.","Ja kuningas meni ja hänen miehensä Jerusalemiin Jebusilaisia vastaan, jotka maalla asuivat. Ja he sanoivat Davidille: ei sinun pidä tänne tuleman, vaan sokiat ja ontuvat pitää sinun täältä pois ajaman; ja he ajattelivat, ettei Davidin pitänyt sinne tuleman."],[5,7,"Mutta David voitti Zionin linnan, se on Davidin kaupunki.","Mutta David voitti Zionin linnan, se on Davidin kaupunki."],[5,8,"Ja sinä päivänä sanoi David: jos joku lyö Jebusilaiset, ja tarttuu heidän rästäänsä alaisiin ja lyö sokiat ja ontuvat, joita Davidin sielu vihaa (hänen pitää pään ja ylimmäisen oleman); josta heillä on sananlasku: ei yhtään sokiaa ja ontuvaa päästetä huoneesen.","Ja sinä päivänä sanoi David: jos joku lyö Jebusilaiset, ja tarttuu heidän rästäänsä alaisiin ja lyö sokiat ja ontuvat, joita Davidin sielu vihaa (hänen pitää pään ja ylimmäisen oleman); josta heillä on sananlasku: ei yhtään sokiaa ja ontuvaa päästetä huoneesen."],[5,9,"Ja David asui linnassa ja kutsui sen Davidin kaupungiksi; ja David rakensi sen ympäri Millosta, niin myös sisällisen puolen.","Ja David asui linnassa ja kutsui sen Davidin kaupungiksi; ja David rakensi sen ympäri Millosta, niin myös sisällisen puolen."],[5,10,"Ja David menestyi ja enentyi, ja Herra Jumala Zebaot oli hänen kanssansa.","Ja David menestyi ja enentyi, ja Herra Jumala Zebaot oli hänen kanssansa."],[5,11,"Niin Hiram, Tyron kuningas, lähetti sanansaattajat Davidin tykö, ja sedripuita, ja puuseppiä, ja seinäkivien hakkaajia, jotka rakensivat Davidin huoneen.","Niin Hiram, Tyron kuningas, lähetti sanansaattajat Davidin tykö, ja sedripuita, ja puuseppiä, ja seinäkivien hakkaajia, jotka rakensivat Davidin huoneen."],[5,12,"Ja David ymmärsi Herran vahvistaneeksi hänen Israelin kuninkaaksi ja korottaneeksi hänen valtakuntansa, kansansa Israelin tähden.","Ja David ymmärsi Herran vahvistaneeksi hänen Israelin kuninkaaksi ja korottaneeksi hänen valtakuntansa, kansansa Israelin tähden."],[5,13,"Niin David otti Jerusalemista vielä usiampia jalkavaimoja ja emäntiä, sittekuin hän tuli Hebronista. Ja Davidille syntyi vielä poikia ja tyttäriä.","Niin David otti Jerusalemista vielä usiampia jalkavaimoja ja emäntiä, sittekuin hän tuli Hebronista. Ja Davidille syntyi vielä poikia ja tyttäriä."],[5,14,"Ja nämät ovat heidän nimensä, jotka hänelle Jerusalemissa syntyivät: Sammua, Sobab, Natan ja Salomo,","Ja nämät ovat heidän nimensä, jotka hänelle Jerusalemissa syntyivät: Sammua, Sobab, Natan ja Salomo,"],[5,15,"Jibhar, Elisua, Nepheg ja Japhia,","Jibhar, Elisua, Nepheg ja Japhia,"],[5,16,"Elisama, Eliada ja Eliphalet.","Elisama, Eliada ja Eliphalet."],[5,17,"Ja kuin Philistealaiset kuulivat Davidin voidelluksi Israelin kuninkaaksi, nousivat kaikki Philistealaiset etsimään Davidia. Ja kuin David sen kuuli, niin hän meni linnaan.","Ja kuin Philistealaiset kuulivat Davidin voidelluksi Israelin kuninkaaksi, nousivat kaikki Philistealaiset etsimään Davidia. Ja kuin David sen kuuli, niin hän meni linnaan."],[5,18,"Mutta Philistealaiset tulivat ja sioittivat itsensä Rephaimin laaksoon.","Mutta Philistealaiset tulivat ja sioittivat itsensä Rephaimin laaksoon."],[5,19,"Ja David kysyi Herralta, sanoen: menenkö minä Philistealaisia vastaan? ja annatkos heitä minun käteeni? Ja Herra sanoi Davidille: mene, sillä minä annan tosin Philistealaiset sinun käsiis.","Ja David kysyi Herralta, sanoen: menenkö minä Philistealaisia vastaan? ja annatkos heitä minun käteeni? Ja Herra sanoi Davidille: mene, sillä minä annan tosin Philistealaiset sinun käsiis."],[5,20,"Ja David tuli BaalPeratsimiin, ja David löi heidät siinä, ja sanoi: Herra on minun viholliseni eroittanut minun edestäni, niinkuin vesi erkanee toinen toisestansa; siitä kutsutaan se paikka BaalPeratsim.","Ja David tuli BaalPeratsimiin, ja David löi heidät siinä, ja sanoi: Herra on minun viholliseni eroittanut minun edestäni, niinkuin vesi erkanee toinen toisestansa; siitä kutsutaan se paikka BaalPeratsim."],[5,21,"Ja he jättivät siihen epäjumalansa; mutta David ja hänen väkensä ottivat ne pois.","Ja he jättivät siihen epäjumalansa; mutta David ja hänen väkensä ottivat ne pois."],[5,22,"Ja Philistealaiset vielä nousivat ja sioittivat itsensä Rephaimin laaksoon.","Ja Philistealaiset vielä nousivat ja sioittivat itsensä Rephaimin laaksoon."],[5,23,"Niin David kysyi Herralta, ja hän vastasi: ei sinun pidä menemän alas, mutta tule takaa heidän ympärinsä, ettäs tulet heitä vastaan fikunapuiden kohdalla.","Niin David kysyi Herralta, ja hän vastasi: ei sinun pidä menemän alas, mutta tule takaa heidän ympärinsä, ettäs tulet heitä vastaan fikunapuiden kohdalla."],[5,24,"Ja kuin sinä kuulet fikunapuun latvat kahisevan, niin kulje; sillä Herra on silloin lähtenyt ulos sinun etees, lyömään Phlistealaisten sotajoukkoa.","Ja kuin sinä kuulet fikunapuun latvat kahisevan, niin kulje; sillä Herra on silloin lähtenyt ulos sinun etees, lyömään Phlistealaisten sotajoukkoa."],[5,25,"David teki niinkuin Herra oli hänelle käskenyt, ja löi Philistealaiset hamasta Gebasta siihenasti kuin Gaseriin tullaan,","David teki niinkuin Herra oli hänelle käskenyt, ja löi Philistealaiset hamasta Gebasta siihenasti kuin Gaseriin tullaan,"],[6,1,"Ja David taas kokosi kaikki valitut miehet Israelista, kolmekymmentä tuhatta,","Ja David taas kokosi kaikki valitut miehet Israelista, kolmekymmentä tuhatta,"],[6,2,"Ja David nousi ja meni, ja kaikki kansa kuin hänen tykönänsä oli Juudan asuvaisista, tuomaan sieltä Jumalan arkkia, joka kutsutaan Herran Zebaotin nimi, joka asuu Kerubimin päällä.","Ja David nousi ja meni, ja kaikki kansa kuin hänen tykönänsä oli Juudan asuvaisista, tuomaan sieltä Jumalan arkkia, joka kutsutaan Herran Zebaotin nimi, joka asuu Kerubimin päällä."],[6,3,"Ja he panivat Jumalan arkin uuden vaunun päälle ja toivat sen AbiNadabin huoneesta, joka asui Gibeassa. Mutta Ussa ja Ahjo, AbiNadabin pojat ajoivat sitä uutta vaunua.","Ja he panivat Jumalan arkin uuden vaunun päälle ja toivat sen AbiNadabin huoneesta, joka asui Gibeassa. Mutta Ussa ja Ahjo, AbiNadabin pojat ajoivat sitä uutta vaunua."],[6,4,"Niin he toivat sen AbiNadabin huoneesta, joka oli Gibeassa, Jumalan arkin kanssa; ja Ahjo kävi arkin edellä.","Niin he toivat sen AbiNadabin huoneesta, joka oli Gibeassa, Jumalan arkin kanssa; ja Ahjo kävi arkin edellä."],[6,5,"Niin David ja kaikki Israelin huone soittivat Herran edessä kaikkinaisilla honkaisilla kanteleilla ja harpuilla, psaltareilla, trumpuilla, kulkuisilla ja simpeleillä.","Niin David ja kaikki Israelin huone soittivat Herran edessä kaikkinaisilla honkaisilla kanteleilla ja harpuilla, psaltareilla, trumpuilla, kulkuisilla ja simpeleillä."],[6,6,"Ja kuin he tulivat Nahonin riihen tykö, otti Ussa Jumalan arkin ja piteli sitä, sillä härjät menivät sivuin tietä.","Ja kuin he tulivat Nahonin riihen tykö, otti Ussa Jumalan arkin ja piteli sitä, sillä härjät menivät sivuin tietä."],[6,7,"Niin Herran viha julmistui Ussan päälle, ja Jumala löi hänen siinä maahan hänen tyhmyytensä tähden, niin että hän kuoli siinä Jumalan arkin tykönä.","Niin Herran viha julmistui Ussan päälle, ja Jumala löi hänen siinä maahan hänen tyhmyytensä tähden, niin että hän kuoli siinä Jumalan arkin tykönä."],[6,8,"Silloin tuli David murheelliseksi, että Herra niin repäisi Ussan, ja kutsui sen paikan PeretsUssa, tähän päivään asti.","Silloin tuli David murheelliseksi, että Herra niin repäisi Ussan, ja kutsui sen paikan PeretsUssa, tähän päivään asti."],[6,9,"Ja David pelkäsi Herraa sinä päivänä ja sanoi: kuinka Herran arkki tulisi minun tyköni?","Ja David pelkäsi Herraa sinä päivänä ja sanoi: kuinka Herran arkki tulisi minun tyköni?"],[6,10,"Ja ei tahtonut antaa tuoda sitä tykönsä Davidin kaupunkiin, vaan salli kannettaa ObedEdomin Gatilaisen huoneesen.","Ja ei tahtonut antaa tuoda sitä tykönsä Davidin kaupunkiin, vaan salli kannettaa ObedEdomin Gatilaisen huoneesen."],[6,11,"Ja Herran arkki viipyi kolme kuukautta ObedEdomin Gatilaisen huoneessa, ja Herra siunasi hänen ja kaiken hänen huoneensa.","Ja Herran arkki viipyi kolme kuukautta ObedEdomin Gatilaisen huoneessa, ja Herra siunasi hänen ja kaiken hänen huoneensa."],[6,12,"Ja se oli sanottu kuningas Davidille, että Herra oli siunannut ObedEdomin huoneen ja kaiken mitä hänellä oli, Jumalan arkin tähden. Niin meni David ja toi Jumalan arkin ObedEdomin huoneesta Davidin kaupunkiin ilolla.","Ja se oli sanottu kuningas Davidille, että Herra oli siunannut ObedEdomin huoneen ja kaiken mitä hänellä oli, Jumalan arkin tähden. Niin meni David ja toi Jumalan arkin ObedEdomin huoneesta Davidin kaupunkiin ilolla."],[6,13,"Ja kuin ne, jotka Herran arkkia kantoivat, olivat käyneet kuusi askelta, niin uhrattiin härkä ja lihava lammas.","Ja kuin ne, jotka Herran arkkia kantoivat, olivat käyneet kuusi askelta, niin uhrattiin härkä ja lihava lammas."],[6,14,"Ja David hyppäsi kaikella voimalla Herran edessä ja hän oli vaatetettu liinaisella päällisvaatteella.","Ja David hyppäsi kaikella voimalla Herran edessä ja hän oli vaatetettu liinaisella päällisvaatteella."],[6,15,"Ja David ja kaikki Israelin kansa toivat Herran arkin riemulla Ja basunan helinällä.","Ja David ja kaikki Israelin kansa toivat Herran arkin riemulla Ja basunan helinällä."],[6,16,"Ja kuin Herran arkki joutui Davidin kaupunkiin, katsoi Mikal, Saulin tytär akkunasta ja näki kuningas Davidin hyppäävän kaikella voimallansa Herran edessä, ja hän katsoi hänen ylön sydämessänsä.","Ja kuin Herran arkki joutui Davidin kaupunkiin, katsoi Mikal, Saulin tytär akkunasta ja näki kuningas Davidin hyppäävän kaikella voimallansa Herran edessä, ja hän katsoi hänen ylön sydämessänsä."],[6,17,"Ja he toivat Herran arkin sisälle ja panivat sen siallensa keskelle majaa, jonka David oli sille rakentanut. Ja David uhrasi polttouhria ja kiitosuhria Herran edessä.","Ja he toivat Herran arkin sisälle ja panivat sen siallensa keskelle majaa, jonka David oli sille rakentanut. Ja David uhrasi polttouhria ja kiitosuhria Herran edessä."],[6,18,"Ja kuin David oli uhrannut polttouhria ja kiitosuhria, siunasi hän kansan Herran Zebaotin nimeen,","Ja kuin David oli uhrannut polttouhria ja kiitosuhria, siunasi hän kansan Herran Zebaotin nimeen,"],[6,19,"Ja jakoi kaikelle kansalle ja kaikelle Israelin seurakunnalle, miehille ja vaimoille, jokaiselle kyrsän leipää, ja kappaleen lihaa, ja mitan (viinaa); sitte meni kaikki kansa matkaansa, jokainen huoneesensa.","Ja jakoi kaikelle kansalle ja kaikelle Israelin seurakunnalle, miehille ja vaimoille, jokaiselle kyrsän leipää, ja kappaleen lihaa, ja mitan (viinaa); sitte meni kaikki kansa matkaansa, jokainen huoneesensa."],[6,20,"Ja kuin David palasi siunaamaan huonettansa, meni Mikal, Saulin tytär ulos häntä vastaan ja sanoi: kuinka jalo on ollut Israelin kuningas tänäpänä, joka on itsensä paljastanut palveliainsa piikain edessä, niinkuin irstaat ihmiset paljastavat itsensä!","Ja kuin David palasi siunaamaan huonettansa, meni Mikal, Saulin tytär ulos häntä vastaan ja sanoi: kuinka jalo on ollut Israelin kuningas tänäpänä, joka on itsensä paljastanut palveliainsa piikain edessä, niinkuin irstaat ihmiset paljastavat itsensä!"],[6,21,"Mutta David sanoi Mikalille: Herran edessä joka minun valinnut on pikemmin kuin sinun isäs ja kaiken hänen huoneensa, ja on käskenyt minun olla Herran kansan Israelin päämiehenä: ja Herran edessä minä tahdon iloita.","Mutta David sanoi Mikalille: Herran edessä joka minun valinnut on pikemmin kuin sinun isäs ja kaiken hänen huoneensa, ja on käskenyt minun olla Herran kansan Israelin päämiehenä: ja Herran edessä minä tahdon iloita."],[6,22,"Ja minä tahdon vielä halvempi olla ja nöyrä minun silmäini edessä: ja minä kunnioitetaan niiden piikain kanssa, joistas puhunut olet.","Ja minä tahdon vielä halvempi olla ja nöyrä minun silmäini edessä: ja minä kunnioitetaan niiden piikain kanssa, joistas puhunut olet."],[6,23,"Ja Mikalilla, Saulin tyttärellä ei ollut yhtään lasta kuolemapäiväänsä asti.","Ja Mikalilla, Saulin tyttärellä ei ollut yhtään lasta kuolemapäiväänsä asti."],[7,1,"Ja kuin kuningas istui huoneessansa, ja Herra oli hänelle antanut levon kaikilta hänen vihollisiltansa, ympäristöllä,","Ja kuin kuningas istui huoneessansa, ja Herra oli hänelle antanut levon kaikilta hänen vihollisiltansa, ympäristöllä,"],[7,2,"Sanoi kuningas propheta Natanille: katso, minä asun sedripuisessa huoneessa, ja Jumalan arkki asuu vaatetten keskellä.","Sanoi kuningas propheta Natanille: katso, minä asun sedripuisessa huoneessa, ja Jumalan arkki asuu vaatetten keskellä."],[7,3,"Natan sanoi kuninkaalle: mene ja tee kaikki mitä sydämessäs on, sillä Herra on sinun kanssas.","Natan sanoi kuninkaalle: mene ja tee kaikki mitä sydämessäs on, sillä Herra on sinun kanssas."],[7,4,"Mutta tapahtui sinä yönä, että Herran sana tuli Natan prophetan tykö ja sanoi:","Mutta tapahtui sinä yönä, että Herran sana tuli Natan prophetan tykö ja sanoi:"],[7,5,"Mene ja sano palvelialleni Davidille: Näin sanoo Herra: sinäkö minulle huoneen rakennat asuakseni?","Mene ja sano palvelialleni Davidille: Näin sanoo Herra: sinäkö minulle huoneen rakennat asuakseni?"],[7,6,"Sillä en minä ole asunut yhdessäkään huoneessa siitä päivästä, jona minä Israelin lapset johdatin Egyptistä, tähän päivään asti; vaan minä olen vaeltanut majoissa ja Tabernaklissa.","Sillä en minä ole asunut yhdessäkään huoneessa siitä päivästä, jona minä Israelin lapset johdatin Egyptistä, tähän päivään asti; vaan minä olen vaeltanut majoissa ja Tabernaklissa."],[7,7,"Kuhunka ikänä minä kaikkein Israelin lasten kanssa vaelsin, olenko minä ikänä puhunut jonkun kanssa Israelin suvusta, jolle minä olen käskenyt kaita minun kansaani Israelia ja sanonut: miksi ette ole minulle rakentaneet sedripuista huonetta?","Kuhunka ikänä minä kaikkein Israelin lasten kanssa vaelsin, olenko minä ikänä puhunut jonkun kanssa Israelin suvusta, jolle minä olen käskenyt kaita minun kansaani Israelia ja sanonut: miksi ette ole minulle rakentaneet sedripuista huonetta?"],[7,8,"Sano siis nyt palvelialleni Davidille: Näin sanoo Herra Zebaot: minä olen ottanut sinun lampurista kansani Israelin päämieheksi.","Sano siis nyt palvelialleni Davidille: Näin sanoo Herra Zebaot: minä olen ottanut sinun lampurista kansani Israelin päämieheksi."],[7,9,"Ja minä olen sinun kanssas ollut, kussa ikänä sinä olet käynyt, ja olen hävittänyt kaikki vihollises sinun edestäs, ja olen sinulle antanut suuren nimen niiden suurten nimien jälkeen kuin ovat maan päällä.","Ja minä olen sinun kanssas ollut, kussa ikänä sinä olet käynyt, ja olen hävittänyt kaikki vihollises sinun edestäs, ja olen sinulle antanut suuren nimen niiden suurten nimien jälkeen kuin ovat maan päällä."],[7,10,"Ja minä asetan Israelille minun kansalleni sian ja istutan hänen siinä asumaan, ettei hän enää kulkiana olisi; ja jumalattomat ei pidä häntä enää niinkuin ennen vaivaaman.","Ja minä asetan Israelille minun kansalleni sian ja istutan hänen siinä asumaan, ettei hän enää kulkiana olisi; ja jumalattomat ei pidä häntä enää niinkuin ennen vaivaaman."],[7,11,"Ja siitä päivästä, jona minä asetin tuomarit Israelille minun kansalleni, annoin minä sinulle levon kaikilta vihamiehiltäs; ja Herra ilmoittaa sinulle, että Herra sinulle huoneen tehdä tahtoo.","Ja siitä päivästä, jona minä asetin tuomarit Israelille minun kansalleni, annoin minä sinulle levon kaikilta vihamiehiltäs; ja Herra ilmoittaa sinulle, että Herra sinulle huoneen tehdä tahtoo."],[7,12,"Sittekuin sinun aikas on täytetty ja sinä lepäät isäis kanssa, herätän minä sinun siemenes sinun jälkees, joka sinun ruumiistas tuleva on: ja minä vahvistan hänen valtakuntansa.","Sittekuin sinun aikas on täytetty ja sinä lepäät isäis kanssa, herätän minä sinun siemenes sinun jälkees, joka sinun ruumiistas tuleva on: ja minä vahvistan hänen valtakuntansa."],[7,13,"Ja hän rakentaa minun nimelleni huoneen, ja minä vahvistan hänen vaItakuntansa istuimen ijankaikkisesti.","Ja hän rakentaa minun nimelleni huoneen, ja minä vahvistan hänen vaItakuntansa istuimen ijankaikkisesti."],[7,14,"Minä olen hänen isänsä, ja hän on minun poikani: kuin hän väärin tekee, rankaisen minä häntä ihmisen vitsalla ja ihmisten lasten haavoilla.","Minä olen hänen isänsä, ja hän on minun poikani: kuin hän väärin tekee, rankaisen minä häntä ihmisen vitsalla ja ihmisten lasten haavoilla."],[7,15,"Vaan minun laupiuteni ei pidä hänestä eriämän, niinkuin minä sen Saulista eroitin, jonka minä otin sinun edestäs pois.","Vaan minun laupiuteni ei pidä hänestä eriämän, niinkuin minä sen Saulista eroitin, jonka minä otin sinun edestäs pois."],[7,16,"Mutta sinun huonees ja valtakuntas on pysyvä sinun edessäs ijankaikkisesti, ja sinun istuimes pitää vahva oleman ijankaikkisesti.","Mutta sinun huonees ja valtakuntas on pysyvä sinun edessäs ijankaikkisesti, ja sinun istuimes pitää vahva oleman ijankaikkisesti."],[7,17,"Kaikkein näiden sanain jälkeen ja kaiken tämän näyn jälkeen puhui Natan Davidille.","Kaikkein näiden sanain jälkeen ja kaiken tämän näyn jälkeen puhui Natan Davidille."],[7,18,"Niin tuli kuningas David ja pysähtyi Herran eteen, ja sanoi: kuka olen minä, Herra, Herra, ja mikä on minun huoneeni, ettäs minun tähän asti saattanut olet;","Niin tuli kuningas David ja pysähtyi Herran eteen, ja sanoi: kuka olen minä, Herra, Herra, ja mikä on minun huoneeni, ettäs minun tähän asti saattanut olet;"],[7,19,"Ja olet sen vielä vähäksi lukenut, Herra, Herra, mutta olet myös puhunut palvelias huoneelle kaukaisista asioista: ja tämä on sen ihmisen laki, joka on Herra Jumala.","Ja olet sen vielä vähäksi lukenut, Herra, Herra, mutta olet myös puhunut palvelias huoneelle kaukaisista asioista: ja tämä on sen ihmisen laki, joka on Herra Jumala."],[7,20,"Ja mitä Davidin pitää enää sinun kanssas puhuman? sillä sinä tunnet palvelias, Herra, Herra.","Ja mitä Davidin pitää enää sinun kanssas puhuman? sillä sinä tunnet palvelias, Herra, Herra."],[7,21,"Sinun sanas tähden ja sydämes jälkeen olet sinä nämät suuret asiat tehnyt, ilmoittaakses palvelialles.","Sinun sanas tähden ja sydämes jälkeen olet sinä nämät suuret asiat tehnyt, ilmoittaakses palvelialles."],[7,22,"Sentähden olet sinä suuresti ylistetty, Herra Jumala! sillä ei yhtään ole sinun vertaas, ja ei ole yhtään Jumalaa paitsi sinua, kaiken sen jälkeen, kuin me olemme korvillamme kuulleet.","Sentähden olet sinä suuresti ylistetty, Herra Jumala! sillä ei yhtään ole sinun vertaas, ja ei ole yhtään Jumalaa paitsi sinua, kaiken sen jälkeen, kuin me olemme korvillamme kuulleet."],[7,23,"Ja kuka on niinkuin sinun kansas, niinkuin Israel, yksi kansa maan päällä, jota Jumala on mennyt vapahtamaan kansaksensa, ja toimittamaan itsellensä nimeä ja tekemään senkaltaisia suuria ja hirmuisia asioita sinun maallas, kansas edessä, jonka sinä sinulles vapahdit Egyptistä, pakanain ja heidän jumalainsa seasta.","Ja kuka on niinkuin sinun kansas, niinkuin Israel, yksi kansa maan päällä, jota Jumala on mennyt vapahtamaan kansaksensa, ja toimittamaan itsellensä nimeä ja tekemään senkaltaisia suuria ja hirmuisia asioita sinun maallas, kansas edessä, jonka sinä sinulles vapahdit Egyptistä, pakanain ja heidän jumalainsa seasta."],[7,24,"Ja sinä olet vahvistanut sinulles Israelin sinun kansakses ijankaikkisesti, ja sinä Herra olet heidän Jumalaksensa tullut.","Ja sinä olet vahvistanut sinulles Israelin sinun kansakses ijankaikkisesti, ja sinä Herra olet heidän Jumalaksensa tullut."],[7,25,"Niin vahvista siis, Herra Jumala, se sana ijankaikkisesti, jonkas palveliastas ja hänen huoneestansa puhunut olet, ja tee niin kuin puhunut olet.","Niin vahvista siis, Herra Jumala, se sana ijankaikkisesti, jonkas palveliastas ja hänen huoneestansa puhunut olet, ja tee niin kuin puhunut olet."],[7,26,"Niin sinun nimes tulee suureksi iankaikkisesta, että sanotaan: Herra Zebaot on Israelin Jumala, ja sinun palvelias Davidin huone on pysyväinen sinun edessäs.","Niin sinun nimes tulee suureksi iankaikkisesta, että sanotaan: Herra Zebaot on Israelin Jumala, ja sinun palvelias Davidin huone on pysyväinen sinun edessäs."],[7,27,"Sillä sinä Herra Zebaot Israelin Jumala olet avannut palvelias korvat, ja sanonut: minä rakennan sinulle huoneen; sentähden löysi palvelias sydämessänsä, että hän tämän rukouksen sinun tykönäs rukoilis.","Sillä sinä Herra Zebaot Israelin Jumala olet avannut palvelias korvat, ja sanonut: minä rakennan sinulle huoneen; sentähden löysi palvelias sydämessänsä, että hän tämän rukouksen sinun tykönäs rukoilis."],[7,28,"Sentähden nyt Herra, Herra, sinä olet Jumala, ja sinun sanas ovat totuus: sinä olet tämän hyvän puhunut palvelialles.","Sentähden nyt Herra, Herra, sinä olet Jumala, ja sinun sanas ovat totuus: sinä olet tämän hyvän puhunut palvelialles."],[7,29,"Niin rupee nyt siunaamaan palvelias huonetta, että se olis ijankaikkisesti sinun edessäs; sillä sinä Herra, Herra, olet sen puhunut, niin siunattakoon sinun siunauksellas palvelias huone ijankaikkisesti.","Niin rupee nyt siunaamaan palvelias huonetta, että se olis ijankaikkisesti sinun edessäs; sillä sinä Herra, Herra, olet sen puhunut, niin siunattakoon sinun siunauksellas palvelias huone ijankaikkisesti."],[8,1,"Ja sitte tapahtui, että David löi Philistealaiset ja alensi heitä; ja David otti orjuuden suitset Philistealaisten kädestä","Ja sitte tapahtui, että David löi Philistealaiset ja alensi heitä; ja David otti orjuuden suitset Philistealaisten kädestä"],[8,2,"Ja hän löi Moabilaiset, pani heidät maahan makaamaan ja mittasi heitä nuoralla: ja hän mittasi kaksi nuoraa tapettavaksi ja yhden nuoran elämään jätettäväksi, ja Moabilaiset tulivat Davidin palveliaksi, ja he kantoivat hänelle lahjoja.","Ja hän löi Moabilaiset, pani heidät maahan makaamaan ja mittasi heitä nuoralla: ja hän mittasi kaksi nuoraa tapettavaksi ja yhden nuoran elämään jätettäväksi, ja Moabilaiset tulivat Davidin palveliaksi, ja he kantoivat hänelle lahjoja."],[8,3,"David löi myös HadadEserin, Rehobin pojan Zoban kuninkaan, hänen mennessä asettamaan kättänsä Euphratin virran tykö.","David löi myös HadadEserin, Rehobin pojan Zoban kuninkaan, hänen mennessä asettamaan kättänsä Euphratin virran tykö."],[8,4,"Ja David otti heistä tuhannen ja seitsemänsataa hevosmiestä ja kaksikymmentä tuhatta jalkamiestä kiinni, ja raiskasi kaikki vaunuhevoset, ja sata vaunua jätti heistä.","Ja David otti heistä tuhannen ja seitsemänsataa hevosmiestä ja kaksikymmentä tuhatta jalkamiestä kiinni, ja raiskasi kaikki vaunuhevoset, ja sata vaunua jätti heistä."],[8,5,"Niin tulivat Syrialaiset Damaskusta auttamaan HadadEseriä, Zoban kuningasta; ja David löi Syrialaisista kaksikolmattakymmentä tuhatta miestä.","Niin tulivat Syrialaiset Damaskusta auttamaan HadadEseriä, Zoban kuningasta; ja David löi Syrialaisista kaksikolmattakymmentä tuhatta miestä."],[8,6,"Ja David asetti vartiat Syrian Damaskuun. Näin tulivat Syrialaiset Davidin palveliaksi ja kantoivat hänelle lahjoja; sillä Herra autti Davidia, kuhunka ikänä hän meni.","Ja David asetti vartiat Syrian Damaskuun. Näin tulivat Syrialaiset Davidin palveliaksi ja kantoivat hänelle lahjoja; sillä Herra autti Davidia, kuhunka ikänä hän meni."],[8,7,"Ja David otti HadadEserin palveliain kultaiset kilvet ja vei ne Jerusalemiin.","Ja David otti HadadEserin palveliain kultaiset kilvet ja vei ne Jerusalemiin."],[8,8,"Mutta Betasta ja Berotaista, HadadEserin kaupungeista, otti kuningas David ylen paljon vaskea.","Mutta Betasta ja Berotaista, HadadEserin kaupungeista, otti kuningas David ylen paljon vaskea."],[8,9,"Kuin Toi, Hamatin kuningas kuuli Davidin lyöneen kaikki HadadEserin sotaväen,","Kuin Toi, Hamatin kuningas kuuli Davidin lyöneen kaikki HadadEserin sotaväen,"],[8,10,"Lähetti hän poikansa Joramin kuningas Davidin tykö, tervehtimään häntä ystävällisesti ja siunaamaan häntä, että hän soti HadadEserin kanssa ja löi hänen; sillä Toi soti HadadEserin kanssa; ja hänen kädessänsä olivat hopiaiset, kultaiset ja vaskiset astiat.","Lähetti hän poikansa Joramin kuningas Davidin tykö, tervehtimään häntä ystävällisesti ja siunaamaan häntä, että hän soti HadadEserin kanssa ja löi hänen; sillä Toi soti HadadEserin kanssa; ja hänen kädessänsä olivat hopiaiset, kultaiset ja vaskiset astiat."],[8,11,"Ne myös kuningas David pyhitti Herralle, sen hopian ja kullan kanssa, jonka hän pyhitti Herralle kaikilta pakanoilta, jotka hän vaatinut oli allensa:","Ne myös kuningas David pyhitti Herralle, sen hopian ja kullan kanssa, jonka hän pyhitti Herralle kaikilta pakanoilta, jotka hän vaatinut oli allensa:"],[8,12,"Syriasta ja Moabista, Ammonin lapsilta, Philistealaisilta, Amalekilaisilta, niin myös HadadEserin, Rehobin pojan, Zoban kuninkaan saaliista.","Syriasta ja Moabista, Ammonin lapsilta, Philistealaisilta, Amalekilaisilta, niin myös HadadEserin, Rehobin pojan, Zoban kuninkaan saaliista."],[8,13,"Ja David teki itsensä kuuluisaksi, kuin hän palasi lyömästä Syrialaisia Suolalaaksossa, kahdeksantoistakymmentä tuhatta.","Ja David teki itsensä kuuluisaksi, kuin hän palasi lyömästä Syrialaisia Suolalaaksossa, kahdeksantoistakymmentä tuhatta."],[8,14,"Ja hän asetti vartiat koko Edomiin, ja koko Edom oli Davidin alla; sillä Herra autti Davidia, kuhunka ikänä hän meni.","Ja hän asetti vartiat koko Edomiin, ja koko Edom oli Davidin alla; sillä Herra autti Davidia, kuhunka ikänä hän meni."],[8,15,"Niin oli David kaiken Israelin kuningas, ja hän toimitti lain ja oikeuden kaikelle kansallensa.","Niin oli David kaiken Israelin kuningas, ja hän toimitti lain ja oikeuden kaikelle kansallensa."],[8,16,"Ja Joab, ZeruJan poika oli sotajoukon päällä, mutta Josaphat, Ahiludin poika oli kansleri.","Ja Joab, ZeruJan poika oli sotajoukon päällä, mutta Josaphat, Ahiludin poika oli kansleri."],[8,17,"Zadok, Ahitobin poika ja Ahimelek, AbJatarin poika olivat papit; Seraja oli kirjoittaja.","Zadok, Ahitobin poika ja Ahimelek, AbJatarin poika olivat papit; Seraja oli kirjoittaja."],[8,18,"Benaja, Jojadan poika oli Kretin ja Pletin päällä; ja Davidin pojat olivat papit.","Benaja, Jojadan poika oli Kretin ja Pletin päällä; ja Davidin pojat olivat papit."],[9,1,"Ja David sanoi: olleeko joku vielä jäänyt Saulin huoneesta, tehdäkseni laupiuden Jonatanin tähden hänelle.","Ja David sanoi: olleeko joku vielä jäänyt Saulin huoneesta, tehdäkseni laupiuden Jonatanin tähden hänelle."],[9,2,"Niin oli palvelia Saulin huoneesta Ziba nimeltä, sen kutsuivat Davidin tykö. Ja kuningas sanoi hänelle: oletkos Ziba? Hän sanoi: olen, sinun palvelias.","Niin oli palvelia Saulin huoneesta Ziba nimeltä, sen kutsuivat Davidin tykö. Ja kuningas sanoi hänelle: oletkos Ziba? Hän sanoi: olen, sinun palvelias."],[9,3,"Kuningas sanoi: onko vielä joku mies Saulin huoneesta, että minä Jumalan laupiuden tekisin hänelle? Ziba sanoi kuninkaalle: vielä on siellä Jonatanin poika, rampa jaloista.","Kuningas sanoi: onko vielä joku mies Saulin huoneesta, että minä Jumalan laupiuden tekisin hänelle? Ziba sanoi kuninkaalle: vielä on siellä Jonatanin poika, rampa jaloista."],[9,4,"Kuningas sanoi hänelle: kussa hän on? Ziba sanoi kuninkaalle: katso, hän on Lodabarissa, Makirin, Ammielin pojan huoneessa.","Kuningas sanoi hänelle: kussa hän on? Ziba sanoi kuninkaalle: katso, hän on Lodabarissa, Makirin, Ammielin pojan huoneessa."],[9,5,"Niin kuningas David lähetti ja antoi tuoda hänen Lodabarista, Makirin Ammielin pojan huoneesta.","Niin kuningas David lähetti ja antoi tuoda hänen Lodabarista, Makirin Ammielin pojan huoneesta."],[9,6,"Kuin MephiBoset, Saulin pojan Jonatanin poika tuli Davidin tykö, lankesi hän kasvoillensa ja kumarsi. Ja David sanoi: MephiBoset! Hän vastasi: tässä olen, sinun palvelias.","Kuin MephiBoset, Saulin pojan Jonatanin poika tuli Davidin tykö, lankesi hän kasvoillensa ja kumarsi. Ja David sanoi: MephiBoset! Hän vastasi: tässä olen, sinun palvelias."],[9,7,"David sanoi hänelle: älä pelkää; sillä minä totisesti teen laupiuden sinun kanssas Jonatanin sinun isäs tähden, ja minä annan sinulle kaikki sinun isäs Saulin pellot jälleen, ja sinä syöt jokapäivä leipää minun pöydältäni.","David sanoi hänelle: älä pelkää; sillä minä totisesti teen laupiuden sinun kanssas Jonatanin sinun isäs tähden, ja minä annan sinulle kaikki sinun isäs Saulin pellot jälleen, ja sinä syöt jokapäivä leipää minun pöydältäni."],[9,8,"Hän kumarsi ja sanoi: kuka olen minä sinun palvelias, ettäs käänsit sinus kuolleen koiran puoleen, niinkuin minä olen?","Hän kumarsi ja sanoi: kuka olen minä sinun palvelias, ettäs käänsit sinus kuolleen koiran puoleen, niinkuin minä olen?"],[9,9,"Niin kutsui kuningas Ziban, Saulin palvelian, ja sanoi hänelle: minä olen antanut sinun herras pojalle kaiken sen mikä Saulin oma on ollut ja koko hänen huoneensa oma.","Niin kutsui kuningas Ziban, Saulin palvelian, ja sanoi hänelle: minä olen antanut sinun herras pojalle kaiken sen mikä Saulin oma on ollut ja koko hänen huoneensa oma."],[9,10,"Niin pitää sinun, ja sinun lapses, ja palvelias viljelemän hänen peltojansa ja korjaaman herras pojalle leiväksi ja ravinnoksi. Mutta MephiBoset sinun herras poika syö jokapäivä leipää minun pöydältäni. Ja Ziballa oli viisitoistakymmentä poikaa ja kaksikymmentä palveliaa.","Niin pitää sinun, ja sinun lapses, ja palvelias viljelemän hänen peltojansa ja korjaaman herras pojalle leiväksi ja ravinnoksi. Mutta MephiBoset sinun herras poika syö jokapäivä leipää minun pöydältäni. Ja Ziballa oli viisitoistakymmentä poikaa ja kaksikymmentä palveliaa."],[9,11,"Ja Ziba sanoi kuninkaalle: kaikki mitä minun herrani kuningas on palveliallensa käskenyt, tekee palvelias; ja MephiBoset syököön minun pöydältäni, niinkuin yksi kuninkaan lapsista.","Ja Ziba sanoi kuninkaalle: kaikki mitä minun herrani kuningas on palveliallensa käskenyt, tekee palvelias; ja MephiBoset syököön minun pöydältäni, niinkuin yksi kuninkaan lapsista."],[9,12,"Ja MephiBosetilla oli yksi vähä poika nimeltä Miika; mutta kaikki, jotka Ziban huoneesta olivat, olivat MephiBosetin palveliat.","Ja MephiBosetilla oli yksi vähä poika nimeltä Miika; mutta kaikki, jotka Ziban huoneesta olivat, olivat MephiBosetin palveliat."],[9,13,"Ja MephiBoset asui Jerusalemissa; sillä hän söi jokapäivä kuninkaan pöydältä; ja hän ontui molemmista jaloistansa.","Ja MephiBoset asui Jerusalemissa; sillä hän söi jokapäivä kuninkaan pöydältä; ja hän ontui molemmista jaloistansa."],[10,1,"Sitte tapahtui, että Ammonin lasten kuningas kuoli, ja hänen poikansa Hanun hallitsi hänen siassansa.","Sitte tapahtui, että Ammonin lasten kuningas kuoli, ja hänen poikansa Hanun hallitsi hänen siassansa."],[10,2,"Niin sanoi David: minä teen laupiuden Hanunin, Nahaksen pojan kanssa, niinkuin hänen isänsä teki laupiuden minun kanssani; ja lähetti palveliansa lohduttamaan häntä hänen isänsä tähden. Kuin Davidin palvelijat tulivat Ammonin lasten maahan,","Niin sanoi David: minä teen laupiuden Hanunin, Nahaksen pojan kanssa, niinkuin hänen isänsä teki laupiuden minun kanssani; ja lähetti palveliansa lohduttamaan häntä hänen isänsä tähden. Kuin Davidin palvelijat tulivat Ammonin lasten maahan,"],[10,3,"Niin sanoivat Ammonin lasten ylimmäiset herrallensa Hanunille: luuletkos Davidin kunnioittavan sinun isääs sinun silmäis edessä, että hän on lähettänyt lohduttajat sinun tykös? Etkös luule hänen lähettäneen palvelioitansa kaupunkia tutkistelemaan ja vakoomaan ja hävittämään?","Niin sanoivat Ammonin lasten ylimmäiset herrallensa Hanunille: luuletkos Davidin kunnioittavan sinun isääs sinun silmäis edessä, että hän on lähettänyt lohduttajat sinun tykös? Etkös luule hänen lähettäneen palvelioitansa kaupunkia tutkistelemaan ja vakoomaan ja hävittämään?"],[10,4,"Silloin otti Hanun Davidin palveliat, ja ajeli puolen heidän partaansa, ja leikkasi puolen heidän vaatteistansa liki suolivyöhön asti, ja laski heidät menemään.","Silloin otti Hanun Davidin palveliat, ja ajeli puolen heidän partaansa, ja leikkasi puolen heidän vaatteistansa liki suolivyöhön asti, ja laski heidät menemään."],[10,5,"Kuin se Davidille ilmoitettiin, lähetti hän heitä vastaan, sillä miehet olivat suuresti pilkatut; ja kuningas antoi heille sanottaa: olkaat Jerihossa siihen asti, kuin teidän partanne kasvaa, ja sitte tulkaat jälleen.","Kuin se Davidille ilmoitettiin, lähetti hän heitä vastaan, sillä miehet olivat suuresti pilkatut; ja kuningas antoi heille sanottaa: olkaat Jerihossa siihen asti, kuin teidän partanne kasvaa, ja sitte tulkaat jälleen."],[10,6,"Kuin Ammonin lapset näkivät itsensä haisevan Davidin edessä, lähettivät he ja palkkasivat Syrialaiset Rehobin huoneesta ja Zobasta, kaksikymmentä tuhatta jalkamiestä, ja kuningas Maakalta tuhannen miestä, ja Istobilta kaksitoista kymmentä tuhatta miestä.","Kuin Ammonin lapset näkivät itsensä haisevan Davidin edessä, lähettivät he ja palkkasivat Syrialaiset Rehobin huoneesta ja Zobasta, kaksikymmentä tuhatta jalkamiestä, ja kuningas Maakalta tuhannen miestä, ja Istobilta kaksitoista kymmentä tuhatta miestä."],[10,7,"Kuin David sen kuuli, lähetti hän Joabin koko urhoollisen sotajoukon kanssa.","Kuin David sen kuuli, lähetti hän Joabin koko urhoollisen sotajoukon kanssa."],[10,8,"Ja Ammonin lapset läksivät ja sääsivät sodan kaupungin portin eteen. Mutta Syrialaiset Zobasta, Rehobista, Istobista ja Maakasta olivat erinänsä kedolla.","Ja Ammonin lapset läksivät ja sääsivät sodan kaupungin portin eteen. Mutta Syrialaiset Zobasta, Rehobista, Istobista ja Maakasta olivat erinänsä kedolla."],[10,9,"Kuin Joab näki sodan asetetuksi vastaansa edestä ja takaa, valitsi hän kaikista Israelin parhaista miehistä, ja asetti itsensä Syrialaisia vastaan,","Kuin Joab näki sodan asetetuksi vastaansa edestä ja takaa, valitsi hän kaikista Israelin parhaista miehistä, ja asetti itsensä Syrialaisia vastaan,"],[10,10,"Ja muun väen antoi hän veljensä Abisain käden alle, joka asetti itsensä Ammonin lapsia vastaan.","Ja muun väen antoi hän veljensä Abisain käden alle, joka asetti itsensä Ammonin lapsia vastaan."],[10,11,"Ja hän sanoi: jos Syrialaiset tulevat minua voimallisemmaksi, niin tule minun avukseni; jos Ammonin lapset joutuvat sinua voimallisemmaksi, niin minä tulen sinun apuus.","Ja hän sanoi: jos Syrialaiset tulevat minua voimallisemmaksi, niin tule minun avukseni; jos Ammonin lapset joutuvat sinua voimallisemmaksi, niin minä tulen sinun apuus."],[10,12,"Ole miehuullinen, ja olkaamme vahvat meidän kansamme edestä ja meidän Jumalamme kaupunkein edestä; mutta Herra tehköön niinkuin hänelle kelvollinen on.","Ole miehuullinen, ja olkaamme vahvat meidän kansamme edestä ja meidän Jumalamme kaupunkein edestä; mutta Herra tehköön niinkuin hänelle kelvollinen on."],[10,13,"Ja Joab läksi matkaan ja se väki joka hänen kanssansa oli, sotimaan Syrialaisia vastaan; ja he pakenivat hänen edestänsä.","Ja Joab läksi matkaan ja se väki joka hänen kanssansa oli, sotimaan Syrialaisia vastaan; ja he pakenivat hänen edestänsä."],[10,14,"Ja kuin Ammonin lapset näkivät Syrialaiset pakenevan, pakenivat he myös Abisain edestä ja menivät kaupunkiin. Niin palasi Joab Ammonin lasten tyköä ja tuli Jerusalemiin.","Ja kuin Ammonin lapset näkivät Syrialaiset pakenevan, pakenivat he myös Abisain edestä ja menivät kaupunkiin. Niin palasi Joab Ammonin lasten tyköä ja tuli Jerusalemiin."],[10,15,"Ja kuin Syrialaiset näkivät itsensä Israelilta lyödyksi, kokoontuivat he yhteen.","Ja kuin Syrialaiset näkivät itsensä Israelilta lyödyksi, kokoontuivat he yhteen."],[10,16,"Ja HadadEser lähetti ja tuotti Syrialaiset toiselle puolelle veden, ja he tulivat Helamiin; ja Sobak, HadadEserin sodanpäämies meni heidän edellänsä.","Ja HadadEser lähetti ja tuotti Syrialaiset toiselle puolelle veden, ja he tulivat Helamiin; ja Sobak, HadadEserin sodanpäämies meni heidän edellänsä."],[10,17,"Kuin se Davidille ilmoitettiin, kokosi hän kaiken Israelin, ja meni Jordanin ylitse, ja tuli Helamiin; ja Syrialaiset asettivat itsensä Davidia vastaan sotimaan hänen kanssansa.","Kuin se Davidille ilmoitettiin, kokosi hän kaiken Israelin, ja meni Jordanin ylitse, ja tuli Helamiin; ja Syrialaiset asettivat itsensä Davidia vastaan sotimaan hänen kanssansa."],[10,18,"Mutta Syrialaiset pakenivat Israelin edestä, ja David löi heistä seitsemänsataa vaunua ja neljäkymmentä tuhatta ratsasmiestä, löi myös Sobakin sodanpäämiehen, että hän siinä kuoli.","Mutta Syrialaiset pakenivat Israelin edestä, ja David löi heistä seitsemänsataa vaunua ja neljäkymmentä tuhatta ratsasmiestä, löi myös Sobakin sodanpäämiehen, että hän siinä kuoli."],[10,19,"Kuin kaikki ne kuninkaat, jotka olivat HadadEserin alla, näkivät itsensä lyödyksi Israelilta, tekivät he Israelin kanssa rauhan, ja olivat heille alamaiset; ja Syrialaiset ei uskaltaneet Ammonin lapsia enää auttaa.","Kuin kaikki ne kuninkaat, jotka olivat HadadEserin alla, näkivät itsensä lyödyksi Israelilta, tekivät he Israelin kanssa rauhan, ja olivat heille alamaiset; ja Syrialaiset ei uskaltaneet Ammonin lapsia enää auttaa."],[11,1,"Ja kuin se aika joutui vuodesta, jolla kuningasten tapa oli sotiin mennä, lähetti David Joabin ja palveliansa hänen kanssansa ja kaiken Israelin, hukuttamaan Ammonin lapsia, ja he piirittivät Rabban; mutta David jäi Jerusalemiin.","Ja kuin se aika joutui vuodesta, jolla kuningasten tapa oli sotiin mennä, lähetti David Joabin ja palveliansa hänen kanssansa ja kaiken Israelin, hukuttamaan Ammonin lapsia, ja he piirittivät Rabban; mutta David jäi Jerusalemiin."],[11,2,"Ja tapahtui, että David ehtoopuolella nousi vuoteeltansa, ja käyskenteli kuninkaan huoneen katon päällä, ja näki katon päältä vaimon pesevän itsiänsä; ja vaimo oli sangen ihana näkyänsä.","Ja tapahtui, että David ehtoopuolella nousi vuoteeltansa, ja käyskenteli kuninkaan huoneen katon päällä, ja näki katon päältä vaimon pesevän itsiänsä; ja vaimo oli sangen ihana näkyänsä."],[11,3,"Ja David lähetti ja antoi kysyä vaimoa, ja sanoi: eikö tämä ole BatSeba, Eliamin tytär, Hetiläisen Urian emäntä.","Ja David lähetti ja antoi kysyä vaimoa, ja sanoi: eikö tämä ole BatSeba, Eliamin tytär, Hetiläisen Urian emäntä."],[11,4,"Ja David lähetti sanansaattajat ja antoi tuoda hänen. Ja kuin hän tuli hänen tykönsä, makasi hän hänen kanssansa; mutta hän puhdisti itsensä saastaisuudestansa, ja palasi huoneesensa.","Ja David lähetti sanansaattajat ja antoi tuoda hänen. Ja kuin hän tuli hänen tykönsä, makasi hän hänen kanssansa; mutta hän puhdisti itsensä saastaisuudestansa, ja palasi huoneesensa."],[11,5,"Ja vaimo tuli raskaaksi, ja lähetti ja ilmoitti sen Davidille, ja sanoi: minä olen raskaaksi tullut.","Ja vaimo tuli raskaaksi, ja lähetti ja ilmoitti sen Davidille, ja sanoi: minä olen raskaaksi tullut."],[11,6,"Niin lähetti David Joabin tykö, sanoen: lähetä minun tyköni Uria Hetiläinen. Ja Joab lähetti Urian Davidin tykö.","Niin lähetti David Joabin tykö, sanoen: lähetä minun tyköni Uria Hetiläinen. Ja Joab lähetti Urian Davidin tykö."],[11,7,"Ja kuin Uria tuli hänen tykönsä, kysyi David: jos Joab ja kansa rauhassa olisivat ja jos sota menestyis?","Ja kuin Uria tuli hänen tykönsä, kysyi David: jos Joab ja kansa rauhassa olisivat ja jos sota menestyis?"],[11,8,"Ja David sanoi Urialle: mene huoneeses ja pese jalkas. Ja kuin Uria läksi kuninkaan huoneesta, seurasi häntä kohta kuninkaan herkku.","Ja David sanoi Urialle: mene huoneeses ja pese jalkas. Ja kuin Uria läksi kuninkaan huoneesta, seurasi häntä kohta kuninkaan herkku."],[11,9,"Ja Uria pani levätä kuninkaan huoneen oven eteen, kussa kaikki hänen herransa palveliat makasivat, ja ei mennyt huoneesensa.","Ja Uria pani levätä kuninkaan huoneen oven eteen, kussa kaikki hänen herransa palveliat makasivat, ja ei mennyt huoneesensa."],[11,10,"Kuin Davidille sanottiin: ei Uria ole mennyt huoneesensa, sanoi David Urialle: etkös tullut matkasta? miksi et mennyt huoneeses?","Kuin Davidille sanottiin: ei Uria ole mennyt huoneesensa, sanoi David Urialle: etkös tullut matkasta? miksi et mennyt huoneeses?"],[11,11,"Mutta Uria sanoi Davidille: arkki, ja Israel ja Juuda makaavat majoissa, herrani Joab ja herrani palveliat makaavat kedolla, ja minä menisin huoneesen syömään, juomaan ja makaamaan emäntäni tykönä? Niin totta kuin sinä elät ja sinun sielus elää, en tee minä sitä.","Mutta Uria sanoi Davidille: arkki, ja Israel ja Juuda makaavat majoissa, herrani Joab ja herrani palveliat makaavat kedolla, ja minä menisin huoneesen syömään, juomaan ja makaamaan emäntäni tykönä? Niin totta kuin sinä elät ja sinun sielus elää, en tee minä sitä."],[11,12,"David sanoi Urialle: niin ole vielä tämä päivä tässä, huomenna lasken minä sinun menemään. Niin Uria oli sen päivän Jerusalemissa ja toisen päivän.","David sanoi Urialle: niin ole vielä tämä päivä tässä, huomenna lasken minä sinun menemään. Niin Uria oli sen päivän Jerusalemissa ja toisen päivän."],[11,13,"Ja David kutsui hänen kanssansa syömään ja juomaan, ja juovutti hänen. Ja ehtoona läksi hän ulos ja pani vuoteesensa levätä herransa palveliain kanssa, ja ei mennyt huoneesensa.","Ja David kutsui hänen kanssansa syömään ja juomaan, ja juovutti hänen. Ja ehtoona läksi hän ulos ja pani vuoteesensa levätä herransa palveliain kanssa, ja ei mennyt huoneesensa."],[11,14,"Huomeneltain kirjoitti David Joabin tykö kirjan, ja lähetti sen Urian myötä.","Huomeneltain kirjoitti David Joabin tykö kirjan, ja lähetti sen Urian myötä."],[11,15,"Ja hän kirjoitti kirjaan sanoen: pankaat Uria kovimman sodan eteen, ja kääntykäät hänen tyköänsä takaperin, että hän lyötäisiin ja kuolis.","Ja hän kirjoitti kirjaan sanoen: pankaat Uria kovimman sodan eteen, ja kääntykäät hänen tyköänsä takaperin, että hän lyötäisiin ja kuolis."],[11,16,"Kuin Joab oli kaupungin edessä, asetti hän Urian siihen paikkaan, kussa hän väkevimmät sotamiehet tiesi olevan.","Kuin Joab oli kaupungin edessä, asetti hän Urian siihen paikkaan, kussa hän väkevimmät sotamiehet tiesi olevan."],[11,17,"Ja kuin miehet läksivät kaupungista ja sotivat Joabia vastaan, kaatuivat muutamat Davidin palvelioista, ja Uria Hetiläinen myös kuoli.","Ja kuin miehet läksivät kaupungista ja sotivat Joabia vastaan, kaatuivat muutamat Davidin palvelioista, ja Uria Hetiläinen myös kuoli."],[11,18,"Niin Joab lähetti ja antoi sanoa Davidille kaikki sodan menot,","Niin Joab lähetti ja antoi sanoa Davidille kaikki sodan menot,"],[11,19,"Ja käski sanansaattajalle sanoen: kuin sinä olet puhunut kaikki sodan menot kuninkaalle:","Ja käski sanansaattajalle sanoen: kuin sinä olet puhunut kaikki sodan menot kuninkaalle:"],[11,20,"Ja jos niin on, että kuningas vihastuu ja sanoo sinulle: miksi te niin lähes kaupunkia astuitte sodalla? Ettekö te tietäneet, että muurin päältä paiskataan?","Ja jos niin on, että kuningas vihastuu ja sanoo sinulle: miksi te niin lähes kaupunkia astuitte sodalla? Ettekö te tietäneet, että muurin päältä paiskataan?"],[11,21,"Kuka löi Abimelekin Jerubbesetin pojan? Eikö vaimo paiskannut myllynkiven kappaletta muurista hänen päällensä, että hän kuoli Tebetsessä? Miksi te astuitte niin lähes muuria? Niin sano: sinun palvelias Uria Hetiläinen on myös kuollut.","Kuka löi Abimelekin Jerubbesetin pojan? Eikö vaimo paiskannut myllynkiven kappaletta muurista hänen päällensä, että hän kuoli Tebetsessä? Miksi te astuitte niin lähes muuria? Niin sano: sinun palvelias Uria Hetiläinen on myös kuollut."],[11,22,"Sanansaattaja meni ja tuli ja jutteli Davidille kaikki nämät, joiden tähden Joab hänen lähettänyt oli.","Sanansaattaja meni ja tuli ja jutteli Davidille kaikki nämät, joiden tähden Joab hänen lähettänyt oli."],[11,23,"Ja sanansaattaja sanoi Davidille: ne miehet voittivat meidät ja tulivat ulos kedolle meidän tykömme; mutta me löimme heidät takaperin kaupungin porttiin asti.","Ja sanansaattaja sanoi Davidille: ne miehet voittivat meidät ja tulivat ulos kedolle meidän tykömme; mutta me löimme heidät takaperin kaupungin porttiin asti."],[11,24,"Ja ampujat ampuivat muurista sinun palvelloitas ja tappoivat muutamia kuninkaan palvelioita, ja sinun palvelias Uria Hetiläinen on myös kuollut.","Ja ampujat ampuivat muurista sinun palvelloitas ja tappoivat muutamia kuninkaan palvelioita, ja sinun palvelias Uria Hetiläinen on myös kuollut."],[11,25,"David sanoi sanansaattajalle: sano näin Joabille: älä sitä pahakses pane, sillä miekka syö nyt yhden, nyt toisen, vahvista sota kaupunkia vastaan, ettäs kukistaisit sen: ja vahvista sinä häntä.","David sanoi sanansaattajalle: sano näin Joabille: älä sitä pahakses pane, sillä miekka syö nyt yhden, nyt toisen, vahvista sota kaupunkia vastaan, ettäs kukistaisit sen: ja vahvista sinä häntä."],[11,26,"Ja kuin Urian emäntä kuuli miehensä Urian kuolleeksi, murehti hän miestänsä.","Ja kuin Urian emäntä kuuli miehensä Urian kuolleeksi, murehti hän miestänsä."],[11,27,"Sittekuin hän oli murehtinut, lähetti David ja antoi tuoda hänen huoneesensa, ja hän tuli hänen emännäksensä ja synnytti hänelle pojan, mutta se työ, jonka David teki, oli paha Herran edessä.","Sittekuin hän oli murehtinut, lähetti David ja antoi tuoda hänen huoneesensa, ja hän tuli hänen emännäksensä ja synnytti hänelle pojan, mutta se työ, jonka David teki, oli paha Herran edessä."],[12,1,"Ja Herra lähetti Natanin Davidin tykö. Kuin hän tuli hänen tykönsä, sanoi hän hänelle: kaksi miestä oli yhdessä kaupungissa, toinen rikas ja toinen köyhä.","Ja Herra lähetti Natanin Davidin tykö. Kuin hän tuli hänen tykönsä, sanoi hän hänelle: kaksi miestä oli yhdessä kaupungissa, toinen rikas ja toinen köyhä."],[12,2,"Rikkaalla oli aivan paljo lampaita ja karjaa;","Rikkaalla oli aivan paljo lampaita ja karjaa;"],[12,3,"Mutta köyhällä ei ollut mitään muuta kuin yksi vähä karitsa, jonka hän ostanut oli, ja elättänyt, ja kasvattanut suureksi, ja ravitsi sen tykönänsä lastensa kanssa; joka myös söi hänen leipänsä palasta, ja joi hänen juoma-astiastansa, ja makasi hänen sylissänsä, ja se oli hänelle niinkuin tytär.","Mutta köyhällä ei ollut mitään muuta kuin yksi vähä karitsa, jonka hän ostanut oli, ja elättänyt, ja kasvattanut suureksi, ja ravitsi sen tykönänsä lastensa kanssa; joka myös söi hänen leipänsä palasta, ja joi hänen juoma-astiastansa, ja makasi hänen sylissänsä, ja se oli hänelle niinkuin tytär."],[12,4,"Mutta kuin rikkaalle miehelle tuli vieras, ei raskinut hän ottaa omista lampaistansa ja karjastansa, valmistaaksensa vieraalle, joka hänen tykönsä tullut oli; mutta otti köyhän miehen lampaan ja valmisti vieraalle, joka hänen tykönsä tullut oli.","Mutta kuin rikkaalle miehelle tuli vieras, ei raskinut hän ottaa omista lampaistansa ja karjastansa, valmistaaksensa vieraalle, joka hänen tykönsä tullut oli; mutta otti köyhän miehen lampaan ja valmisti vieraalle, joka hänen tykönsä tullut oli."],[12,5,"Niin Davidin viha julmistui suuresti sitä miestä vastaan, ja hän sanoi Natanille: niin totta kuin Herra elää, se mies on kuoleman lapsi, joka sen teki,","Niin Davidin viha julmistui suuresti sitä miestä vastaan, ja hän sanoi Natanille: niin totta kuin Herra elää, se mies on kuoleman lapsi, joka sen teki,"],[12,6,"Niin myös pitää hänen maksaman neljäkertaisesti sen lampaan, että hän sen tehnyt on, ja ei säästänyt sitä.","Niin myös pitää hänen maksaman neljäkertaisesti sen lampaan, että hän sen tehnyt on, ja ei säästänyt sitä."],[12,7,"Niin sanoi Natan Davidille: sinä olet se mies. Näin sanoo Herra Israelin Jumala: minä olen voidellut sinun Israelin kuninkaaksi ja minä olen pelastanut sinun Saulin kädestä,","Niin sanoi Natan Davidille: sinä olet se mies. Näin sanoo Herra Israelin Jumala: minä olen voidellut sinun Israelin kuninkaaksi ja minä olen pelastanut sinun Saulin kädestä,"],[12,8,"Ja olen antanut sinulle sinun herras huoneen ja hänen emäntänsä sinun syliis, ja olen antanut sinulle Israelin ja Juudan huoneen; ja jos siinä vähä on, niin minä sen lisään sinulle.","Ja olen antanut sinulle sinun herras huoneen ja hänen emäntänsä sinun syliis, ja olen antanut sinulle Israelin ja Juudan huoneen; ja jos siinä vähä on, niin minä sen lisään sinulle."],[12,9,"Miksis katsoit Herran sanan ylön, tehden pahaa hänen silmäinsä edessä? Urian Hetiläisen olet sinä lyönyt miekalla, ja hänen vaimonsa olet sinä ottanut sinulles emännäksi; mutta hänen olet sinä tappanut Ammonin lasten miekalla.","Miksis katsoit Herran sanan ylön, tehden pahaa hänen silmäinsä edessä? Urian Hetiläisen olet sinä lyönyt miekalla, ja hänen vaimonsa olet sinä ottanut sinulles emännäksi; mutta hänen olet sinä tappanut Ammonin lasten miekalla."],[12,10,"Niin ei pidä myös miekan lakkaaman sinun huoneestas ijankaikkisesti; ettäs olet katsonut minun ylön, ja Urian, Hetiläisen, emännän ottanut sinulles emännäksi.","Niin ei pidä myös miekan lakkaaman sinun huoneestas ijankaikkisesti; ettäs olet katsonut minun ylön, ja Urian, Hetiläisen, emännän ottanut sinulles emännäksi."],[12,11,"Näin sanoo Herra: katso, minä herätän pahuuden sinua vastaan omasta huoneestas, ja otan sinun emäntäs sinun silmäis nähden, ja annan ne lähimmäiselles, ja hän makaa sinun emäntäis sivussa valkiana päivänä.","Näin sanoo Herra: katso, minä herätän pahuuden sinua vastaan omasta huoneestas, ja otan sinun emäntäs sinun silmäis nähden, ja annan ne lähimmäiselles, ja hän makaa sinun emäntäis sivussa valkiana päivänä."],[12,12,"Sillä sinä olet sen tehnyt salaisesti; mutta minä teen tämän koko Israelin edessä ja auringon edessä.","Sillä sinä olet sen tehnyt salaisesti; mutta minä teen tämän koko Israelin edessä ja auringon edessä."],[12,13,"Niin sanoi David Natanille: minä olen syntiä tehnyt Herraa vastaan. Natan sanoi Davidille: niin on myös Herra sinun syntis ottanut pois, ei sinun pidä kuoleman.","Niin sanoi David Natanille: minä olen syntiä tehnyt Herraa vastaan. Natan sanoi Davidille: niin on myös Herra sinun syntis ottanut pois, ei sinun pidä kuoleman."],[12,14,"Mutta ettäs tämän työn kautta saatit Herran viholliset pilkkaamaan, pitää sen pojan, joka sinulle syntynyt on, totisesti kuoleman.","Mutta ettäs tämän työn kautta saatit Herran viholliset pilkkaamaan, pitää sen pojan, joka sinulle syntynyt on, totisesti kuoleman."],[12,15,"Sitte meni Natan huoneesensa. Mutta Herra löi lapsen, jonka Urian emäntä Davidille synnyttänyt oli, että se sairasti kuolemallansa.","Sitte meni Natan huoneesensa. Mutta Herra löi lapsen, jonka Urian emäntä Davidille synnyttänyt oli, että se sairasti kuolemallansa."],[12,16,"Ja David etsi Jumalaa lapsen tähden: ja David paastosi paljo, ja meni ja makasi yön maan päällä.","Ja David etsi Jumalaa lapsen tähden: ja David paastosi paljo, ja meni ja makasi yön maan päällä."],[12,17,"Niin nousivat hänen huoneensa vanhimmat nostamaan häntä maasta; mutta ei hän tahtonut, eikä syönyt leipää heidän kanssansa.","Niin nousivat hänen huoneensa vanhimmat nostamaan häntä maasta; mutta ei hän tahtonut, eikä syönyt leipää heidän kanssansa."],[12,18,"Seitsemäntenä päivänä kuoli lapsi; ja ei Davidin palveliat tohtineet sanoa hänelle lasta kuolleeksi, sillä he ajattelivat: katso, kuin lapsi vielä eli, puhuimme me hänen kanssansa, ja ei hän kuullut meidän ääntämme, kuinka paljo enemmin hän tulis murheelliseksi,jos me sanoisimme hänelle: lapsi on kuollut?","Seitsemäntenä päivänä kuoli lapsi; ja ei Davidin palveliat tohtineet sanoa hänelle lasta kuolleeksi, sillä he ajattelivat: katso, kuin lapsi vielä eli, puhuimme me hänen kanssansa, ja ei hän kuullut meidän ääntämme, kuinka paljo enemmin hän tulis murheelliseksi,jos me sanoisimme hänelle: lapsi on kuollut?"],[12,19,"Kuin David näki palveliainsa hiljaksensa puhuvan, ymmärsi hän lapsen kuolleeksi, ja sanoi palvelioillensa: kuoliko lapsi? He sanoivat: kuoli.","Kuin David näki palveliainsa hiljaksensa puhuvan, ymmärsi hän lapsen kuolleeksi, ja sanoi palvelioillensa: kuoliko lapsi? He sanoivat: kuoli."],[12,20,"Ja David nousi maasta, pesi itsensä ja voiteli, ja muutti toiset vaatteet yllensä, ja meni Herran huoneesen ja rukoili, ja tuli kotiansa, ja antoi panna ruokaa eteensä ja söi.","Ja David nousi maasta, pesi itsensä ja voiteli, ja muutti toiset vaatteet yllensä, ja meni Herran huoneesen ja rukoili, ja tuli kotiansa, ja antoi panna ruokaa eteensä ja söi."],[12,21,"Niin sanoivat hänen palveliansa hänelle: mikä se on minkä sinä teet? lapsen eläissä paastosit sinä ja itkit, mutta lapsen kuoltua nouset sinä ja syöt.","Niin sanoivat hänen palveliansa hänelle: mikä se on minkä sinä teet? lapsen eläissä paastosit sinä ja itkit, mutta lapsen kuoltua nouset sinä ja syöt."],[12,22,"Hän sanoi: lapsen eläissä minä paastosin ja itkin; sillä minä ajattelin: kuka tietää, jos Herra on minulle armollinen, että lapsi eläis.","Hän sanoi: lapsen eläissä minä paastosin ja itkin; sillä minä ajattelin: kuka tietää, jos Herra on minulle armollinen, että lapsi eläis."],[12,23,"Mutta nyt on se kuollut: mitä minun pitäis vielä paastoaman: taidanko minä hänen enää jällensä tuoda? Minä menen hänen tykönsä, mutta ei hän palaja minun tyköni.","Mutta nyt on se kuollut: mitä minun pitäis vielä paastoaman: taidanko minä hänen enää jällensä tuoda? Minä menen hänen tykönsä, mutta ei hän palaja minun tyköni."],[12,24,"Ja kuin David oli lohduttanut emäntäänsä BatSebaa, meni hän hänen tykönsä ja lepäsi hänen tykönänsä; ja hän synnytti pojan ja hän kutsui hänen nimensä Salomo, ja Herra rakasti häntä.","Ja kuin David oli lohduttanut emäntäänsä BatSebaa, meni hän hänen tykönsä ja lepäsi hänen tykönänsä; ja hän synnytti pojan ja hän kutsui hänen nimensä Salomo, ja Herra rakasti häntä."],[12,25,"Ja hän lähetti hänen Natan prophetan käden alle, ja kutsui hänen Jedidjah, Herran tähden.","Ja hän lähetti hänen Natan prophetan käden alle, ja kutsui hänen Jedidjah, Herran tähden."],[12,26,"Niin soti Joab Ammonin lasten Rabbaa vastaan ja voitti sen kuninkaallisen kaupungin.","Niin soti Joab Ammonin lasten Rabbaa vastaan ja voitti sen kuninkaallisen kaupungin."],[12,27,"Ja Joab lähetti sanansaattajat Davidille ja antoi sanoa hänelle: minä olen sotinut Rabbaa vastaan ja olen voittanut vesikaupungin;","Ja Joab lähetti sanansaattajat Davidille ja antoi sanoa hänelle: minä olen sotinut Rabbaa vastaan ja olen voittanut vesikaupungin;"],[12,28,"Niin kokoa nyt jäänyt kansa, ja piiritä kaupunki, ja voita se, etten minä sitä voittaisi, ja minulle siitä nimi olisi.","Niin kokoa nyt jäänyt kansa, ja piiritä kaupunki, ja voita se, etten minä sitä voittaisi, ja minulle siitä nimi olisi."],[12,29,"Niin David kokosi kaiken kansan, ja matkusti Rabbaan ja soti sitä vastaan, ja voitti sen;","Niin David kokosi kaiken kansan, ja matkusti Rabbaan ja soti sitä vastaan, ja voitti sen;"],[12,30,"Ja otti heidän kuninkaansa kruunun hänen päästänsä, joka painoi leiviskän kultaa, ja kalliita kiviä, ja se pantiin Davidin päähän; ja hän vei paljo saalista kaupungista ulos.","Ja otti heidän kuninkaansa kruunun hänen päästänsä, joka painoi leiviskän kultaa, ja kalliita kiviä, ja se pantiin Davidin päähän; ja hän vei paljo saalista kaupungista ulos."],[12,31,"Ja kansan, joka siellä oli, johdatti hän ulos ja pani sahaan, rautahaudoille ja kirvestöihin, ja käytti heidän tiilihautoja myöten: niin hän teki kaikille Ammonin lasten kaupungeille. Ja David ja kaikki kansa palasi Jerusalemiin.","Ja kansan, joka siellä oli, johdatti hän ulos ja pani sahaan, rautahaudoille ja kirvestöihin, ja käytti heidän tiilihautoja myöten: niin hän teki kaikille Ammonin lasten kaupungeille. Ja David ja kaikki kansa palasi Jerusalemiin."],[13,1,"Ja tapahtui sitte, että Absalomilla Davidin pojalla oli kaunis sisar, jonka nimi oli Tamar; ja Amnon Davidin poika rakasti häntä.","Ja tapahtui sitte, että Absalomilla Davidin pojalla oli kaunis sisar, jonka nimi oli Tamar; ja Amnon Davidin poika rakasti häntä."],[13,2,"Ja Amnon saatti itsensä tuskissansa sairaaksi sisarensa Tamarin tähden; sillä hän oli neitsy. Ja näkyi työlääksi Amnonin silmäin edessä hänelle jotakin tehdä.","Ja Amnon saatti itsensä tuskissansa sairaaksi sisarensa Tamarin tähden; sillä hän oli neitsy. Ja näkyi työlääksi Amnonin silmäin edessä hänelle jotakin tehdä."],[13,3,"Mutta Amnonilla oli ystävä,joka kutsuttiin Jonadab, Simean Davidin veljen poika; ja Jonadab oli sangen kavala mies.","Mutta Amnonilla oli ystävä,joka kutsuttiin Jonadab, Simean Davidin veljen poika; ja Jonadab oli sangen kavala mies."],[13,4,"Hän sanoi hänelle: kuninkaan poika, miksis niin laihaksi tulet päivä päivältä? Etkös minulle sitä sano? Niin sanoi Amnon hänelle: minä rakastan Tamaria,veljeni Absalomin sisarta.","Hän sanoi hänelle: kuninkaan poika, miksis niin laihaksi tulet päivä päivältä? Etkös minulle sitä sano? Niin sanoi Amnon hänelle: minä rakastan Tamaria,veljeni Absalomin sisarta."],[13,5,"Jonadab sanoi hänelle: laske sinus vuoteeses ja teeskele itses sairaaksi: kuin siis sinun isäs tulee katsomaan sinua, niin sano hänelle: tulkaan sisareni Tamar ruokkimaan minua ja valmistamaan ruokaa minun eteeni, että minä näkisin ja söisin hänen kädestänsä.","Jonadab sanoi hänelle: laske sinus vuoteeses ja teeskele itses sairaaksi: kuin siis sinun isäs tulee katsomaan sinua, niin sano hänelle: tulkaan sisareni Tamar ruokkimaan minua ja valmistamaan ruokaa minun eteeni, että minä näkisin ja söisin hänen kädestänsä."],[13,6,"Niin Amnon pani levätä ja teeskeli itsensä sairaaksi. Kuin kuningas tuli häntä katsomaan, sanoi Amnon kuninkaalle: tulkaan minun sisareni Tamar valmistamaan minun eteeni kaksikin herkkua, että minä söisin hänen kädestänsä.","Niin Amnon pani levätä ja teeskeli itsensä sairaaksi. Kuin kuningas tuli häntä katsomaan, sanoi Amnon kuninkaalle: tulkaan minun sisareni Tamar valmistamaan minun eteeni kaksikin herkkua, että minä söisin hänen kädestänsä."],[13,7,"Niin lähetti David sanan Tamarille huoneesen ja antoi hänelle sanoa: mene veljes Amnonin huoneesen ja valmista hänelle ruokaa.","Niin lähetti David sanan Tamarille huoneesen ja antoi hänelle sanoa: mene veljes Amnonin huoneesen ja valmista hänelle ruokaa."],[13,8,"Tamar meni veljensä Amnonin huoneesen, ja hän makasi vuoteessa; ja hän otti taikinan, sotkui ja valmisti sen hänen silmäinsä edessä, ja kypsensi ne herkut.","Tamar meni veljensä Amnonin huoneesen, ja hän makasi vuoteessa; ja hän otti taikinan, sotkui ja valmisti sen hänen silmäinsä edessä, ja kypsensi ne herkut."],[13,9,"Ja hän otti pannun ja kaasi hänen eteensä, vaan ei hän tahtonut syödä. Ja Amnon sanoi: antakaat kaikki mennä ulos minun tyköäni; niin menivät kaikki ulos hänen tyköänsä.","Ja hän otti pannun ja kaasi hänen eteensä, vaan ei hän tahtonut syödä. Ja Amnon sanoi: antakaat kaikki mennä ulos minun tyköäni; niin menivät kaikki ulos hänen tyköänsä."],[13,10,"Niin sanoi Amnon Tamarille: kanna ruoka kamariin syödäkseni kädestäs. Niin Tamar otti herkun, jonka hän valmistanut oli, ja kantoi kamariin veljensä Amnonin tykö.","Niin sanoi Amnon Tamarille: kanna ruoka kamariin syödäkseni kädestäs. Niin Tamar otti herkun, jonka hän valmistanut oli, ja kantoi kamariin veljensä Amnonin tykö."],[13,11,"Ja kuin hän taritsi hänelle syödä, tarttui hän häneen ja sanoi hänelle: tule minun sisareni ja makaa minun kanssani.","Ja kuin hän taritsi hänelle syödä, tarttui hän häneen ja sanoi hänelle: tule minun sisareni ja makaa minun kanssani."],[13,12,"Mutta hän sanoi: ei, minun veljeni, älä minua häpäise! sillä ei niin pidä tehtämän Israelissa. älä tee hulluutta.","Mutta hän sanoi: ei, minun veljeni, älä minua häpäise! sillä ei niin pidä tehtämän Israelissa. älä tee hulluutta."],[13,13,"Kuhunka minun pitäis häpiäni sälyttämän? Ja sinä tulisit niinkuin tyhmä Israelissa. Puhu paremmin kuninkaan kanssa, sillä ei hän minua sinulta kiellä.","Kuhunka minun pitäis häpiäni sälyttämän? Ja sinä tulisit niinkuin tyhmä Israelissa. Puhu paremmin kuninkaan kanssa, sillä ei hän minua sinulta kiellä."],[13,14,"Mutta ei hän tahtonut kuulla häntä, vaan voitti hänen, häpäisi ja makasi hänen.","Mutta ei hän tahtonut kuulla häntä, vaan voitti hänen, häpäisi ja makasi hänen."],[13,15,"Sitte vihasi Amnon häntä sangen suurella vihalla, niin että viha, jolla hän häntä vihasi oli suurempi, kuin rakkaus ennen oli, jolla hän häntä rakasti. Ja Amnon sanoi hänelle: nouse ja mene.","Sitte vihasi Amnon häntä sangen suurella vihalla, niin että viha, jolla hän häntä vihasi oli suurempi, kuin rakkaus ennen oli, jolla hän häntä rakasti. Ja Amnon sanoi hänelle: nouse ja mene."],[13,16,"Mutta hän sanoi: eikö tämä pahuus ole suurempi kuin se toinen, jonka sinä olet tehnyt minun kanssani, ettäs minun ajat ulos. Mutta ei hän tahtonut kuulla häntä;","Mutta hän sanoi: eikö tämä pahuus ole suurempi kuin se toinen, jonka sinä olet tehnyt minun kanssani, ettäs minun ajat ulos. Mutta ei hän tahtonut kuulla häntä;"],[13,17,"Vaan kutsui nuorukaisensa, joka häntä palveli ja sanoi: aja tämä ulos minun tyköäni, ja sulje ovi kiinni hänen jälkeensä.","Vaan kutsui nuorukaisensa, joka häntä palveli ja sanoi: aja tämä ulos minun tyköäni, ja sulje ovi kiinni hänen jälkeensä."],[13,18,"Ja hänen yllänsä oli kirjava hame; sillä senkaltaisilla hameilla olivat kuninkaan tyttäret vaatetetut, niinkauvan kuin he olivat neitseet. Ja kuin hänen palveliansa oli hänen ajanut ulos ja sulkenut oven hänen jälkeensä,","Ja hänen yllänsä oli kirjava hame; sillä senkaltaisilla hameilla olivat kuninkaan tyttäret vaatetetut, niinkauvan kuin he olivat neitseet. Ja kuin hänen palveliansa oli hänen ajanut ulos ja sulkenut oven hänen jälkeensä,"],[13,19,"Heitti Tamar tuhkaa päänsä päälle, ja repäisi sen kirjavan hameen rikki, joka hänen yllänsä oli, ja pani kätensä päänsä päälle, ja huusi mennessänsä.","Heitti Tamar tuhkaa päänsä päälle, ja repäisi sen kirjavan hameen rikki, joka hänen yllänsä oli, ja pani kätensä päänsä päälle, ja huusi mennessänsä."],[13,20,"Ja hänen veljensä Absalom sanoi hänelle: onko sinun veljes Amnon ollut sinun kanssas? Ole ääneti sisareni: se on sinun veljes, älä sitä niin pane sydämees. Niin Tamar jäi yksinäiseksi veljensä Absalomin huoneesen.","Ja hänen veljensä Absalom sanoi hänelle: onko sinun veljes Amnon ollut sinun kanssas? Ole ääneti sisareni: se on sinun veljes, älä sitä niin pane sydämees. Niin Tamar jäi yksinäiseksi veljensä Absalomin huoneesen."],[13,21,"Ja kuin kuningas David kaikki nämät kuuli vihastui hän sangen suuresti.","Ja kuin kuningas David kaikki nämät kuuli vihastui hän sangen suuresti."],[13,22,"Mutta Absalom ei puhunut Amnonille pahaa eli hyvää; vaan Absalom vihasi Amnonia että hän häpäisi hänen sisarensa Tamarin.","Mutta Absalom ei puhunut Amnonille pahaa eli hyvää; vaan Absalom vihasi Amnonia että hän häpäisi hänen sisarensa Tamarin."],[13,23,"Kahden vuoden perästä antoi Absalom kerittää lampaitansa BaalHatsarissa, joka on Ephraimin tykönä; ja Absalom kutsui kaikki kuninkaan lapset.","Kahden vuoden perästä antoi Absalom kerittää lampaitansa BaalHatsarissa, joka on Ephraimin tykönä; ja Absalom kutsui kaikki kuninkaan lapset."],[13,24,"Ja Absalom tuli myös kuninkaan tykö ja sanoi: katso, palveliallas ovat nyt lammasten keritsiät: minä rukoilen, että kuningas palvelioinensa tulis palveliansa tykö.","Ja Absalom tuli myös kuninkaan tykö ja sanoi: katso, palveliallas ovat nyt lammasten keritsiät: minä rukoilen, että kuningas palvelioinensa tulis palveliansa tykö."],[13,25,"Mutta kuningas sanoi Absalomille: ei niin, poikani, älkäämme kaikki menkö, ettemme tekisi sinulle vaivaa. Ja vaikka hän suuresti rukoili häntä, ei hän kuitenkaan tahtonut mennä, vaan siunasi häntä.","Mutta kuningas sanoi Absalomille: ei niin, poikani, älkäämme kaikki menkö, ettemme tekisi sinulle vaivaa. Ja vaikka hän suuresti rukoili häntä, ei hän kuitenkaan tahtonut mennä, vaan siunasi häntä."],[13,26,"Absalom sanoi: jollet sinä tule, niin salli veljeni Amnonin käydä meidän kanssamme. Kuningas sanoi hänelle: mitä hän menee sinun kanssas?","Absalom sanoi: jollet sinä tule, niin salli veljeni Amnonin käydä meidän kanssamme. Kuningas sanoi hänelle: mitä hän menee sinun kanssas?"],[13,27,"Niin Absalom vaati häntä, että hän antoi Amnonin ja kaikki kuninkaan lapset mennä heidän kanssansa.","Niin Absalom vaati häntä, että hän antoi Amnonin ja kaikki kuninkaan lapset mennä heidän kanssansa."],[13,28,"Ja Absalom käski palvelioillensa ja sanoi: ottakaat vaari kuin Amnon tulee iloiseksi viinasta ja minä sanon teille: lyökäät Amnon! niin tappakaat häntä, älkäät peljätkö, sillä minä olen sen teille käskenyt, olkaat rohkiat ja miehuulliset siihen.","Ja Absalom käski palvelioillensa ja sanoi: ottakaat vaari kuin Amnon tulee iloiseksi viinasta ja minä sanon teille: lyökäät Amnon! niin tappakaat häntä, älkäät peljätkö, sillä minä olen sen teille käskenyt, olkaat rohkiat ja miehuulliset siihen."],[13,29,"Ja Absalomin palveliat tekivät Amnonille niinkuin Absalom käskenyt oli. Niin kaikki kuninkaan lapset nousivat, ja jokainen istui muulinsa päälle ja pakeni.","Ja Absalomin palveliat tekivät Amnonille niinkuin Absalom käskenyt oli. Niin kaikki kuninkaan lapset nousivat, ja jokainen istui muulinsa päälle ja pakeni."],[13,30,"Ja kuin he vielä tiellä olivat, tuli sanoma Davidille, sanoen: Absalom on lyönyt kaikki kuninkaan lapset, niin ettei yksikään heistä ole jäänyt.","Ja kuin he vielä tiellä olivat, tuli sanoma Davidille, sanoen: Absalom on lyönyt kaikki kuninkaan lapset, niin ettei yksikään heistä ole jäänyt."],[13,31,"Niin nousi kuningas ja repäisi vaatteensa rikki, ja heitti itsensä maahan; ja kaikki palveliat, jotka seisoivat hänen ympärillänsä, repäisivät vaatteensa rikki.","Niin nousi kuningas ja repäisi vaatteensa rikki, ja heitti itsensä maahan; ja kaikki palveliat, jotka seisoivat hänen ympärillänsä, repäisivät vaatteensa rikki."],[13,32,"Niin vastasi Jonadab Simean Davidin veljen poika ja sanoi: älköön minun Herrani ajatelko, että kaikki nuorukaiset kuninkaan lapsista ovat tapetut, vaan ainoastansa Amnon on kuollut; sillä se on ollut Absalomin mielessä siitä päivästä, kuin hän häpäisi hänen sisarensa Tamarin.","Niin vastasi Jonadab Simean Davidin veljen poika ja sanoi: älköön minun Herrani ajatelko, että kaikki nuorukaiset kuninkaan lapsista ovat tapetut, vaan ainoastansa Amnon on kuollut; sillä se on ollut Absalomin mielessä siitä päivästä, kuin hän häpäisi hänen sisarensa Tamarin."],[13,33,"Niin älköön herrani kuningas panko sydämellensä, ajatellen, että kaikki kuninkaan lapset ovat kuolleet; sillä Amnon on ainoastansa kuollut.","Niin älköön herrani kuningas panko sydämellensä, ajatellen, että kaikki kuninkaan lapset ovat kuolleet; sillä Amnon on ainoastansa kuollut."],[13,34,"Ja Absalom pakeni; ja palvelia, joka vartiana oli, nosti silmänsä ja näki, ja katso, suuri joukko kansaa tuli tiellä toinen toisensa perästä, vuoren sivulta.","Ja Absalom pakeni; ja palvelia, joka vartiana oli, nosti silmänsä ja näki, ja katso, suuri joukko kansaa tuli tiellä toinen toisensa perästä, vuoren sivulta."],[13,35,"Niin Jonadab sanoi kuninkaalle: katso, kuninkaan lapset tulevat; niinkuin palvelias sanonut on, niin on myös tapahtunut.","Niin Jonadab sanoi kuninkaalle: katso, kuninkaan lapset tulevat; niinkuin palvelias sanonut on, niin on myös tapahtunut."],[13,36,"Ja kuin hän puhunut oli, katso, kuninkaan lapset tulivat, korottivat äänensä ja itkivät. Kuningas ja kaikki hänen palveliansa itkivät myös suurella itkulla.","Ja kuin hän puhunut oli, katso, kuninkaan lapset tulivat, korottivat äänensä ja itkivät. Kuningas ja kaikki hänen palveliansa itkivät myös suurella itkulla."],[13,37,"Mutta Albsalom pakeni ja meni Talmain Gessurin kuninkaan Ammihudin pojan tykö; mutta hän murehti poikansa tähden ne päivät.","Mutta Albsalom pakeni ja meni Talmain Gessurin kuninkaan Ammihudin pojan tykö; mutta hän murehti poikansa tähden ne päivät."],[13,38,"Mutta sittekuin Absalom oli paennut ja matkustanut Gessuriin oli hän siellä kolme ajastaikaa.","Mutta sittekuin Absalom oli paennut ja matkustanut Gessuriin oli hän siellä kolme ajastaikaa."],[13,39,"Ja sen jälkeen lakkasi kuningas David menemästä Absalomia vastaan; sillä hän oli jo lohdutettu Amnonin jälkeen, joka kuollut oli.","Ja sen jälkeen lakkasi kuningas David menemästä Absalomia vastaan; sillä hän oli jo lohdutettu Amnonin jälkeen, joka kuollut oli."],[14,1,"Ja kuin Joab ZeruJan poika ymmärsi kuninkaan sydämen olevan Absalomia vastaan;","Ja kuin Joab ZeruJan poika ymmärsi kuninkaan sydämen olevan Absalomia vastaan;"],[14,2,"Niin Joab lähetti Tekoaan ja antoi tuoda sieltä toimellisen vaimon, ja sanoi hänelle: teeskele nyt sinus murheelliseksi, ja pue murhevaatteet päälles, ja älä voitele sinuas öljyllä; vaan ole niinkuin joku vaimo, joka jo kauvan aikaa on murehtinut kuollutta;","Niin Joab lähetti Tekoaan ja antoi tuoda sieltä toimellisen vaimon, ja sanoi hänelle: teeskele nyt sinus murheelliseksi, ja pue murhevaatteet päälles, ja älä voitele sinuas öljyllä; vaan ole niinkuin joku vaimo, joka jo kauvan aikaa on murehtinut kuollutta;"],[14,3,"Ja mene kuninkaan tykö ja puhu näin ja näin hänen kanssansa. Ja Joab pani sanat hänen suuhunsa.","Ja mene kuninkaan tykö ja puhu näin ja näin hänen kanssansa. Ja Joab pani sanat hänen suuhunsa."],[14,4,"Ja kuin Tekoan vaimo tahtoi puhua kuninkaan kanssa, lankesi hän maahan kasvoillensa, kumarsi ja sanoi: auta minua! kuningas.","Ja kuin Tekoan vaimo tahtoi puhua kuninkaan kanssa, lankesi hän maahan kasvoillensa, kumarsi ja sanoi: auta minua! kuningas."],[14,5,"Kuningas sanoi hänelle: mikä sinun on? Hän sanoi: minä olen tosin leskivaimo, ja minun mieheni on kuollut,","Kuningas sanoi hänelle: mikä sinun on? Hän sanoi: minä olen tosin leskivaimo, ja minun mieheni on kuollut,"],[14,6,"Ja sinun piiallas oli kaksi poikaa: ne riitelivät keskenänsä kedolla, ja ettei siellä ollut joka heidät eroitti, niin löi toinen toisensa ja tappoi hänen.","Ja sinun piiallas oli kaksi poikaa: ne riitelivät keskenänsä kedolla, ja ettei siellä ollut joka heidät eroitti, niin löi toinen toisensa ja tappoi hänen."],[14,7,"Ja katso, nyt nousee koko sukukunta piikaas vastaan ja sanoo: anna tänne se, joka veljensä tappoi, tapettavaksi hänen veljensä sielun edestä, jonka hän tappanut on, ja tehtäväksi perinnöttömäksi. Ja he tahtovat sammuttaa minun kipinäni, joka vielä jäljellä on, ettei minun miehelläni ensinkään nimeä pitäisi hänen jälkeensä oleman maan päällä.","Ja katso, nyt nousee koko sukukunta piikaas vastaan ja sanoo: anna tänne se, joka veljensä tappoi, tapettavaksi hänen veljensä sielun edestä, jonka hän tappanut on, ja tehtäväksi perinnöttömäksi. Ja he tahtovat sammuttaa minun kipinäni, joka vielä jäljellä on, ettei minun miehelläni ensinkään nimeä pitäisi hänen jälkeensä oleman maan päällä."],[14,8,"Kuningas sanoi vaimolle: mene kotias, ja minä käsken sinun puolestas.","Kuningas sanoi vaimolle: mene kotias, ja minä käsken sinun puolestas."],[14,9,"Ja Tekoan vaimo sanoi kuninkaalle: minun herrani kuningas, se pahateko olkoon minun päälläni ja minun isäni huoneen päällä; mutta kuningas ja hänen istuimensa olkoon viatoin.","Ja Tekoan vaimo sanoi kuninkaalle: minun herrani kuningas, se pahateko olkoon minun päälläni ja minun isäni huoneen päällä; mutta kuningas ja hänen istuimensa olkoon viatoin."],[14,10,"Kuningas sanoi: joka sinua vastaan puhuu, tuo häntä minun tyköni: ei hänen pidä enää rupeeman sinuun.","Kuningas sanoi: joka sinua vastaan puhuu, tuo häntä minun tyköni: ei hänen pidä enää rupeeman sinuun."],[14,11,"Hän sanoi: ajatelkaan nyt kuningas Herransa Jumalansa päälle, ettei verenkostajia ylen monta olisi kadottamaan, ja ettei minun poikani surmattaisi. Hän sanoi: niin totta kuin Herra elää, ei pidä hiuskarvakaan lankeeman pojastas maan päälle.","Hän sanoi: ajatelkaan nyt kuningas Herransa Jumalansa päälle, ettei verenkostajia ylen monta olisi kadottamaan, ja ettei minun poikani surmattaisi. Hän sanoi: niin totta kuin Herra elää, ei pidä hiuskarvakaan lankeeman pojastas maan päälle."],[14,12,"Ja vaimo sanoi: anna nyt sinun piikas sanoa jotakin herralleni kuninkaalle! Hän sanoi: sano.","Ja vaimo sanoi: anna nyt sinun piikas sanoa jotakin herralleni kuninkaalle! Hän sanoi: sano."],[14,13,"Vaimo sanoi: miksi sinulla on senkaltainen ajatus Jumalan kansaa vastaan? että kuningas senkaltaisia sanoja puhunut on, niinkuin hän tekis itsensä vialliseksi, ettei kuningas anna tuoda kulkiaansa jälleen:","Vaimo sanoi: miksi sinulla on senkaltainen ajatus Jumalan kansaa vastaan? että kuningas senkaltaisia sanoja puhunut on, niinkuin hän tekis itsensä vialliseksi, ettei kuningas anna tuoda kulkiaansa jälleen:"],[14,14,"Sillä me tosin kuolemme ja juoksemme niinkuin vesi maahan, jota ei pidätetä: Ja ei Jumalakaan henkeä ota pois, vaan ajattelee kaiketi, ettei kulkia häneltä syöstäisi ulos.","Sillä me tosin kuolemme ja juoksemme niinkuin vesi maahan, jota ei pidätetä: Ja ei Jumalakaan henkeä ota pois, vaan ajattelee kaiketi, ettei kulkia häneltä syöstäisi ulos."],[14,15,"Niin olen minä nyt tullut puhumaan senkaltaisia herralleni kuninkaalle; sillä kansa on peljättänyt minua, ja piikas ajatteli: minä puhun kuninkaan kanssa, kuka tietää, että hän tekee piikansa sanan jälkeen.","Niin olen minä nyt tullut puhumaan senkaltaisia herralleni kuninkaalle; sillä kansa on peljättänyt minua, ja piikas ajatteli: minä puhun kuninkaan kanssa, kuka tietää, että hän tekee piikansa sanan jälkeen."],[14,16,"Sillä kuningas kuulee piikaansa ja auttaa niiden kädestä, jotka minua ja minun poikaani yhtä haavaa Jumalan perimisestä eroittaa tahtovat.","Sillä kuningas kuulee piikaansa ja auttaa niiden kädestä, jotka minua ja minun poikaani yhtä haavaa Jumalan perimisestä eroittaa tahtovat."],[14,17,"Ja piikas ajatteli: herrani kuninkaan sanat ovat minulle lohdutukseksi; sillä herrani kuninkaani on niinkuin Jumalan enkeli, ja kuultelee hyvän ja pahan; sentähden myös Herra sinun Jumalas on sinun kanssas.","Ja piikas ajatteli: herrani kuninkaan sanat ovat minulle lohdutukseksi; sillä herrani kuninkaani on niinkuin Jumalan enkeli, ja kuultelee hyvän ja pahan; sentähden myös Herra sinun Jumalas on sinun kanssas."],[14,18,"Kuningas vastasi ja sanoi vaimolle: älä siis salaa minulta sitä, mitä minä kysyn sinulta. Vaimo sanoi: herrani kuningas puhukaan.","Kuningas vastasi ja sanoi vaimolle: älä siis salaa minulta sitä, mitä minä kysyn sinulta. Vaimo sanoi: herrani kuningas puhukaan."],[14,19,"Kuningas sanoi: eikö Joabin käsi ole sinun kanssas kaikissa päissä? Vaimo vastasi ja sanoi: niin totta kuin sinun sielus elää, minun herrani kuningas, ei ole yhtäkään oikialla eli vasemmalla kädellä, paitsi sitä kuin minun herrani kuningas sanonut on; sillä sinun palvelias Joab on minun käskenyt ja on kaikki nämät sanat piikas suuhun pannut.","Kuningas sanoi: eikö Joabin käsi ole sinun kanssas kaikissa päissä? Vaimo vastasi ja sanoi: niin totta kuin sinun sielus elää, minun herrani kuningas, ei ole yhtäkään oikialla eli vasemmalla kädellä, paitsi sitä kuin minun herrani kuningas sanonut on; sillä sinun palvelias Joab on minun käskenyt ja on kaikki nämät sanat piikas suuhun pannut."],[14,20,"Että minä niin kääntäisin tämän asian, sen on sinun palvelias Joab tehnyt: mutta minun herrani on toimellinen niinkuin Jumalan enkeli, ja ymmärtää kaikki kappaleet maan päällä.","Että minä niin kääntäisin tämän asian, sen on sinun palvelias Joab tehnyt: mutta minun herrani on toimellinen niinkuin Jumalan enkeli, ja ymmärtää kaikki kappaleet maan päällä."],[14,21,"Silloin sanoi kuningas Joabille: katso, minä olen sen tehnyt: mene ja tuo nuorukainen Absalom jälleen.","Silloin sanoi kuningas Joabille: katso, minä olen sen tehnyt: mene ja tuo nuorukainen Absalom jälleen."],[14,22,"Silloin lankesi Joab kasvoillensa maahan, kumarsi ja kiitti kuningasta, ja sanoi: tänäpänä ymmärtää palvelias minun löytäneeksi armon sinun edessäs, minun herrani kuningas; sillä kuningas tekee, mitä hänen palveliansa sanoo.","Silloin lankesi Joab kasvoillensa maahan, kumarsi ja kiitti kuningasta, ja sanoi: tänäpänä ymmärtää palvelias minun löytäneeksi armon sinun edessäs, minun herrani kuningas; sillä kuningas tekee, mitä hänen palveliansa sanoo."],[14,23,"Niin nousi Joab ja meni Gessuriin, ja toi Absalomin Jerusalemiin.","Niin nousi Joab ja meni Gessuriin, ja toi Absalomin Jerusalemiin."],[14,24,"Mutta kuningas sanoi: anna hänen poiketa huoneesensa ja ei nähdä minun kasvojani. Niin Absalom poikkesi huoneesensa ja ei nähnyt kuninkaan kasvoja.","Mutta kuningas sanoi: anna hänen poiketa huoneesensa ja ei nähdä minun kasvojani. Niin Absalom poikkesi huoneesensa ja ei nähnyt kuninkaan kasvoja."],[14,25,"Ja koko Israelissa ei ollut yksikään mies niin kaunis kuin Absalom, ja niin suuresti ylistettävä; hamasta hänen kantapäästänsä niin päänlakeen asti ei ollut yhtäkään virhettä hänessä.","Ja koko Israelissa ei ollut yksikään mies niin kaunis kuin Absalom, ja niin suuresti ylistettävä; hamasta hänen kantapäästänsä niin päänlakeen asti ei ollut yhtäkään virhettä hänessä."],[14,26,"Ja kuin hänen päänsä kerittiin (se tapahtui vihdoin joka vuosi, sillä se oli hänelle ylen raskas, niin että hänen piti sen keritsemän), niin painoivat hänen hiuksensa kaksisataa sikliä kuninkaan painon jälkeen.","Ja kuin hänen päänsä kerittiin (se tapahtui vihdoin joka vuosi, sillä se oli hänelle ylen raskas, niin että hänen piti sen keritsemän), niin painoivat hänen hiuksensa kaksisataa sikliä kuninkaan painon jälkeen."],[14,27,"Ja Absalomille syntyi kolme poikaa ja yksi tytär, se kutsuttiin Tamar; ja hän oli kaunis vaimo näöstä.","Ja Absalomille syntyi kolme poikaa ja yksi tytär, se kutsuttiin Tamar; ja hän oli kaunis vaimo näöstä."],[14,28,"Ja niin oli Absalom kaksi ajastaikaa Jerusalemissa, ettei hän kuninkaan kasvoja nähnyt.","Ja niin oli Absalom kaksi ajastaikaa Jerusalemissa, ettei hän kuninkaan kasvoja nähnyt."],[14,29,"Ja Absalom lähetti Joabin perään, lähettääksensä häntä kuninkaan tykö: ja ei hän tahtonut tulla hänen tykönsä. Hän lähetti toisen kerran, vaan ei hän tahtonut tulla.","Ja Absalom lähetti Joabin perään, lähettääksensä häntä kuninkaan tykö: ja ei hän tahtonut tulla hänen tykönsä. Hän lähetti toisen kerran, vaan ei hän tahtonut tulla."],[14,30,"Silloin sanoi hän palvelioillensa: katsokaat sitä Joabin pellon kappaletta minun sarkani vieressä, ja hänellä on siinä ohraa: menkäät ja pistäkäät tuli siihen; niin pistivät Absalomin palveliat tulen siihen.","Silloin sanoi hän palvelioillensa: katsokaat sitä Joabin pellon kappaletta minun sarkani vieressä, ja hänellä on siinä ohraa: menkäät ja pistäkäät tuli siihen; niin pistivät Absalomin palveliat tulen siihen."],[14,31,"Silloin nousi Joab ja tuli Absalomin huoneesen, ja sanoi hänelle: miksi palvelias ovat pistäneet tulen minun sarkaani?","Silloin nousi Joab ja tuli Absalomin huoneesen, ja sanoi hänelle: miksi palvelias ovat pistäneet tulen minun sarkaani?"],[14,32,"Absalom sanoi Joabille: katso, minä lähetin sinun perääs ja annoin sanoa sinulle: tule minun tyköni, lähettääkseni sinua kuninkaan tykö, ja antaakseni sanoa: miksi minä tulin Gessurista? Se olis minulle parempi, että minä vielä siellä olisin. Niin anna minun nähdä kuninkaan kasvot: jos myös joku pahateko on minussa, niin tappakoon minun.","Absalom sanoi Joabille: katso, minä lähetin sinun perääs ja annoin sanoa sinulle: tule minun tyköni, lähettääkseni sinua kuninkaan tykö, ja antaakseni sanoa: miksi minä tulin Gessurista? Se olis minulle parempi, että minä vielä siellä olisin. Niin anna minun nähdä kuninkaan kasvot: jos myös joku pahateko on minussa, niin tappakoon minun."],[14,33,"Ja Joab meni kuninkaan tykö ja sanoi sen hänelle, ja hän kutsui Absalomin kuninkaan tykö. Ja hän kumarsi kuninkaan eteen maahan kasvoillensa, ja kuningas antoi suuta Absalomille.","Ja Joab meni kuninkaan tykö ja sanoi sen hänelle, ja hän kutsui Absalomin kuninkaan tykö. Ja hän kumarsi kuninkaan eteen maahan kasvoillensa, ja kuningas antoi suuta Absalomille."],[15,1,"Ja tapahtui sitte, että Absalom antoi valmistaa itsellensä vaunut ja hevoset, ja viisikymmentä miestä, jotka olivat hänen edelläjuoksiansa.","Ja tapahtui sitte, että Absalom antoi valmistaa itsellensä vaunut ja hevoset, ja viisikymmentä miestä, jotka olivat hänen edelläjuoksiansa."],[15,2,"Ja Absalom nousi varhain huomeneltain ja seisoi porttitien vieressä, ja kuin jollakin oli asiaa tulla kuninkaan tykö oikeuden eteen, kutsui Absalom sen tykönsä ja sanoi: sinun palvelias on yhdestä Israelin sukukunnista,","Ja Absalom nousi varhain huomeneltain ja seisoi porttitien vieressä, ja kuin jollakin oli asiaa tulla kuninkaan tykö oikeuden eteen, kutsui Absalom sen tykönsä ja sanoi: sinun palvelias on yhdestä Israelin sukukunnista,"],[15,3,"Niin Absalom sanoi hänelle: katso, sinun asias on oikia ja selkiä; mutta ei ole yksikään siellä kuninkaalta asetettu, joka sinua kuulis.","Niin Absalom sanoi hänelle: katso, sinun asias on oikia ja selkiä; mutta ei ole yksikään siellä kuninkaalta asetettu, joka sinua kuulis."],[15,4,"Ja Absalom sanoi: kuka minun asettais tuomariksi maalla, että jokainen tulis minun tyköni jolla jotain asiaa ja kaipaamista on, auttaakseni häntä oikeuteen?","Ja Absalom sanoi: kuka minun asettais tuomariksi maalla, että jokainen tulis minun tyköni jolla jotain asiaa ja kaipaamista on, auttaakseni häntä oikeuteen?"],[15,5,"Ja kuin joku tuli hänen tykönsä kumartamaan häntä, ojensi hän kätensä ja tarttui häneen, ja antoi hänen suuta.","Ja kuin joku tuli hänen tykönsä kumartamaan häntä, ojensi hän kätensä ja tarttui häneen, ja antoi hänen suuta."],[15,6,"Niin teki Absalom kaikelle Israelille, kuin he tulivat oikeuden eteen kuninkaan tykö; ja niin varasti Absalom Israelin miesten sydämet.","Niin teki Absalom kaikelle Israelille, kuin he tulivat oikeuden eteen kuninkaan tykö; ja niin varasti Absalom Israelin miesten sydämet."],[15,7,"Ja tapahtui neljänkymmenen ajastajan perästä, että Absalom sanoi kuninkaalle: minä menisin ja täyttäisin lupaukseni, jonka minä lupasin Herralle Hebronissa.","Ja tapahtui neljänkymmenen ajastajan perästä, että Absalom sanoi kuninkaalle: minä menisin ja täyttäisin lupaukseni, jonka minä lupasin Herralle Hebronissa."],[15,8,"Sillä silloin kuin minä asuin Gessurissa Syriassa, lupasi sinun palvelias lupauksen ja sanoi: kuin Herra tuo minun kerran Jerusalemiin jälleen, palvelen minä Herraa.","Sillä silloin kuin minä asuin Gessurissa Syriassa, lupasi sinun palvelias lupauksen ja sanoi: kuin Herra tuo minun kerran Jerusalemiin jälleen, palvelen minä Herraa."],[15,9,"Kuningas sanoi hänelle: mene rauhassa! Ja hän nousi ja meni Hebroniin.","Kuningas sanoi hänelle: mene rauhassa! Ja hän nousi ja meni Hebroniin."],[15,10,"Mutta Absalom oli lähettänyt vakoojat kaikkiin Israelin sukukuntiin, ja käski sanoa: kuin saatte kuulla torven äänen, niin sanokaat: Absalom on kuningas Hebronissa.","Mutta Absalom oli lähettänyt vakoojat kaikkiin Israelin sukukuntiin, ja käski sanoa: kuin saatte kuulla torven äänen, niin sanokaat: Absalom on kuningas Hebronissa."],[15,11,"Mutta Absalomin kanssa meni kaksisataa miestä Jerusalemista, jotka olivat kutsutut; mutta ne menivät yksinkertaisuudessansa, eikä mitään asiasta tietäneet.","Mutta Absalomin kanssa meni kaksisataa miestä Jerusalemista, jotka olivat kutsutut; mutta ne menivät yksinkertaisuudessansa, eikä mitään asiasta tietäneet."],[15,12,"Ja Absalom lähetti myös Ahitophelin Gilonilaisen, Davidin neuvonantajan, perään hänen kaupungistansa Gilosta, kuin hän uhria uhrasi; niin tehtiin juuri vahva liitto, ja paljo kansaa lisääntyi ja eneni Absalomin tykö.","Ja Absalom lähetti myös Ahitophelin Gilonilaisen, Davidin neuvonantajan, perään hänen kaupungistansa Gilosta, kuin hän uhria uhrasi; niin tehtiin juuri vahva liitto, ja paljo kansaa lisääntyi ja eneni Absalomin tykö."],[15,13,"Ja yksi tuli ja ilmoitti sen Davidille, ja sanoi: Israelin miesten sydän on kääntynyt Absalomin jälkeen.","Ja yksi tuli ja ilmoitti sen Davidille, ja sanoi: Israelin miesten sydän on kääntynyt Absalomin jälkeen."],[15,14,"Ja David sanoi kaikille palvelioillensa, jotka hänen kanssansa Jerusalemissa olivat: nouskaamme ja paetkaamme, sillä muutoin ei pääse yksikään meistä Absalomin edestä! rientäkäät menemään, ettei hän äkisti karkaisi meidän päällemme, ja ottaisi meitä kiinni, ja vahingoitsisi meitä ja löisi kaupunkia miekalla.","Ja David sanoi kaikille palvelioillensa, jotka hänen kanssansa Jerusalemissa olivat: nouskaamme ja paetkaamme, sillä muutoin ei pääse yksikään meistä Absalomin edestä! rientäkäät menemään, ettei hän äkisti karkaisi meidän päällemme, ja ottaisi meitä kiinni, ja vahingoitsisi meitä ja löisi kaupunkia miekalla."],[15,15,"Kuninkaan palveliat sanoivat kuninkaalle: mitä meidän herramme kuningas valitsee, katso tässä me palvelias olemme.","Kuninkaan palveliat sanoivat kuninkaalle: mitä meidän herramme kuningas valitsee, katso tässä me palvelias olemme."],[15,16,"Ja kuningas kävi jalkaisin ulos kaiken huoneensa kanssa; mutta hän jätti kymmenen jalkavaimoa huoneita vartioitsemaan.","Ja kuningas kävi jalkaisin ulos kaiken huoneensa kanssa; mutta hän jätti kymmenen jalkavaimoa huoneita vartioitsemaan."],[15,17,"Ja kuin kuningas ja kaikki kansa olivat jalkaisin käyneet ulos, seisoivat he kaukana huoneista.","Ja kuin kuningas ja kaikki kansa olivat jalkaisin käyneet ulos, seisoivat he kaukana huoneista."],[15,18,"Ja kaikki hänen palveliansa kävivät hänen tykönänsä, sitälikin myös kaikki Kretit ja Pletit; ja kaikki Gatilaiset kuusisataa miestä, jotka jalkaisin olivat tulleet Gatista, kävivät kuninkaan edellä.","Ja kaikki hänen palveliansa kävivät hänen tykönänsä, sitälikin myös kaikki Kretit ja Pletit; ja kaikki Gatilaiset kuusisataa miestä, jotka jalkaisin olivat tulleet Gatista, kävivät kuninkaan edellä."],[15,19,"Ja kuningas sanoi Ittaille Gatilaiselle: miksi sinä myös tulet meidän kanssamme? Palaja ja ole kuninkaan tykönä; sillä sinä olet muukalainen, ja olet tänne tullut sinun sialtas.","Ja kuningas sanoi Ittaille Gatilaiselle: miksi sinä myös tulet meidän kanssamme? Palaja ja ole kuninkaan tykönä; sillä sinä olet muukalainen, ja olet tänne tullut sinun sialtas."],[15,20,"Sillä eilen sinä tulit, ja minun pitäis tänäpänä antaman sinun käydä meidän kanssamme; mutta minä menen, kuhunka minä menen: palaja sinä ja vie sinun veljes myötäs. Sinun kanssas tapahtukoon armo ja vakuus!","Sillä eilen sinä tulit, ja minun pitäis tänäpänä antaman sinun käydä meidän kanssamme; mutta minä menen, kuhunka minä menen: palaja sinä ja vie sinun veljes myötäs. Sinun kanssas tapahtukoon armo ja vakuus!"],[15,21,"Ittai vastasi kuningasta ja sanoi: niin totta kuin Herra elää, ja niin totta kuin minun herrani kuningas elää, kussa ikänä herrani kuningas on, olisi se kuolemassa eli elämässä, siellä pitää myös sinun palvelias oleman.","Ittai vastasi kuningasta ja sanoi: niin totta kuin Herra elää, ja niin totta kuin minun herrani kuningas elää, kussa ikänä herrani kuningas on, olisi se kuolemassa eli elämässä, siellä pitää myös sinun palvelias oleman."],[15,22,"David sanoi Ittaille: tule ja käy meidän kanssamme. Ja niin kävi Ittai Gatilainen, ja kaikki hänen miehensä, ja kaikki lapset jotka hänen kanssansa olivat.","David sanoi Ittaille: tule ja käy meidän kanssamme. Ja niin kävi Ittai Gatilainen, ja kaikki hänen miehensä, ja kaikki lapset jotka hänen kanssansa olivat."],[15,23,"Ja kaikki maakunta itki suurella äänellä, ja kaikki väki meni kanssa. Ja kuningas kävi Kidronin ojan ylitse, ja kaikki kansa kävi edellä korven tietä.","Ja kaikki maakunta itki suurella äänellä, ja kaikki väki meni kanssa. Ja kuningas kävi Kidronin ojan ylitse, ja kaikki kansa kävi edellä korven tietä."],[15,24,"Ja katso, Zadok myös oli siellä ja kaikki Leviläiset, jotka hänen kanssansa olivat, ja he kantoivat Jumalan liitonarkin, ja panivat ylös Jumalan arkin. Ja Abjatar meni ylös, siihenasti kuin kaikki väki tuli kaupungista.","Ja katso, Zadok myös oli siellä ja kaikki Leviläiset, jotka hänen kanssansa olivat, ja he kantoivat Jumalan liitonarkin, ja panivat ylös Jumalan arkin. Ja Abjatar meni ylös, siihenasti kuin kaikki väki tuli kaupungista."],[15,25,"Niin sanoi kuningas Zadokille: kanna Jumalan arkki kaupunkiin jälleen: jos minä löydän armon Herran edessä, niin hän tuo minun jälleen ja antaa minun nähdä hänen ja hänen majansa.","Niin sanoi kuningas Zadokille: kanna Jumalan arkki kaupunkiin jälleen: jos minä löydän armon Herran edessä, niin hän tuo minun jälleen ja antaa minun nähdä hänen ja hänen majansa."],[15,26,"Mutta jos hän niin sanoo: et sinä ole minulle otollinen! katso, tässä minä olen: hän tehköön minulle, mitä hän tahtoo!","Mutta jos hän niin sanoo: et sinä ole minulle otollinen! katso, tässä minä olen: hän tehköön minulle, mitä hän tahtoo!"],[15,27,"Ja kuningas sanoi papille Zadokille: sinä näkiä, palaja rauhassa kaupunkiin, ja molemmat teidän poikanne teidän kanssanne, Ahimaats sinun poikas ja Jonatan AbJatarin poika.","Ja kuningas sanoi papille Zadokille: sinä näkiä, palaja rauhassa kaupunkiin, ja molemmat teidän poikanne teidän kanssanne, Ahimaats sinun poikas ja Jonatan AbJatarin poika."],[15,28,"Katso, minä odotan tasaisella kedolla korvessa siihenasti kuin teiltä sana tulee, tekemään minulle tiettäväksi.","Katso, minä odotan tasaisella kedolla korvessa siihenasti kuin teiltä sana tulee, tekemään minulle tiettäväksi."],[15,29,"Niin Zadok ja AbJatar kantoivat Jumalan arkin Jerusalemiin, ja olivat siellä.","Niin Zadok ja AbJatar kantoivat Jumalan arkin Jerusalemiin, ja olivat siellä."],[15,30,"Mutta David meni ylös öljymäen paltaa myöten ja itki käydessänsä, ja hänen päänsä oli peitetty, ja kävi kengittä; niin myös kaikki kansa, jotka hänen kanssansa olivat, peittivät päänsä, ja käyden astuivat ylös ja itkivät.","Mutta David meni ylös öljymäen paltaa myöten ja itki käydessänsä, ja hänen päänsä oli peitetty, ja kävi kengittä; niin myös kaikki kansa, jotka hänen kanssansa olivat, peittivät päänsä, ja käyden astuivat ylös ja itkivät."],[15,31,"Ja kuin Davidille ilmoitettiin Ahitophelin olevan liitossa Absalomin kanssa, sanoi hän: Herra, tee Ahitophelin neuvo tyhmyydeksi!","Ja kuin Davidille ilmoitettiin Ahitophelin olevan liitossa Absalomin kanssa, sanoi hän: Herra, tee Ahitophelin neuvo tyhmyydeksi!"],[15,32,"Ja kuin David tuli kukkulalle, kussa Jumalaa rukoiltiin, katso, Husai Arkilainen kohtasi häntä reväistyllä hameella, ja multaa hänen päänsä päällä.","Ja kuin David tuli kukkulalle, kussa Jumalaa rukoiltiin, katso, Husai Arkilainen kohtasi häntä reväistyllä hameella, ja multaa hänen päänsä päällä."],[15,33,"Ja David sanoi: jos seuraat minua, niin sinä olet minulle kuormaksi.","Ja David sanoi: jos seuraat minua, niin sinä olet minulle kuormaksi."],[15,34,"Mutta jos palajat kaupunkiin ja sanot AbsalomilIe: minä olen sinun palvelias, kuningas, joka ennen isääs olen kauvan palvellut, ja tahdon olla nyt sinun palvelias: ja näin sinä minulle teet Ahitophelin neuvon tyhjäksi.","Mutta jos palajat kaupunkiin ja sanot AbsalomilIe: minä olen sinun palvelias, kuningas, joka ennen isääs olen kauvan palvellut, ja tahdon olla nyt sinun palvelias: ja näin sinä minulle teet Ahitophelin neuvon tyhjäksi."],[15,35,"Eikö Zadok ja AbJatar papit ole sinun kanssas? Ja kaikki, mitäs kuulet kuninkaan huoneessa, ilmoita papeille Zadokille ja AbJatarille.","Eikö Zadok ja AbJatar papit ole sinun kanssas? Ja kaikki, mitäs kuulet kuninkaan huoneessa, ilmoita papeille Zadokille ja AbJatarille."],[15,36,"Katso, heidän kaksi poikaansa ovat siellä heidän kanssansa, Ahimaats Zadokin poika ja Jonatan AbJatarin poika: niiden kanssa te saatte lähettää minulle, mitä te kuulette.","Katso, heidän kaksi poikaansa ovat siellä heidän kanssansa, Ahimaats Zadokin poika ja Jonatan AbJatarin poika: niiden kanssa te saatte lähettää minulle, mitä te kuulette."],[15,37,"Niin Husai Davidin ystävä meni kaupunkiin ja Absalom tuli Jerusalemiin.","Niin Husai Davidin ystävä meni kaupunkiin ja Absalom tuli Jerusalemiin."],[16,1,"Ja kuin David oli vähä käynyt alas vuoren kukkulalta, katso, kohtasi hänen Ziba MephiBosetin palvelia kahdella satuloidulla aasilla, joiden päällä oli kaksisataa leipää, ja sata rypälettä rusinoita, ja sata rypälettä fikunia ja leili viinaa.","Ja kuin David oli vähä käynyt alas vuoren kukkulalta, katso, kohtasi hänen Ziba MephiBosetin palvelia kahdella satuloidulla aasilla, joiden päällä oli kaksisataa leipää, ja sata rypälettä rusinoita, ja sata rypälettä fikunia ja leili viinaa."],[16,2,"Niin sanoi kuningas Ziballe: mitäs näillä tahdot tehdä? Ziba sanoi: aasit pitää oleman kuninkaan perheelle, joilla he ajaisivat, leivät ja fikunat palvelioille, joista he söisivät, ja viina heidän juodaksensa, kuin he väsyvät korvessa.","Niin sanoi kuningas Ziballe: mitäs näillä tahdot tehdä? Ziba sanoi: aasit pitää oleman kuninkaan perheelle, joilla he ajaisivat, leivät ja fikunat palvelioille, joista he söisivät, ja viina heidän juodaksensa, kuin he väsyvät korvessa."],[16,3,"Kuningas sanoi: kussa on herras poika? Ziba sanoi kuninkaalle: katso, hän jäi Jerusalemiin, sillä hän sanoi: tänäpänä pitää Israelin huoneen antaman minulle minun isäni valtakunnan.","Kuningas sanoi: kussa on herras poika? Ziba sanoi kuninkaalle: katso, hän jäi Jerusalemiin, sillä hän sanoi: tänäpänä pitää Israelin huoneen antaman minulle minun isäni valtakunnan."],[16,4,"Kuningas sanoi Ziballe: katso, kaikki mitä MephiBosetilla on, pitää sinun oleman. Ziba sanoi: minä rukoilen nöyrästi, anna minun löytää armo sinun edessäs, herrani kuningas.","Kuningas sanoi Ziballe: katso, kaikki mitä MephiBosetilla on, pitää sinun oleman. Ziba sanoi: minä rukoilen nöyrästi, anna minun löytää armo sinun edessäs, herrani kuningas."],[16,5,"Kuin kuningas David tuli Bahurimiin, katso, sieltä tuli yksi mies Saulin huoneen suvusta, Simei nimeltä, Geran poika, se läksi ulos ja kiroili käydessänsä,","Kuin kuningas David tuli Bahurimiin, katso, sieltä tuli yksi mies Saulin huoneen suvusta, Simei nimeltä, Geran poika, se läksi ulos ja kiroili käydessänsä,"],[16,6,"Ja paiskeli kiviä Davidin puoleen, ja kaikkia kuningas Davidin palvelioita vastaan; sillä kaikki kansa ja kaikki väkevät olivat hänen oikialla ja vasemmalla puolellansa.","Ja paiskeli kiviä Davidin puoleen, ja kaikkia kuningas Davidin palvelioita vastaan; sillä kaikki kansa ja kaikki väkevät olivat hänen oikialla ja vasemmalla puolellansa."],[16,7,"Ja Simei sanoi näin kiroillessansa häntä: ulos, ulos tänne, sinä verikoira, sinä Belialin mies!","Ja Simei sanoi näin kiroillessansa häntä: ulos, ulos tänne, sinä verikoira, sinä Belialin mies!"],[16,8,"Herra on maksanut sinulle kaiken Saulin huoneen veren, ettäs olet tullut hänen siaansa kuninkaaksi. Ja Herra on antanut valtakunnan pojalles Absalomille; ja katso, nyt sinä olet sinun pahuudessas, sillä sinä olet verikoira.","Herra on maksanut sinulle kaiken Saulin huoneen veren, ettäs olet tullut hänen siaansa kuninkaaksi. Ja Herra on antanut valtakunnan pojalles Absalomille; ja katso, nyt sinä olet sinun pahuudessas, sillä sinä olet verikoira."],[16,9,"Silloin Abisai ZeruJan poika sanoi kuninkaalle: pitääkö tämän kuolleen koiran kiroileman herraani kuningasta? Minä menen ja lyön häneltä pään pois.","Silloin Abisai ZeruJan poika sanoi kuninkaalle: pitääkö tämän kuolleen koiran kiroileman herraani kuningasta? Minä menen ja lyön häneltä pään pois."],[16,10,"Kuningas sanoi: te ZeruJan pojat, mitä minun on teidän kanssanne? Anna hänen kirota; sillä Herra on hänelle sanonut: kiroile David. Kuka taitaa nyt sanoa: miksis niin teet?","Kuningas sanoi: te ZeruJan pojat, mitä minun on teidän kanssanne? Anna hänen kirota; sillä Herra on hänelle sanonut: kiroile David. Kuka taitaa nyt sanoa: miksis niin teet?"],[16,11,"Ja David sanoi Abisaille ja kaikille palvelioillensa: katso, minun poikani, joka minun kupeistani tullut on, seisoo minun henkeni perään: miksi ei siis pidä myös Jeminin pojan? Antakaat hänen kiroilla, sillä Herra on hänelle sanonut.","Ja David sanoi Abisaille ja kaikille palvelioillensa: katso, minun poikani, joka minun kupeistani tullut on, seisoo minun henkeni perään: miksi ei siis pidä myös Jeminin pojan? Antakaat hänen kiroilla, sillä Herra on hänelle sanonut."],[16,12,"Mahtaa tapahtua: Herra katsoo minun viheliäisyyttäni, ja Herra maksaa minulle hyvällä, sen kun hän minua tänäpänä kiroilee.","Mahtaa tapahtua: Herra katsoo minun viheliäisyyttäni, ja Herra maksaa minulle hyvällä, sen kun hän minua tänäpänä kiroilee."],[16,13,"Ja David meni väkinensä tietä myöten; mutta Simei kävi hänen kohdallansa mäen viertä myöten, ja käyden kiroili, lasketti kiviä hänen puoleensa ja viskeli multaa.","Ja David meni väkinensä tietä myöten; mutta Simei kävi hänen kohdallansa mäen viertä myöten, ja käyden kiroili, lasketti kiviä hänen puoleensa ja viskeli multaa."],[16,14,"Ja kuningas vaelsi, ja kaikki kansa joka oli hänen kanssansa oli väsyksissä; ja hän lepäsi siinä.","Ja kuningas vaelsi, ja kaikki kansa joka oli hänen kanssansa oli väsyksissä; ja hän lepäsi siinä."],[16,15,"Mutta Absalom ja kaikki kansa, Israelin miehet, tulivat Jerusalemiin; ja Ahitophel hänen kanssansa.","Mutta Absalom ja kaikki kansa, Israelin miehet, tulivat Jerusalemiin; ja Ahitophel hänen kanssansa."],[16,16,"Kuin Husai Arkilainen Davidin ystävä tuli Absalomin tykö, sanoi hän Absalomille: kuningas eläköön, kuningas eläköön!","Kuin Husai Arkilainen Davidin ystävä tuli Absalomin tykö, sanoi hän Absalomille: kuningas eläköön, kuningas eläköön!"],[16,17,"Absalom sanoi Husaille: onko tämä sinun laupiutes ystävääs kohtaan? Miksi et mennyt ystäväs kanssa?","Absalom sanoi Husaille: onko tämä sinun laupiutes ystävääs kohtaan? Miksi et mennyt ystäväs kanssa?"],[16,18,"Husai sanoi Absalomille: ei niin; mutta jonka Herra valitsee,ja tämä kansa, ja kaikki Israelin miehet, hänen minä olen ja hänen kanssansa minä pysyn.","Husai sanoi Absalomille: ei niin; mutta jonka Herra valitsee,ja tämä kansa, ja kaikki Israelin miehet, hänen minä olen ja hänen kanssansa minä pysyn."],[16,19,"Sitälikin, ketästä minun pitäis palveleman? eikö hänen poikansa edessä? Niinkuin minä olen palvellut isäis edessä, niin minä myös tahdon olla sinun edessäs.","Sitälikin, ketästä minun pitäis palveleman? eikö hänen poikansa edessä? Niinkuin minä olen palvellut isäis edessä, niin minä myös tahdon olla sinun edessäs."],[16,20,"Ja Absalom sanoi Ahitophelille: pitäkäät neuvoa, mitä meidän pitää tekemän?","Ja Absalom sanoi Ahitophelille: pitäkäät neuvoa, mitä meidän pitää tekemän?"],[16,21,"Ahitophel sanoi Absalomille: makaa isäs jalkavaimoin kanssa, jotka hän on jättänyt huonetta vartioitsemaan; niin koko Israel saa kuulla sinun tehneeksi isäs haisemaan, ja kaikkein kädet vahvistetaan siitä, jotka sinun tykönäs ovat.","Ahitophel sanoi Absalomille: makaa isäs jalkavaimoin kanssa, jotka hän on jättänyt huonetta vartioitsemaan; niin koko Israel saa kuulla sinun tehneeksi isäs haisemaan, ja kaikkein kädet vahvistetaan siitä, jotka sinun tykönäs ovat."],[16,22,"Niin tekivät he Absalomille majan katon päälle; ja Absalom makasi kaikkein isänsä jalkavaimoin kanssa, kaiken Israelin nähden.","Niin tekivät he Absalomille majan katon päälle; ja Absalom makasi kaikkein isänsä jalkavaimoin kanssa, kaiken Israelin nähden."],[16,23,"Kuin Ahitophel neuvoa antoi sillä ajalla, oli se niinkuin joku olis kysynyt Jumalalta jostakin asiasta: kaikki niin olivat Ahitophelin neuvot niin Davidin kuin Absalominkin tykönä.","Kuin Ahitophel neuvoa antoi sillä ajalla, oli se niinkuin joku olis kysynyt Jumalalta jostakin asiasta: kaikki niin olivat Ahitophelin neuvot niin Davidin kuin Absalominkin tykönä."],[17,1,"Ja Ahitophel sanoi Absalomille: minä valitsen nyt kaksitoistakymmentä tuhatta miestä ja nousen tänä yönä ajamaan Davidia takaa.","Ja Ahitophel sanoi Absalomille: minä valitsen nyt kaksitoistakymmentä tuhatta miestä ja nousen tänä yönä ajamaan Davidia takaa."],[17,2,"Ja minä karkaan hänen päällensä, niinkauvan kuin hän on väsynyt ja heikko käsistä. Kuin minä hänen peljätän, että kaikki kansa pakenee, joka hänen tykönänsä on, niin lyön minä kuninkaan yksinänsä,","Ja minä karkaan hänen päällensä, niinkauvan kuin hän on väsynyt ja heikko käsistä. Kuin minä hänen peljätän, että kaikki kansa pakenee, joka hänen tykönänsä on, niin lyön minä kuninkaan yksinänsä,"],[17,3,"Ja palautan kaiken kansan sinun tykös. Kuin jokainen on sinun tykös palautettu, niinkuin sinä anonut olet, niin kaikki kansa on rauhassa.","Ja palautan kaiken kansan sinun tykös. Kuin jokainen on sinun tykös palautettu, niinkuin sinä anonut olet, niin kaikki kansa on rauhassa."],[17,4,"Se näkyi oikia olevan Absalomille ja kaikille vanhimmille Israelissa.","Se näkyi oikia olevan Absalomille ja kaikille vanhimmille Israelissa."],[17,5,"Mutta Absalom sanoi: kutsuttakoon myös Husai Arkilainen, ja kuulkaamme, mitä hän tästä asiasta sanoo.","Mutta Absalom sanoi: kutsuttakoon myös Husai Arkilainen, ja kuulkaamme, mitä hän tästä asiasta sanoo."],[17,6,"Ja kuin Husai tuli Absalomin tykö, puhui Absalom hänelle, sanoen: näitä Ahitophel on puhunut, sano sinä, pitääkö meidän niin tekemän, taikka ei?","Ja kuin Husai tuli Absalomin tykö, puhui Absalom hänelle, sanoen: näitä Ahitophel on puhunut, sano sinä, pitääkö meidän niin tekemän, taikka ei?"],[17,7,"Niin Husai sanoi Absalomille: ei ole se hyvä neuvo, kuin Ahitophel tällä haavalla antanut on.","Niin Husai sanoi Absalomille: ei ole se hyvä neuvo, kuin Ahitophel tällä haavalla antanut on."],[17,8,"Ja Husai sanoi vielä: sinä tunnet hyvin isäs ja hänen miehensä, että ne ovat väkevät ja vihaiset sydämestä niinkuin karhu, jolta pojat ovat otetut kedolla pois: on myös isäs sotamies, ja ei hän yöttele väkensä kanssa.","Ja Husai sanoi vielä: sinä tunnet hyvin isäs ja hänen miehensä, että ne ovat väkevät ja vihaiset sydämestä niinkuin karhu, jolta pojat ovat otetut kedolla pois: on myös isäs sotamies, ja ei hän yöttele väkensä kanssa."],[17,9,"Katso: nyt hän on lymyttänyt itsensä johonkuhun luolaan eli johonkuhun muuhun paikkaan: jos se nyt tapahtuis, että he nyt alussa kaatuisivat, ja se kuin sen kohta kuulis, niin hän sanois: siellä on tapahtunut suuri tappo sen kansan seassa, jotka Absalomia seurasivat.","Katso: nyt hän on lymyttänyt itsensä johonkuhun luolaan eli johonkuhun muuhun paikkaan: jos se nyt tapahtuis, että he nyt alussa kaatuisivat, ja se kuin sen kohta kuulis, niin hän sanois: siellä on tapahtunut suuri tappo sen kansan seassa, jotka Absalomia seurasivat."],[17,10,"Niin rupeais todella jokainen pelkäämään, joka muutoin on väkevä sotamies, jonka sydän on kuin jalopeuran sydän; sillä kaikki Israel tietää, että isäs on väkevä, ja ne ovat jalot sotamiehet, jotka hänen kanssansa ovat.","Niin rupeais todella jokainen pelkäämään, joka muutoin on väkevä sotamies, jonka sydän on kuin jalopeuran sydän; sillä kaikki Israel tietää, että isäs on väkevä, ja ne ovat jalot sotamiehet, jotka hänen kanssansa ovat."],[17,11,"Mutta sitä neuvoa minä annan, että sinä kokoat tykös kaiken Israelin, hamasta Danista BerSebaan asti, niin monta kuin santaa meren rannalla: ja sinä itse menet heidän kanssansa heidän seassansa.","Mutta sitä neuvoa minä annan, että sinä kokoat tykös kaiken Israelin, hamasta Danista BerSebaan asti, niin monta kuin santaa meren rannalla: ja sinä itse menet heidän kanssansa heidän seassansa."],[17,12,"Niin me karkaamme hänen päällensä, kussa paikassa me hänen ikänä löydämme, ja karkaamme hänen päällensä, niinkuin kaste lankee maan päälle, ettemme yhtäkään jätä jäljelle kaikista hänen miehistänsä, jotka hänen kanssansa ovat.","Niin me karkaamme hänen päällensä, kussa paikassa me hänen ikänä löydämme, ja karkaamme hänen päällensä, niinkuin kaste lankee maan päälle, ettemme yhtäkään jätä jäljelle kaikista hänen miehistänsä, jotka hänen kanssansa ovat."],[17,13,"Mutta jos hän kokoo itsensä johonkuhun kaupunkiin, niin pitää koko Israelin siihen kaupunkiin heittämän köysiä; ja me vedämme sen virtaan siihenasti, ettei siitä löydetä yhtäkään kiveä.","Mutta jos hän kokoo itsensä johonkuhun kaupunkiin, niin pitää koko Israelin siihen kaupunkiin heittämän köysiä; ja me vedämme sen virtaan siihenasti, ettei siitä löydetä yhtäkään kiveä."],[17,14,"Niin sanoi Absalom ja jokainen mies Israelista: Husain Arkilaisen neuvo on parempi kuin Ahitophelin. Mutta Herra asetti sen niin, että Ahitophelin hyvä neuvo estettiin, että Herra saattais Absalomille onnettomuuden.","Niin sanoi Absalom ja jokainen mies Israelista: Husain Arkilaisen neuvo on parempi kuin Ahitophelin. Mutta Herra asetti sen niin, että Ahitophelin hyvä neuvo estettiin, että Herra saattais Absalomille onnettomuuden."],[17,15,"Ja Husai sanoi papille Zadokille ja AbJatarille: niin ja niin on Ahitophel Absalomia ja Israelin vanhempia neuvonut, mutta minä olen niin ja niin neuvonut.","Ja Husai sanoi papille Zadokille ja AbJatarille: niin ja niin on Ahitophel Absalomia ja Israelin vanhempia neuvonut, mutta minä olen niin ja niin neuvonut."],[17,16,"Niin lähettäkäät nyt kiiruusti matkaan, ja ilmoittakaat Davidille ja sanokaat: älä ole yötä kedolla korvessa, mutta riennä pois, ettei kuningas nieltäis ja kaikki väki joka hänen kanssansa on.","Niin lähettäkäät nyt kiiruusti matkaan, ja ilmoittakaat Davidille ja sanokaat: älä ole yötä kedolla korvessa, mutta riennä pois, ettei kuningas nieltäis ja kaikki väki joka hänen kanssansa on."],[17,17,"Ja Jonatan ja Ahimaats seisoivat Rogelin lähteen tykönä, ja yksi piika meni ja sanoi sen heille, ja he menivät ja sanoivat sen kuningas Davidille; sillä ei he uskaltaneet näyttää itsiänsä, että olivat tulleet kaupunkiin.","Ja Jonatan ja Ahimaats seisoivat Rogelin lähteen tykönä, ja yksi piika meni ja sanoi sen heille, ja he menivät ja sanoivat sen kuningas Davidille; sillä ei he uskaltaneet näyttää itsiänsä, että olivat tulleet kaupunkiin."],[17,18,"Mutta yksi palvelia sai heidät nähdä ja ilmoitti Absalomille. Ja he menivät nopiasti molemmin matkaansa ja tulivat Bahurimissa yhden miehen huoneesen, hänellä oli kaivo kartanossansa; ja he astuivat siihen sisälle.","Mutta yksi palvelia sai heidät nähdä ja ilmoitti Absalomille. Ja he menivät nopiasti molemmin matkaansa ja tulivat Bahurimissa yhden miehen huoneesen, hänellä oli kaivo kartanossansa; ja he astuivat siihen sisälle."],[17,19,"Ja vaimo otti peitteen ja levitti kaivon päälle, ja hajoitti survotuita herneitä sen päälle; niin ettei sitä tuntunut.","Ja vaimo otti peitteen ja levitti kaivon päälle, ja hajoitti survotuita herneitä sen päälle; niin ettei sitä tuntunut."],[17,20,"Kuin Absalomin palveliat tulivat vaimon tykö huoneeseen, sanoivat he: kussa on Ahimaats ja Jonatan? Vaimo sanoi heille: he menivät tuon vähän ojan ylitse. Ja kuin he olivat etsineet ja ei mitään löytäneet, menivät he Jerusalemiin jällensä.","Kuin Absalomin palveliat tulivat vaimon tykö huoneeseen, sanoivat he: kussa on Ahimaats ja Jonatan? Vaimo sanoi heille: he menivät tuon vähän ojan ylitse. Ja kuin he olivat etsineet ja ei mitään löytäneet, menivät he Jerusalemiin jällensä."],[17,21,"Ja kuin he olivat menneet pois, nousivat he kaivosta ylös, ja menivät matkaansa, ja ilmoittivat kuningas Davidille, ja sanoivat Davidille: nouskaat ja menkäät kiiruusti veden ylitse; sillä niin ja niin on Ahitophel pitänyt neuvoa teitä vastaan.","Ja kuin he olivat menneet pois, nousivat he kaivosta ylös, ja menivät matkaansa, ja ilmoittivat kuningas Davidille, ja sanoivat Davidille: nouskaat ja menkäät kiiruusti veden ylitse; sillä niin ja niin on Ahitophel pitänyt neuvoa teitä vastaan."],[17,22,"Silloin nousi David ja kaikki väki, joka hänen kanssansa oli, ja meni ennen päivän koittamaa Jordanin ylitse, ja ei yksikään puuttunut heistä, joka ei tullut Jordanin ylitse.","Silloin nousi David ja kaikki väki, joka hänen kanssansa oli, ja meni ennen päivän koittamaa Jordanin ylitse, ja ei yksikään puuttunut heistä, joka ei tullut Jordanin ylitse."],[17,23,"Kuin Abitophel näki, ettei hänen neuvonsa jälkeen tehty, satuloitsi hän aasinsa, nousi ja meni huoneesensa ja kaupunkiinsa, ja toimitti huoneensa menot, ja hirtti itsensä; ja niin hän kuoli ja haudattiin isänsä hautaan.","Kuin Abitophel näki, ettei hänen neuvonsa jälkeen tehty, satuloitsi hän aasinsa, nousi ja meni huoneesensa ja kaupunkiinsa, ja toimitti huoneensa menot, ja hirtti itsensä; ja niin hän kuoli ja haudattiin isänsä hautaan."],[17,24,"Ja David tuli Mahanaimiin; ja Absalom meni Jordanin ylitse, hän ja kaikki Israelin miehet hänen kanssansa.","Ja David tuli Mahanaimiin; ja Absalom meni Jordanin ylitse, hän ja kaikki Israelin miehet hänen kanssansa."],[17,25,"Ja Absalom asetti Amasan Joabin siaan sodanpäämieheksi. Ja Amasa oli Jetran sen Jisreeliläisen poika, joka makasi Abigailin Nahaksen tyttären ZeruJan sisaren, Joabin äidin.","Ja Absalom asetti Amasan Joabin siaan sodanpäämieheksi. Ja Amasa oli Jetran sen Jisreeliläisen poika, joka makasi Abigailin Nahaksen tyttären ZeruJan sisaren, Joabin äidin."],[17,26,"Mutta Israel ja Absalom sioittivat itsensä Gileadin maalle.","Mutta Israel ja Absalom sioittivat itsensä Gileadin maalle."],[17,27,"Kuin David oli tullut Mahanaimiin, toi Sobi Nahaksen poika, Ammonin lasten Rabbatista, ja Makir Amnielin poika Lodebarista ja Barsillai Gileadilainen Rogelimista","Kuin David oli tullut Mahanaimiin, toi Sobi Nahaksen poika, Ammonin lasten Rabbatista, ja Makir Amnielin poika Lodebarista ja Barsillai Gileadilainen Rogelimista"],[17,28,"Makausvaatteita, maljoja, saviastioita, nisuja, ohria, jauhoja, kuivatuita tähkäpäitä, papuja, herneitä ja tuletettuja herneitä,","Makausvaatteita, maljoja, saviastioita, nisuja, ohria, jauhoja, kuivatuita tähkäpäitä, papuja, herneitä ja tuletettuja herneitä,"],[17,29,"Hunajaa, voita, lampaita ja lehmän juustoja, ne kantoivat he Davidille ja väelle, joka hänen kanssansa oli, ravinnoksi; sillä he ajattelivat: kansa rupee isoomaan, väsymään ja janoomaan korvessa.","Hunajaa, voita, lampaita ja lehmän juustoja, ne kantoivat he Davidille ja väelle, joka hänen kanssansa oli, ravinnoksi; sillä he ajattelivat: kansa rupee isoomaan, väsymään ja janoomaan korvessa."],[18,1,"Ja David silmäili kansan, joka hänen tykönänsä oli, ja pani päämiehiä tuhanten ja satain päälle,","Ja David silmäili kansan, joka hänen tykönänsä oli, ja pani päämiehiä tuhanten ja satain päälle,"],[18,2,"Ja lähetti kansasta kolmannen osan Joabin kanssa ja kolmannen osan Abisain ZeruJan pojan Joabin veljen kanssa, ja kolmannen osan Ittain sen Gatilaisen kanssa. Ja kuningas sanoi kansalle: minä menen kohta myös teidän kanssanne.","Ja lähetti kansasta kolmannen osan Joabin kanssa ja kolmannen osan Abisain ZeruJan pojan Joabin veljen kanssa, ja kolmannen osan Ittain sen Gatilaisen kanssa. Ja kuningas sanoi kansalle: minä menen kohta myös teidän kanssanne."],[18,3,"Mutta kansa sanoi: älä mene; sillä jos me joudumme pakenemaan, ei he meistä tottele: jos puoli kuolee meistä, ei he siitä pidä lukua; sillä sinä olet niinkuin kymmenentuhatta meistä. Se on parempi, ettäs tulet meille avuksi kaupungista.","Mutta kansa sanoi: älä mene; sillä jos me joudumme pakenemaan, ei he meistä tottele: jos puoli kuolee meistä, ei he siitä pidä lukua; sillä sinä olet niinkuin kymmenentuhatta meistä. Se on parempi, ettäs tulet meille avuksi kaupungista."],[18,4,"Kuningas sanoi heille: mitä te luulette teillenne olevan hyväksi, sen minä teen. Ja kuningas seisoi portilla, ja kansa kävi sadoin ja tuhansin ulos.","Kuningas sanoi heille: mitä te luulette teillenne olevan hyväksi, sen minä teen. Ja kuningas seisoi portilla, ja kansa kävi sadoin ja tuhansin ulos."],[18,5,"Ja kuningas käski Joabia, Abisaita ja Ittaita, sanoen: menkäät siviästi nuorukaisen Absalomin kanssa; ja kaikki kansa kuuli kuninkaan varoittavan jokaista päämiestä Absalomista.","Ja kuningas käski Joabia, Abisaita ja Ittaita, sanoen: menkäät siviästi nuorukaisen Absalomin kanssa; ja kaikki kansa kuuli kuninkaan varoittavan jokaista päämiestä Absalomista."],[18,6,"Ja kuin kansa tuli väljälle Israelia vastaan, niin oli sota Ephraimin metsässä.","Ja kuin kansa tuli väljälle Israelia vastaan, niin oli sota Ephraimin metsässä."],[18,7,"Ja Israelin kansa lyötiin siellä Davidin palvelioilta, että sinä päivänä tapahtui sangen suuri tappo: (ja kaatui) kaksikymmentä tuhatta miestä.","Ja Israelin kansa lyötiin siellä Davidin palvelioilta, että sinä päivänä tapahtui sangen suuri tappo: (ja kaatui) kaksikymmentä tuhatta miestä."],[18,8,"Ja sota hajoitettiin siellä kaikkeen maahan; ja metsä surmasi usiamman sinä päivänä kansasta, kuin miekka.","Ja sota hajoitettiin siellä kaikkeen maahan; ja metsä surmasi usiamman sinä päivänä kansasta, kuin miekka."],[18,9,"Ja Absalom kohtasi Davidin palvelioita ja ajoi muulilla. Ja kun muuli tuli oksaisen paksun tammen alle, tarttui hänen päänsä tammeen, ja hän jäi riippumaan taivaan ja maan välille, mutta muuli juoksi matkaansa hänen altansa.","Ja Absalom kohtasi Davidin palvelioita ja ajoi muulilla. Ja kun muuli tuli oksaisen paksun tammen alle, tarttui hänen päänsä tammeen, ja hän jäi riippumaan taivaan ja maan välille, mutta muuli juoksi matkaansa hänen altansa."],[18,10,"Kuin yksi mies sen näki, ilmoitti hän Joabille, ja sanoi: katso, minä näin Absalomin riippuvan tammessa.","Kuin yksi mies sen näki, ilmoitti hän Joabille, ja sanoi: katso, minä näin Absalomin riippuvan tammessa."],[18,11,"Ja Joab sanoi miehelle, joka sen hänelle ilmoitti: katso, näitkös sen? Miksi et lyönyt häntä siitä maahan? Niin minä olisin minun puolestani antanut sinulle kymmenen hopiapenninkiä ja yhden vyön.","Ja Joab sanoi miehelle, joka sen hänelle ilmoitti: katso, näitkös sen? Miksi et lyönyt häntä siitä maahan? Niin minä olisin minun puolestani antanut sinulle kymmenen hopiapenninkiä ja yhden vyön."],[18,12,"Mies sanoi Joabille: jos olisin saanut punnittuna tuhannen hopiapenninkiä minun käteeni, en minä vielä sittenkään olisi kättäni satuttanut kuninkaan poikaan; sillä kuningas käski meidän kuullemme sinua ja Abisaita ja Ittaita, sanoen: pitäkäät vaari nuorukaisesta Absalomista.","Mies sanoi Joabille: jos olisin saanut punnittuna tuhannen hopiapenninkiä minun käteeni, en minä vielä sittenkään olisi kättäni satuttanut kuninkaan poikaan; sillä kuningas käski meidän kuullemme sinua ja Abisaita ja Ittaita, sanoen: pitäkäät vaari nuorukaisesta Absalomista."],[18,13,"Eli jos minä vielä jotakin vääryyttä tehnyt olisin sieluni vahingoksi (sillä ei kuninkaan edessä mitään salattu ole), niin sinä olisit ollut minua vastaan.","Eli jos minä vielä jotakin vääryyttä tehnyt olisin sieluni vahingoksi (sillä ei kuninkaan edessä mitään salattu ole), niin sinä olisit ollut minua vastaan."],[18,14,"Joab sanoi: en minä enää sinun tykönäs viivy; ja otti kolme keihästä käteensä ja pisti ne Absalomin sydämeen, kuin hän vielä tammessa eli;","Joab sanoi: en minä enää sinun tykönäs viivy; ja otti kolme keihästä käteensä ja pisti ne Absalomin sydämeen, kuin hän vielä tammessa eli;"],[18,15,"Ja kymmenen nuorukaista Joabin asetten kantajista piirittivät hänen; he löivät ja tappoivat Absalomin.","Ja kymmenen nuorukaista Joabin asetten kantajista piirittivät hänen; he löivät ja tappoivat Absalomin."],[18,16,"Niin puhalsi Joab basunaan, ja kansa palasi ajamasta Israelia takaa; sillä Joab tahtoi armahtaa kansaa.","Niin puhalsi Joab basunaan, ja kansa palasi ajamasta Israelia takaa; sillä Joab tahtoi armahtaa kansaa."],[18,17,"Ja he ottivat Absalomin, ja heittivät metsässä suureen kuoppaan, ja panivat suuren kiviroukkion hänen päällensä. Ja koko Israel pakeni kukin majallensa.","Ja he ottivat Absalomin, ja heittivät metsässä suureen kuoppaan, ja panivat suuren kiviroukkion hänen päällensä. Ja koko Israel pakeni kukin majallensa."],[18,18,"Vaan Absalom oli eläissänsä pystyttänyt itsellensä patsaan, se seisoo Kuninkaanlaaksossa; sillä hän sanoi: ei minulla ole yhtään poikaa, olkoon tämä sentähden minun nimeni muistoksi. Ja kutsui sen patsaan nimellänsä, joka vielä tänäpänä kutsutaan Absalomin paikaksi.","Vaan Absalom oli eläissänsä pystyttänyt itsellensä patsaan, se seisoo Kuninkaanlaaksossa; sillä hän sanoi: ei minulla ole yhtään poikaa, olkoon tämä sentähden minun nimeni muistoksi. Ja kutsui sen patsaan nimellänsä, joka vielä tänäpänä kutsutaan Absalomin paikaksi."],[18,19,"Ahimaats Zadokin poika sanoi: minä juoksen nyt ja ilmoitan kuninkaalle, Herran saattaneeksi hänelle oikeuden hänen vihollistensa käsistä.","Ahimaats Zadokin poika sanoi: minä juoksen nyt ja ilmoitan kuninkaalle, Herran saattaneeksi hänelle oikeuden hänen vihollistensa käsistä."],[18,20,"Joab sanoi hänelle: et sinä yhtään hyvää sanomaa vie tänäpänä, vie toisena päivänä sanomia, vaan ei sinun pidä tänäpänä sanomaa saattaman; sillä kuninkaan poika on kuollut.","Joab sanoi hänelle: et sinä yhtään hyvää sanomaa vie tänäpänä, vie toisena päivänä sanomia, vaan ei sinun pidä tänäpänä sanomaa saattaman; sillä kuninkaan poika on kuollut."],[18,21,"Mutta Joab sanoi Kuusille: mene ja ilmoita kuninkaalle mitäs nähnyt olet. Ja Kuusi kumarsi Joabia ja juoksi.","Mutta Joab sanoi Kuusille: mene ja ilmoita kuninkaalle mitäs nähnyt olet. Ja Kuusi kumarsi Joabia ja juoksi."],[18,22,"Mutta Ahimaats Zadokin poika sanoi vielä kerran Joabille: vaikka mitä olis, minä juoksen myös Kuusin perässä. Joab sanoi: miksi sinä juokset, poikani? Et sinä vie yhtään hyvää sanomaa.","Mutta Ahimaats Zadokin poika sanoi vielä kerran Joabille: vaikka mitä olis, minä juoksen myös Kuusin perässä. Joab sanoi: miksi sinä juokset, poikani? Et sinä vie yhtään hyvää sanomaa."],[18,23,"Hän vastasi: vaikka mitä olis, minä juoksen. Hän sanoi hänelle: juokse. Niin Ahimaats juoksi kohdastansa ja ennätti Kuusin.","Hän vastasi: vaikka mitä olis, minä juoksen. Hän sanoi hänelle: juokse. Niin Ahimaats juoksi kohdastansa ja ennätti Kuusin."],[18,24,"Mutta David istui kahden portin vaiheella, ja vartia meni portin kohdalle, muurin katon päälle, nosti silmänsä ja näki miehen juoksevan yksinänsä,","Mutta David istui kahden portin vaiheella, ja vartia meni portin kohdalle, muurin katon päälle, nosti silmänsä ja näki miehen juoksevan yksinänsä,"],[18,25,"Ja vartia huusi ja sanoi sen kuninkaalle. Kuningas sanoi: jos hän on yksin, niin hän on hyvä sanantuoja; Ja hän aina juoksi ja tuli lähemmä.","Ja vartia huusi ja sanoi sen kuninkaalle. Kuningas sanoi: jos hän on yksin, niin hän on hyvä sanantuoja; Ja hän aina juoksi ja tuli lähemmä."],[18,26,"Niin vartia näki toisen miehen juoksevan, ja huusi ovenvartialle ja sanoi: katso, yksi mies juoksee yksinänsä. Kuningas sanoi: se on myös hyvä sanantuoja.","Niin vartia näki toisen miehen juoksevan, ja huusi ovenvartialle ja sanoi: katso, yksi mies juoksee yksinänsä. Kuningas sanoi: se on myös hyvä sanantuoja."],[18,27,"Vartia sanoi: minulle näkyy ensimäisen juoksu, niinkuin se olis Ahimaatsin Zadokin pojan juoksu. Ja kuningas sanoi: se on hyvä mies ja tuo hyvää sanomaa.","Vartia sanoi: minulle näkyy ensimäisen juoksu, niinkuin se olis Ahimaatsin Zadokin pojan juoksu. Ja kuningas sanoi: se on hyvä mies ja tuo hyvää sanomaa."],[18,28,"Ahimaats huusi ja sanoi kuninkaalle: Rauha! ja kumarsi kuninkaan edessä maahan kasvoillensa ja sanoi: kiitetty olkoon Herra sinun Jumalas, joka ne miehet on antanut sinun kätees, jotka nostivat kätensä herraani kuningasta vastaan!","Ahimaats huusi ja sanoi kuninkaalle: Rauha! ja kumarsi kuninkaan edessä maahan kasvoillensa ja sanoi: kiitetty olkoon Herra sinun Jumalas, joka ne miehet on antanut sinun kätees, jotka nostivat kätensä herraani kuningasta vastaan!"],[18,29,"Kuningas sanoi: onko nuorukainen Absalom rauhassa? Ahimaats sanoi: minä näin suuren metelin, kuin Joab kuninkaan palvelia lähetti minun sinun palvelias tänne, ja en minä tiedä, mikä se oli.","Kuningas sanoi: onko nuorukainen Absalom rauhassa? Ahimaats sanoi: minä näin suuren metelin, kuin Joab kuninkaan palvelia lähetti minun sinun palvelias tänne, ja en minä tiedä, mikä se oli."],[18,30,"Kuningas sanoi: mene erinäs ja seiso siellä. Ja hän meni erinänsä ja seisoi siellä.","Kuningas sanoi: mene erinäs ja seiso siellä. Ja hän meni erinänsä ja seisoi siellä."],[18,31,"Ja katso, Kuusi tuli ja sanoi: täällä ovat hyvät sanomat, herrani kuningas: Herra on saattanut tänäpänä sinulle oikeuden kaikkein kädestä, jotka nousivat sinua vastaan.","Ja katso, Kuusi tuli ja sanoi: täällä ovat hyvät sanomat, herrani kuningas: Herra on saattanut tänäpänä sinulle oikeuden kaikkein kädestä, jotka nousivat sinua vastaan."],[18,32,"Kuningas sanoi Kuusille: onko nuorukainen Absalom rauhassa? Kuusi sanoi: tapahtukoon niin herrani kuninkaan vihollisille, kuin nuorukaiselle on tapahtunut, ja kaikille niille, jotka heitänsä asettavat sinua vastaan sinulle vahingoksi!","Kuningas sanoi Kuusille: onko nuorukainen Absalom rauhassa? Kuusi sanoi: tapahtukoon niin herrani kuninkaan vihollisille, kuin nuorukaiselle on tapahtunut, ja kaikille niille, jotka heitänsä asettavat sinua vastaan sinulle vahingoksi!"],[18,33,"Niin tuli kuningas murheelliseksi, ja meni portin ylistupaan ja itki, ja sanoi mennessänsä näin: poikani Absalom! poikani, poikani Absalom! 0, jospa minä olisin kuollut sinun siassas, oi, Absalom poikani, minun poikani!","Niin tuli kuningas murheelliseksi, ja meni portin ylistupaan ja itki, ja sanoi mennessänsä näin: poikani Absalom! poikani, poikani Absalom! 0, jospa minä olisin kuollut sinun siassas, oi, Absalom poikani, minun poikani!"],[19,1,"Ja Joabille ilmoitettiin: katso, kuningas itkee ja suree Absalomia.","Ja Joabille ilmoitettiin: katso, kuningas itkee ja suree Absalomia."],[19,2,"Ja sinä päivänä oli voitosta itku kaiken kansan seassa; sillä kansa oli kuullut sinä päivänä sanottavan kuninkaan olevan murheellisen poikansa tähden.","Ja sinä päivänä oli voitosta itku kaiken kansan seassa; sillä kansa oli kuullut sinä päivänä sanottavan kuninkaan olevan murheellisen poikansa tähden."],[19,3,"Ja kansa lymytti sinä päivänä itsensä ja ei tullut kaupunkiin; niinkuin joku kansa varastaa itsensä, joka häpee paetessansa sodassa.","Ja kansa lymytti sinä päivänä itsensä ja ei tullut kaupunkiin; niinkuin joku kansa varastaa itsensä, joka häpee paetessansa sodassa."],[19,4,"Mutta kuningas peitti kasvonsa ja huusi suurella äänellä: voi minun poikani Absalom! Absalom, minun poikani, minun poikani!","Mutta kuningas peitti kasvonsa ja huusi suurella äänellä: voi minun poikani Absalom! Absalom, minun poikani, minun poikani!"],[19,5,"Niin Joab tuli kuninkaan tykö huoneeseen ja sanoi: sinä olet häväissyt tänäpänä kaikki sinun palvelias, jotka ovat sinun, ja sinun poikais ja tytärtes, emäntäis ja jalkavaimois hengen hädästä pelastaneet tänäpänä;","Niin Joab tuli kuninkaan tykö huoneeseen ja sanoi: sinä olet häväissyt tänäpänä kaikki sinun palvelias, jotka ovat sinun, ja sinun poikais ja tytärtes, emäntäis ja jalkavaimois hengen hädästä pelastaneet tänäpänä;"],[19,6,"Ettäs rakastat niitä, jotka sinua vihaavat, ja vihaat niitä, jotka sinua rakastavat; sillä tänäpänä sinä ilmoitit sinus ei lukua pitävän sodanpäämiehistä eli palvelioistas, ja siitä minä tänäpänä ymmärrän, että jos Absalom ainoastansa eläis ja me kaikki olisimme tänäpänä kuolleet, se sinulle kelpais.","Ettäs rakastat niitä, jotka sinua vihaavat, ja vihaat niitä, jotka sinua rakastavat; sillä tänäpänä sinä ilmoitit sinus ei lukua pitävän sodanpäämiehistä eli palvelioistas, ja siitä minä tänäpänä ymmärrän, että jos Absalom ainoastansa eläis ja me kaikki olisimme tänäpänä kuolleet, se sinulle kelpais."],[19,7,"Nouse siis nyt ja käy ulos, ja puhu suloisesti palvelioilles; sillä minä vannon sinulle Herran kautta, että jolles sinä käy ulos, niin ei ole yksikään mies sinun tykönäs tätä yötä; se on sinulle pahempi, kuin kaikki se vastoinkäyminen, joka sinulle hamasta nuoruudestas tähän asti on tapahtunut.","Nouse siis nyt ja käy ulos, ja puhu suloisesti palvelioilles; sillä minä vannon sinulle Herran kautta, että jolles sinä käy ulos, niin ei ole yksikään mies sinun tykönäs tätä yötä; se on sinulle pahempi, kuin kaikki se vastoinkäyminen, joka sinulle hamasta nuoruudestas tähän asti on tapahtunut."],[19,8,"Niin nousi kuningas, ja istui portilla. Ja se ilmoitettiin kaikelle kansalle, sanoen: katso, kuningas istuu portilla. Niin kaikki kansa tuli kuninkaan eteen; vaan Israel oli paennut itsekukin majoillensa.","Niin nousi kuningas, ja istui portilla. Ja se ilmoitettiin kaikelle kansalle, sanoen: katso, kuningas istuu portilla. Niin kaikki kansa tuli kuninkaan eteen; vaan Israel oli paennut itsekukin majoillensa."],[19,9,"Ja kaikki kansa Israelin sukukunnista riiteli keskenänsä, sanoen: kuningas on meitä auttanut meidän vihamiestemme käsistä, Ja hän on meitä pelastanut Philistealaisilta: ja nyt täytyy hänen maakunnasta paeta Absalomin tähden.","Ja kaikki kansa Israelin sukukunnista riiteli keskenänsä, sanoen: kuningas on meitä auttanut meidän vihamiestemme käsistä, Ja hän on meitä pelastanut Philistealaisilta: ja nyt täytyy hänen maakunnasta paeta Absalomin tähden."],[19,10,"Mutta Absalom, jonka me voitelimme meillemme, on kuollut sodassa, miksi te nyt olette niin hiljaiset noutamaan kuningasta?","Mutta Absalom, jonka me voitelimme meillemme, on kuollut sodassa, miksi te nyt olette niin hiljaiset noutamaan kuningasta?"],[19,11,"Mutta kuningas David lähetti pappein Zadokin ja AbJatarin tykö, ja käski heille sanoa: puhukaat vanhimmille Juudassa, sanoen: miksi te olette viimeiset kuningasta kotiansa noutamaan? Sillä kaiken Israelin puhe oli ilmoitettu kuninkaan huoneessa.","Mutta kuningas David lähetti pappein Zadokin ja AbJatarin tykö, ja käski heille sanoa: puhukaat vanhimmille Juudassa, sanoen: miksi te olette viimeiset kuningasta kotiansa noutamaan? Sillä kaiken Israelin puhe oli ilmoitettu kuninkaan huoneessa."],[19,12,"Te olette minun veljeni, minun luuni ja minun lihani: miksi te olette viimeiset noutamaan jälleen kuningasta?","Te olette minun veljeni, minun luuni ja minun lihani: miksi te olette viimeiset noutamaan jälleen kuningasta?"],[19,13,"Ja sanokaat Amasalle: etkös ole minun luuni ja lihani? Jumala tehköön minulle niin ja niin, jollei sinun pidä tuleman sotaherraksi minun edessäni Joabin siaan sinun elinaikanas.","Ja sanokaat Amasalle: etkös ole minun luuni ja lihani? Jumala tehköön minulle niin ja niin, jollei sinun pidä tuleman sotaherraksi minun edessäni Joabin siaan sinun elinaikanas."],[19,14,"Ja hän käänsi kaikkein Juudan miesten sydämet niinkuin yhden miehen. Ja he lähettivät kuninkaalle sanan: palaja sinä ja kaikki palvelias.","Ja hän käänsi kaikkein Juudan miesten sydämet niinkuin yhden miehen. Ja he lähettivät kuninkaalle sanan: palaja sinä ja kaikki palvelias."],[19,15,"Niin kuningas tuli jälleen. Ja kuin hän lähestyi Jordania, olivat kaikki Juudan miehet tulleet Gilgaliin menemään kuningasta vastaan ja saattamaan kuningasta Jordanin ylitse.","Niin kuningas tuli jälleen. Ja kuin hän lähestyi Jordania, olivat kaikki Juudan miehet tulleet Gilgaliin menemään kuningasta vastaan ja saattamaan kuningasta Jordanin ylitse."],[19,16,"Ja Simei Geran poika, Jeminin pojan Bahurimista, kiiruhti itsensä ja meni alas Juudan miesten kanssa kuningas Davidia vastaan.","Ja Simei Geran poika, Jeminin pojan Bahurimista, kiiruhti itsensä ja meni alas Juudan miesten kanssa kuningas Davidia vastaan."],[19,17,"Ja hänen kanssansa oli tuhannen miestä BenJaminista, oli myös Ziba Saulin huoneen palvelia viidentoistakymmenen poikansa kanssa ja kahdenkymmenen palvellansa kanssa; ja he kiiruhtivat heitänsä Jordanin ylitse kuninkaan eteen.","Ja hänen kanssansa oli tuhannen miestä BenJaminista, oli myös Ziba Saulin huoneen palvelia viidentoistakymmenen poikansa kanssa ja kahdenkymmenen palvellansa kanssa; ja he kiiruhtivat heitänsä Jordanin ylitse kuninkaan eteen."],[19,18,"He valmistivat alukset kuningasta ja hänen palvelioitansa ylitse vietää, tehdäksensä sitä kuninkaalle mielen nouteeksi. Mutta Simei Geran poika lankesi polvillensa kuninkaan eteen hänen mennessä Jordanin ylitse,","He valmistivat alukset kuningasta ja hänen palvelioitansa ylitse vietää, tehdäksensä sitä kuninkaalle mielen nouteeksi. Mutta Simei Geran poika lankesi polvillensa kuninkaan eteen hänen mennessä Jordanin ylitse,"],[19,19,"Ja sanoi kuninkaalle: minun herrani, älä lue minulle sitä pahaa tekoa, älä myös muistele sinun palvelias rikosta, jolla hän sinun vihoitti, herra kuningas, lähteissäs Jerusalemista: älköön kuningas sitä sydämeensä panko.","Ja sanoi kuninkaalle: minun herrani, älä lue minulle sitä pahaa tekoa, älä myös muistele sinun palvelias rikosta, jolla hän sinun vihoitti, herra kuningas, lähteissäs Jerusalemista: älköön kuningas sitä sydämeensä panko."],[19,20,"Sillä sinun palvelias tuntee syntiä tehneensä, ja katso, minä olen tänäpänä lähtenyt ensimäisenä koko Josephin huoneesta herraani kuningasta vastaan.","Sillä sinun palvelias tuntee syntiä tehneensä, ja katso, minä olen tänäpänä lähtenyt ensimäisenä koko Josephin huoneesta herraani kuningasta vastaan."],[19,21,"Mutta Abisai ZeruJan poika vastasi ja sanoi: eikö Simein sen edessä pitäisi kuoleman, että hän kirosi Herran voideltua?","Mutta Abisai ZeruJan poika vastasi ja sanoi: eikö Simein sen edessä pitäisi kuoleman, että hän kirosi Herran voideltua?"],[19,22,"Ja David vastasi: mitä minun on teidän kanssanne, te ZeruJan pojat, että tahdotte tänäpänä minulle tulla saatanaksi? Pitäiskö jonkun tänäpänä kuoleman Israelista? Luuletteko, etten minä tiedä tänäpänä itseni tulleeksi kunininkaaksi Israelissa?","Ja David vastasi: mitä minun on teidän kanssanne, te ZeruJan pojat, että tahdotte tänäpänä minulle tulla saatanaksi? Pitäiskö jonkun tänäpänä kuoleman Israelista? Luuletteko, etten minä tiedä tänäpänä itseni tulleeksi kunininkaaksi Israelissa?"],[19,23,"Sanoi siis kuningas Simeille: ei sinun pidä kuoleman; ja kuningas vannoi hänelle.","Sanoi siis kuningas Simeille: ei sinun pidä kuoleman; ja kuningas vannoi hänelle."],[19,24,"Tuli myös MephiBoset Saulin poika kuningasta vastaan, pesemättömillä jaloilla ja ajelemattomalla parralla; ei hän ollut myös pessyt vaatteitansa siitä päivästä, kuin kuningas läksi ja rauhassa jälleen palasi.","Tuli myös MephiBoset Saulin poika kuningasta vastaan, pesemättömillä jaloilla ja ajelemattomalla parralla; ei hän ollut myös pessyt vaatteitansa siitä päivästä, kuin kuningas läksi ja rauhassa jälleen palasi."],[19,25,"Kuin hän tuli Jerusalemissa kuningasta vastaan, sanoi kuningas hänelle: miksi et minun kanssani tullut, MephiBoset?","Kuin hän tuli Jerusalemissa kuningasta vastaan, sanoi kuningas hänelle: miksi et minun kanssani tullut, MephiBoset?"],[19,26,"Ja hän sanoi: herra kuningas, minun palveliani on pettänyt minun; sillä palvelias ajatteli: minä satuloitsen aasin, ajan ja vaellan sillä kuninkaan tykö; sillä palvelias on ontuva.","Ja hän sanoi: herra kuningas, minun palveliani on pettänyt minun; sillä palvelias ajatteli: minä satuloitsen aasin, ajan ja vaellan sillä kuninkaan tykö; sillä palvelias on ontuva."],[19,27,"Ja vielä päälliseksi on hän kantanut minun herrani kuninkaan edessä palvelias päälle; vaan herrani kuningas on kuin Jumalan enkeli, tee siis mitä sinulle on kelvollinen.","Ja vielä päälliseksi on hän kantanut minun herrani kuninkaan edessä palvelias päälle; vaan herrani kuningas on kuin Jumalan enkeli, tee siis mitä sinulle on kelvollinen."],[19,28,"Sillä koko minun isäni huone ei ole muu ollut kuin kuoleman kansa herrani kuninkaan edessä, ja sinä olet palvelias istuttanut niiden sekaan, jotka sinun pöydältäs syövät; mikä oikeus on minulla enää huutaa kuninkaan tykö?","Sillä koko minun isäni huone ei ole muu ollut kuin kuoleman kansa herrani kuninkaan edessä, ja sinä olet palvelias istuttanut niiden sekaan, jotka sinun pöydältäs syövät; mikä oikeus on minulla enää huutaa kuninkaan tykö?"],[19,29,"Kuningas sanoi hänelle: mitäs tahdot enää puhua asiastas? Minä olen sanonut: sinun ja Ziban pitää keskenänsä jakaman pellon.","Kuningas sanoi hänelle: mitäs tahdot enää puhua asiastas? Minä olen sanonut: sinun ja Ziban pitää keskenänsä jakaman pellon."],[19,30,"Niin MephiBoset sanoi kuninkaalle: ottakaan hän sen kokonansa, että herrani kuningas on rauhassa kotiansa palannut.","Niin MephiBoset sanoi kuninkaalle: ottakaan hän sen kokonansa, että herrani kuningas on rauhassa kotiansa palannut."],[19,31,"Ja Barsillai Gileadilainen tuli Rogelimista ja meni kuninkaan kanssa Jordanin ylitse, saattamaan häntä Jordanin ylitse.","Ja Barsillai Gileadilainen tuli Rogelimista ja meni kuninkaan kanssa Jordanin ylitse, saattamaan häntä Jordanin ylitse."],[19,32,"Ja Barsillai oli sangen ijällinen, jo kahdeksankymmenen vuotinen; hän oli ravinnut kuningasta, kuin hän Mahanaimissa oli; sillä hän oli sangen jalo mies.","Ja Barsillai oli sangen ijällinen, jo kahdeksankymmenen vuotinen; hän oli ravinnut kuningasta, kuin hän Mahanaimissa oli; sillä hän oli sangen jalo mies."],[19,33,"Ja kuningas sanoi Barsillaille: seuraa minua, minä ravitsen sinun minun kanssani Jerusalemissa.","Ja kuningas sanoi Barsillaille: seuraa minua, minä ravitsen sinun minun kanssani Jerusalemissa."],[19,34,"Mutta Barsillai sanoi kuninkaalle: kuinka monta vuotta minulla enää on elää, että minä menisin kuninkaan kanssa Jerusalemiin?","Mutta Barsillai sanoi kuninkaalle: kuinka monta vuotta minulla enää on elää, että minä menisin kuninkaan kanssa Jerusalemiin?"],[19,35,"Minä olen jo tänäpänä kahdeksankymmenen ajastaikainen, tietäisinkö minä, mikä hyvä eli paha olis? eli maistaisko palvelias, mitä hän syö ja juo? taikka kuulisinko minä silleen veisaajain ja laulajain ääntä? Miksi palvelias pitäis vaivaaman herraani kuningasta?","Minä olen jo tänäpänä kahdeksankymmenen ajastaikainen, tietäisinkö minä, mikä hyvä eli paha olis? eli maistaisko palvelias, mitä hän syö ja juo? taikka kuulisinko minä silleen veisaajain ja laulajain ääntä? Miksi palvelias pitäis vaivaaman herraani kuningasta?"],[19,36,"Sinun palvelias menee vähä Jordanin ylitse kuninkaan kanssa: minkätähden kuningas tahtoo minulle näin kostaa?","Sinun palvelias menee vähä Jordanin ylitse kuninkaan kanssa: minkätähden kuningas tahtoo minulle näin kostaa?"],[19,37,"Salli siis nyt palvelias palata jällensä, että minä kuolisin minun kaupungissani ja haudattaisiin isäni ja äitini hautaan: ja katso, tässä on sinun palvelias Kimeham, hän menköön herrani kuninkaan kanssa: ja tee hänelle, mitä sinulle on kelvollinen.","Salli siis nyt palvelias palata jällensä, että minä kuolisin minun kaupungissani ja haudattaisiin isäni ja äitini hautaan: ja katso, tässä on sinun palvelias Kimeham, hän menköön herrani kuninkaan kanssa: ja tee hänelle, mitä sinulle on kelvollinen."],[19,38,"Kuningas vastasi: Kimehamin pitää seuraaman minua ylitse, ja minä teen hänelle, mikä sinulle on otollinen, ja kaikki mitäs minulta anot, teen minä sinulle.","Kuningas vastasi: Kimehamin pitää seuraaman minua ylitse, ja minä teen hänelle, mikä sinulle on otollinen, ja kaikki mitäs minulta anot, teen minä sinulle."],[19,39,"Kuin kaikki kansa ja kuningas olivat menneet Jordinin ylitse, antoi kuningas Barsillain suuta ja siunasi häntä, ja hän palasi kotiansa.","Kuin kaikki kansa ja kuningas olivat menneet Jordinin ylitse, antoi kuningas Barsillain suuta ja siunasi häntä, ja hän palasi kotiansa."],[19,40,"Niin kuningas meni Gilgaliin ja Kimeham seurasi häntä; ja kaikki Juudan väki oli saattanut kuningasta ylitse, niin myös puoli Israelin kansasta.","Niin kuningas meni Gilgaliin ja Kimeham seurasi häntä; ja kaikki Juudan väki oli saattanut kuningasta ylitse, niin myös puoli Israelin kansasta."],[19,41,"Ja katso, silloin tulivat kaikki Israelin miehet kuninkaan tykö ja sanoivat hänelle: miksi meidän veljemme Juudan miehet ovat varastaneet sinun ja vieneet kuninkaan perheinensä Jordanin ylitse, kaikki myös Davidin miehet hänen kanssansa.","Ja katso, silloin tulivat kaikki Israelin miehet kuninkaan tykö ja sanoivat hänelle: miksi meidän veljemme Juudan miehet ovat varastaneet sinun ja vieneet kuninkaan perheinensä Jordanin ylitse, kaikki myös Davidin miehet hänen kanssansa."],[19,42,"Niin vastasivat kaikki Juudan miehet Israelin miehille: sillä kuningas on meitä läheisempi, miksi te sentähden niin närkästytte? Vai luuletteko te, että me jollakulla olemme kuninkaalta ravitut, taikka joitakin lahjoja saaneet?","Niin vastasivat kaikki Juudan miehet Israelin miehille: sillä kuningas on meitä läheisempi, miksi te sentähden niin närkästytte? Vai luuletteko te, että me jollakulla olemme kuninkaalta ravitut, taikka joitakin lahjoja saaneet?"],[19,43,"Niin Israelin miehet vastasivat Juudan miehiä, sanoen: meillä on kymmenen osaa kuninkaassa, enemmin myös David meille tulee kuin teille: kuinka siis sinä olet minua niin halvaksi lukenut, ettei minun olisi sopinut ensimäisenä olla kuningastani noutamassa? Mutta Juudan miehet puhuivat tuimemmin kuin Israelin miehet.","Niin Israelin miehet vastasivat Juudan miehiä, sanoen: meillä on kymmenen osaa kuninkaassa, enemmin myös David meille tulee kuin teille: kuinka siis sinä olet minua niin halvaksi lukenut, ettei minun olisi sopinut ensimäisenä olla kuningastani noutamassa? Mutta Juudan miehet puhuivat tuimemmin kuin Israelin miehet."],[20,1,"Mutta siihen tuli yksi kuuluisa Belialin mies, jonka nimi oli Seba Bikrin poika Jeministä; se soitti basunalla ja sanoi: ei meillä ole yhtäkään osaa Davidissa eikä yhtäkään perimistä Isain pojassa, itsekukin palatkaan majaansa, o Israel!","Mutta siihen tuli yksi kuuluisa Belialin mies, jonka nimi oli Seba Bikrin poika Jeministä; se soitti basunalla ja sanoi: ei meillä ole yhtäkään osaa Davidissa eikä yhtäkään perimistä Isain pojassa, itsekukin palatkaan majaansa, o Israel!"],[20,2,"Silloin jokainen Israelissa luopui Davidista, ja seurasivat Sebaa Bikrin poikaa. Mutta Juudan miehet riippuivat kuninkaassansa Jordanista Jerusalemiin asti.","Silloin jokainen Israelissa luopui Davidista, ja seurasivat Sebaa Bikrin poikaa. Mutta Juudan miehet riippuivat kuninkaassansa Jordanista Jerusalemiin asti."],[20,3,"Ja David tuli kotiansa Jerusalemiin, ja kuningas otti ne kymmenen jalkavaimoa, jotka hän oli jättänyt huonetta vartioitsemaan, ja antoi heidän kätkettää, ja elätti heitä ja ei mennyt heidän tykönsä; ja he olivat salvatut kuolemaansa asti leskeydessänsä.","Ja David tuli kotiansa Jerusalemiin, ja kuningas otti ne kymmenen jalkavaimoa, jotka hän oli jättänyt huonetta vartioitsemaan, ja antoi heidän kätkettää, ja elätti heitä ja ei mennyt heidän tykönsä; ja he olivat salvatut kuolemaansa asti leskeydessänsä."],[20,4,"Ja kuningas sanoi Amasalle: kokoa minun tyköni Juudan miehet kolmena päivänä, ja sinun pitää myös itse läsnä oleman.","Ja kuningas sanoi Amasalle: kokoa minun tyköni Juudan miehet kolmena päivänä, ja sinun pitää myös itse läsnä oleman."],[20,5,"Niin Amasa meni kokoomaan Juudan miehiä, ja hän viipyi määrätyn ajan ylitse.","Niin Amasa meni kokoomaan Juudan miehiä, ja hän viipyi määrätyn ajan ylitse."],[20,6,"Niin David sanoi Abisaille: nyt Seba Bikrin poika enempi meitä vahingoitsee kuin Absalom: ota siis herras palveliat ja aja häntä takaa, ettei hän löytäisi vahvoja kaupungeita ja pääsisi meidän silmäimme edestä.","Niin David sanoi Abisaille: nyt Seba Bikrin poika enempi meitä vahingoitsee kuin Absalom: ota siis herras palveliat ja aja häntä takaa, ettei hän löytäisi vahvoja kaupungeita ja pääsisi meidän silmäimme edestä."],[20,7,"Silloin läksivät hänen kanssansa Joabin miehet, ja Kretit ja Pletit, ja kaikki väkevät. Ja he läksivät Jerusalemista ajamaan Sebaa Bikrin poikaa takaa.","Silloin läksivät hänen kanssansa Joabin miehet, ja Kretit ja Pletit, ja kaikki väkevät. Ja he läksivät Jerusalemista ajamaan Sebaa Bikrin poikaa takaa."],[20,8,"Kuin he joutuivat suuren vahan tykö Gibeoniin, tuli Amasa heidän eteensä. Mutta Joab oli vyötetty päällisvaatteissansa, ja sen päällä miekan vyö, joka riippui hänen kupeissansa tupessa, ja koska hän kävi, taisi se pudota.","Kuin he joutuivat suuren vahan tykö Gibeoniin, tuli Amasa heidän eteensä. Mutta Joab oli vyötetty päällisvaatteissansa, ja sen päällä miekan vyö, joka riippui hänen kupeissansa tupessa, ja koska hän kävi, taisi se pudota."],[20,9,"Ja Joab sanoi Amasalle: oletkos rauhassa, minun veljeni? Ja Joab tarttui oikialla kädellänsä Amasan partaan, suuta antaaksensa hänen.","Ja Joab sanoi Amasalle: oletkos rauhassa, minun veljeni? Ja Joab tarttui oikialla kädellänsä Amasan partaan, suuta antaaksensa hänen."],[20,10,"Mutta ei Amasa ottanut vaaria miekasta joka oli Joabin kädessä: ja hän pisti sillä häntä vatsaan ja vuodatti hänen sisällyksensä maalle, eikä häntä enää pistänyt, ja hän kuoli. Mutta Joab ja hänen veljensä Abisai ajoivat Sebaa Bikrin poikaa takaa.","Mutta ei Amasa ottanut vaaria miekasta joka oli Joabin kädessä: ja hän pisti sillä häntä vatsaan ja vuodatti hänen sisällyksensä maalle, eikä häntä enää pistänyt, ja hän kuoli. Mutta Joab ja hänen veljensä Abisai ajoivat Sebaa Bikrin poikaa takaa."],[20,11,"Mutta yksi Joabin palvelioista seisoi hänen tykönänsä ja sanoi: kuka tahtoo pitää Joabin ja Davidin kanssa, hän seuratkaan Joabia!","Mutta yksi Joabin palvelioista seisoi hänen tykönänsä ja sanoi: kuka tahtoo pitää Joabin ja Davidin kanssa, hän seuratkaan Joabia!"],[20,12,"Mutta Amasa makasi tahrattuna veressä keskellä tietä. Kuin yksi näki sen, että kaikki kansa seisahti, siirsi hän Amasan tieltä kedolle ja heitti vaatteen hänen päällensä; sillä hän näki, että jokainen joka hänen tykönsä tuli, seisahti siihen.","Mutta Amasa makasi tahrattuna veressä keskellä tietä. Kuin yksi näki sen, että kaikki kansa seisahti, siirsi hän Amasan tieltä kedolle ja heitti vaatteen hänen päällensä; sillä hän näki, että jokainen joka hänen tykönsä tuli, seisahti siihen."],[20,13,"Kuin hän oli tieltä siirretty, meni jokainen Joabin jälkeen, ajamaan Sebaa Bikrin poikaa takaa.","Kuin hän oli tieltä siirretty, meni jokainen Joabin jälkeen, ajamaan Sebaa Bikrin poikaa takaa."],[20,14,"Ja hän vaelsi kaikki Israelin sukukunnat lävitse Abelaan ja BetMaakaan ja koko Berimiin, ja ne kokoontuivat ja seurasivat myös häntä.","Ja hän vaelsi kaikki Israelin sukukunnat lävitse Abelaan ja BetMaakaan ja koko Berimiin, ja ne kokoontuivat ja seurasivat myös häntä."],[20,15,"Mutta kuin he tulivat, niin he piirittivät hänen Abelassa BetMaakan tykönä, ja rakensivat vallin kaupungin ympärille, joka seisoi muurin tasalla. Mutta kaikki kansa, joka Joabin myötä oli, karkasi muuria kukistamaan.","Mutta kuin he tulivat, niin he piirittivät hänen Abelassa BetMaakan tykönä, ja rakensivat vallin kaupungin ympärille, joka seisoi muurin tasalla. Mutta kaikki kansa, joka Joabin myötä oli, karkasi muuria kukistamaan."],[20,16,"Niin toimellinen vaimo huusi kaupungista: kuulkaat, kuulkaat! sanokaat Joabille, että hän tulee tänne lähes, minä puhuttelen häntä.","Niin toimellinen vaimo huusi kaupungista: kuulkaat, kuulkaat! sanokaat Joabille, että hän tulee tänne lähes, minä puhuttelen häntä."],[20,17,"Kuin hän tuli hänen tykönsä, sanoi vaimo: oletkos Joab? Hän vastasi: olen. Vaimo sanoi hänelle: kuule piikas sanat! Hän vastasi: minä kuulen.","Kuin hän tuli hänen tykönsä, sanoi vaimo: oletkos Joab? Hän vastasi: olen. Vaimo sanoi hänelle: kuule piikas sanat! Hän vastasi: minä kuulen."],[20,18,"Ja hän puhui, sanoen: muinoin sanottiin: joka kysellä tahtoo, hän kysykään Abelassa, ja niin se menestyi.","Ja hän puhui, sanoen: muinoin sanottiin: joka kysellä tahtoo, hän kysykään Abelassa, ja niin se menestyi."],[20,19,"Minä olen rauhallinen ja uskollinen (kaupunki) Israelissa, ja sinä tahdot tappaa sen kaupungin ja äidin Israelissa: miksis tahdot niellä Herran perimisen?","Minä olen rauhallinen ja uskollinen (kaupunki) Israelissa, ja sinä tahdot tappaa sen kaupungin ja äidin Israelissa: miksis tahdot niellä Herran perimisen?"],[20,20,"Silloin vastasi Joab ja sanoi: pois se, pois se minusta, että minä nielisin ja hävittäisin.","Silloin vastasi Joab ja sanoi: pois se, pois se minusta, että minä nielisin ja hävittäisin."],[20,21,"Ei asia niin ole; vaan yksi mies Ephraimin vuorelta nimeltä Seba Bikrin poika on nostanut kapinan David kuningasta vastaan: antakaat hän ainoastansa, ja minä erkanen kaupungista. Ja vaimo sanoi Joabille: katso, hänen päänsä pitää sinulle heitettämän muurin ylitse.","Ei asia niin ole; vaan yksi mies Ephraimin vuorelta nimeltä Seba Bikrin poika on nostanut kapinan David kuningasta vastaan: antakaat hän ainoastansa, ja minä erkanen kaupungista. Ja vaimo sanoi Joabille: katso, hänen päänsä pitää sinulle heitettämän muurin ylitse."],[20,22,"Ja vaimo tuli kaiken kansan tykö toimellansa. Ja he hakkasivat Seban Bikrin pojan pään pois ja heittivät Joabille. Ja hän soitti basunalla, ja he hajosivat kaikki kaupungin tyköä itsekukin majoihinsa; mutta Joab palasi Jerusalemiin kuninkaan tykö.","Ja vaimo tuli kaiken kansan tykö toimellansa. Ja he hakkasivat Seban Bikrin pojan pään pois ja heittivät Joabille. Ja hän soitti basunalla, ja he hajosivat kaikki kaupungin tyköä itsekukin majoihinsa; mutta Joab palasi Jerusalemiin kuninkaan tykö."],[20,23,"Ja Joab oli koko Israelin sotajoukon ylitse; vaan BenaJa Jojadan poika oli Kretin ja Pletin ylitse;","Ja Joab oli koko Israelin sotajoukon ylitse; vaan BenaJa Jojadan poika oli Kretin ja Pletin ylitse;"],[20,24,"Adoram oli verorahan haltia; Josaphat Ahiludin poika oli kansleri;","Adoram oli verorahan haltia; Josaphat Ahiludin poika oli kansleri;"],[20,25,"Ja Seja oli kirjoittaja; ja Zadok ja Abjatar olivat papit;","Ja Seja oli kirjoittaja; ja Zadok ja Abjatar olivat papit;"],[20,26,"Niin myös Ira Jairilainen oli Davidin ylimmäinen.","Niin myös Ira Jairilainen oli Davidin ylimmäinen."],[21,1,"Ja Davidin aikana oli kallis aika kolme vuotta järjestänsä: ja David etsi Herran kasvoja. Ja Herra sanoi, Saulin tähden ja sen verihuoneen tähden, että hän tappoi Gibeonilaiset.","Ja Davidin aikana oli kallis aika kolme vuotta järjestänsä: ja David etsi Herran kasvoja. Ja Herra sanoi, Saulin tähden ja sen verihuoneen tähden, että hän tappoi Gibeonilaiset."],[21,2,"Niin kuningas antoi kutsua Gibeonilaiset ja sanoi heille. Mutta Gibeonilaiset ei olleet Israelin lapsista, vaan jääneistä Amorilaisista: ja Israelin lapset olivat vannoneet heille, ja Saul etsi heitä lyödäksensä vihansa kiivaudessa Israelin ja Juudan lasten edessä.","Niin kuningas antoi kutsua Gibeonilaiset ja sanoi heille. Mutta Gibeonilaiset ei olleet Israelin lapsista, vaan jääneistä Amorilaisista: ja Israelin lapset olivat vannoneet heille, ja Saul etsi heitä lyödäksensä vihansa kiivaudessa Israelin ja Juudan lasten edessä."],[21,3,"Niin sanoi David Gibeonilaisille, mitä minun pitää teille tekemän? ja millä minun pitää sen sovittaman, että te siunaisitte Herran perikuntaa?","Niin sanoi David Gibeonilaisille, mitä minun pitää teille tekemän? ja millä minun pitää sen sovittaman, että te siunaisitte Herran perikuntaa?"],[21,4,"Niin vastasivat häntä Gibeonilaiset, ei ole meillä tekemistä hopiasta eli kullasta Saulin ja hänen huoneensa kanssa, eikä myös että joku surmattaisiin Israelista. Hän sanoi, mitä te tahdotte, että minä teille tekisin?","Niin vastasivat häntä Gibeonilaiset, ei ole meillä tekemistä hopiasta eli kullasta Saulin ja hänen huoneensa kanssa, eikä myös että joku surmattaisiin Israelista. Hän sanoi, mitä te tahdotte, että minä teille tekisin?"],[21,5,"He sanoivat kuninkaalle, sen miehen, joka meitä hukutti ja aikoi semmoista meitä vastaan, että meidän piti tuleman niin hävitetyksi, ettei meidän pitänyt seisovaiset oleman kaikissa Israelin maan rajoissa.","He sanoivat kuninkaalle, sen miehen, joka meitä hukutti ja aikoi semmoista meitä vastaan, että meidän piti tuleman niin hävitetyksi, ettei meidän pitänyt seisovaiset oleman kaikissa Israelin maan rajoissa."],[21,6,"Hänen huoneestansa annettakaan meille seitsemän miestä hirttääksemme heitä Herran edessä Saulin Gibeassa, Herran valitun. Kuningas sanoi, minä annan heidät teille.","Hänen huoneestansa annettakaan meille seitsemän miestä hirttääksemme heitä Herran edessä Saulin Gibeassa, Herran valitun. Kuningas sanoi, minä annan heidät teille."],[21,7,"Mutta kuningas armahti MephiBosetia, Jonatanin Saulin pojan poikaa, sen Herran valan tähden, joka oli heidän välillänsä, Davidin ja Jonatanin Saulin pojan välillä.","Mutta kuningas armahti MephiBosetia, Jonatanin Saulin pojan poikaa, sen Herran valan tähden, joka oli heidän välillänsä, Davidin ja Jonatanin Saulin pojan välillä."],[21,8,"Mutta kuningas otti ne kaksi Ritspan Aijan tyttären poikaa, jotka hän Saulille synnyttänyt oli, Armonin ja MephiBosetin, ja viisi Mikalin Saulin tyttären poikaa, jotka hän Hadrielille Barsillain pojalle synnyttänyt oli, joka oli Meholatilainen.","Mutta kuningas otti ne kaksi Ritspan Aijan tyttären poikaa, jotka hän Saulille synnyttänyt oli, Armonin ja MephiBosetin, ja viisi Mikalin Saulin tyttären poikaa, jotka hän Hadrielille Barsillain pojalle synnyttänyt oli, joka oli Meholatilainen."],[21,9,"Ja hän antoi ne Gibeonilaisten käsiin, ja he hirttivät ne vuorella Herran eteen. Ja ne seitsemän lankesivat yhdellä haavalla: ja niin he surmattiin ensimäisinä päivinä elonajasta, ohran leikkaamisen alussa.","Ja hän antoi ne Gibeonilaisten käsiin, ja he hirttivät ne vuorella Herran eteen. Ja ne seitsemän lankesivat yhdellä haavalla: ja niin he surmattiin ensimäisinä päivinä elonajasta, ohran leikkaamisen alussa."],[21,10,"Niin Ritspa Aijan tytär otti säkin ja levitti sen kalliolle elon alusta, siihenasti että vesi olis pisaroinnut taivaasta heidän päällensä, eikä sallinut taivaan lintuja tulla heidän päällensä päivällä, eikä metsän petoja yöllä.","Niin Ritspa Aijan tytär otti säkin ja levitti sen kalliolle elon alusta, siihenasti että vesi olis pisaroinnut taivaasta heidän päällensä, eikä sallinut taivaan lintuja tulla heidän päällensä päivällä, eikä metsän petoja yöllä."],[21,11,"Ja ilmoitettiin Davidille, mitä Ritspa, Aijan tytär, Saulin jalkavaimo, tehnyt oli.","Ja ilmoitettiin Davidille, mitä Ritspa, Aijan tytär, Saulin jalkavaimo, tehnyt oli."],[21,12,"Ja David läksi matkaan ja otti Saulin ja hänen poikansa Jonatanin luut Jabeksen asuvilta Gileadissa, jotka he Betsanin kadulta varastaneet olivat, jossa Philistealaiset heitä ripustaneet olivat siihen aikaan, kuin he surmasivat Saulin Gilboassa;","Ja David läksi matkaan ja otti Saulin ja hänen poikansa Jonatanin luut Jabeksen asuvilta Gileadissa, jotka he Betsanin kadulta varastaneet olivat, jossa Philistealaiset heitä ripustaneet olivat siihen aikaan, kuin he surmasivat Saulin Gilboassa;"],[21,13,"Ja otti sieltä Saulin luut ja hänen poikansa Jonatanin luut; ja he kokosivat myös niiden luut, jotka ripustetut olivat;","Ja otti sieltä Saulin luut ja hänen poikansa Jonatanin luut; ja he kokosivat myös niiden luut, jotka ripustetut olivat;"],[21,14,"Ja he hautasivat Saulin ja hänen poikansa Jonatanin luut BenJaminin maahan Zelaan, hänen isänsä Kisin hautaan, ja he tekivät kaikki niinkuin kuningas heille käskenyt oli: ja niin Jumala sovitettiin sitte maakunnalle.","Ja he hautasivat Saulin ja hänen poikansa Jonatanin luut BenJaminin maahan Zelaan, hänen isänsä Kisin hautaan, ja he tekivät kaikki niinkuin kuningas heille käskenyt oli: ja niin Jumala sovitettiin sitte maakunnalle."],[21,15,"Niin taas nousi Philistealaisten sota Israelia vastaan. Ja David meni sotimaan palvelioinensa Philistealaisia vastaan; ja David väsyi.","Niin taas nousi Philistealaisten sota Israelia vastaan. Ja David meni sotimaan palvelioinensa Philistealaisia vastaan; ja David väsyi."],[21,16,"Niin Jesbibenob, joka oli Raphan lapsia, jonka keihään ota painoi kolmesataa sikliä vaskea, ja jolla oli uudet sota-aseet, alkoi surmata Davidin.","Niin Jesbibenob, joka oli Raphan lapsia, jonka keihään ota painoi kolmesataa sikliä vaskea, ja jolla oli uudet sota-aseet, alkoi surmata Davidin."],[21,17,"Mutta Abisai ZeruJan poika autti häntä, ja löi Philistealaisen, ja tappoi hänen. Niin Davidin palveliat vannoivat hänelle ja sanoivat: ei sinun pidä enää menemän meidän kanssamme sotaan, ettet valkeutta Israelissa sammuttaisi.","Mutta Abisai ZeruJan poika autti häntä, ja löi Philistealaisen, ja tappoi hänen. Niin Davidin palveliat vannoivat hänelle ja sanoivat: ei sinun pidä enää menemän meidän kanssamme sotaan, ettet valkeutta Israelissa sammuttaisi."],[21,18,"Ja sen jälkeen tapahtui, että sota taas nousi Gobissa Philistealaista vastaan; ja Sibekai Husathilainen löi Saphan, joka myös oli Raphan lapsia.","Ja sen jälkeen tapahtui, että sota taas nousi Gobissa Philistealaista vastaan; ja Sibekai Husathilainen löi Saphan, joka myös oli Raphan lapsia."],[21,19,"Niin sota vielä nousi Gobissa Philistealaisia vastaan; ja Elhanan Jaere Oregiminin poika Betlehemiläinen löi Gatilaisen Goljatin, jonka keihään varsi oli niinkuin joku kangasorsi.","Niin sota vielä nousi Gobissa Philistealaisia vastaan; ja Elhanan Jaere Oregiminin poika Betlehemiläinen löi Gatilaisen Goljatin, jonka keihään varsi oli niinkuin joku kangasorsi."],[21,20,"Sitälähin nousi vielä sota Gatissa; ja siellä oli pitkä mies, jolla oli kuusi sormea käsissä ja kuusi varvasta jaloissa, se on yhteen lukien neljäkolmattakymmentä; hän oli myös syntynyt Raphalle.","Sitälähin nousi vielä sota Gatissa; ja siellä oli pitkä mies, jolla oli kuusi sormea käsissä ja kuusi varvasta jaloissa, se on yhteen lukien neljäkolmattakymmentä; hän oli myös syntynyt Raphalle."],[21,21,"Ja kuin hän pilkkasi Israelia, löi hänen Jonatan Davidin veljen Simean poika.","Ja kuin hän pilkkasi Israelia, löi hänen Jonatan Davidin veljen Simean poika."],[21,22,"Nämät neljä olivat syntyneet Raphalle Gatissa; ja he lankesivat Davidin ja hänen palveliainsa kätten kautta.","Nämät neljä olivat syntyneet Raphalle Gatissa; ja he lankesivat Davidin ja hänen palveliainsa kätten kautta."],[22,1,"Ja David puhui Herralle nämät veisun sanat sinä päivänä, jona Herra oli hänen vapahtanut kaikkein vihollistensa käsistä ja Saulin käsistä,","Ja David puhui Herralle nämät veisun sanat sinä päivänä, jona Herra oli hänen vapahtanut kaikkein vihollistensa käsistä ja Saulin käsistä,"],[22,2,"Ja sanoi: Herra on minun kallioni, ja minun linnani, ja minun vapahtajani;","Ja sanoi: Herra on minun kallioni, ja minun linnani, ja minun vapahtajani;"],[22,3,"Jumala on minun vahani, johon minä turvaan; minun kilpeni, ja minun autuuteni sarvi, ja minun varjelukseni, ja minun turvani; minun vapahtajani, joka minun pelastaa vääryydestä.","Jumala on minun vahani, johon minä turvaan; minun kilpeni, ja minun autuuteni sarvi, ja minun varjelukseni, ja minun turvani; minun vapahtajani, joka minun pelastaa vääryydestä."],[22,4,"Ylistettävää Herraa minä avukseni huudan; ja minä vapahdetaan vihollisistani.","Ylistettävää Herraa minä avukseni huudan; ja minä vapahdetaan vihollisistani."],[22,5,"Sillä kuoleman aallot ovat minun piirittäneet, ja Belialin ojat peljättivät minun.","Sillä kuoleman aallot ovat minun piirittäneet, ja Belialin ojat peljättivät minun."],[22,6,"Helvetin siteet kietoivat minun, ja kuoleman paulat ennättivät minun.","Helvetin siteet kietoivat minun, ja kuoleman paulat ennättivät minun."],[22,7,"Ahdistuksessani minä avukseni huudan Herraa, ja minun Jumalani tykö minä huudan; niin hän kuulee minun ääneni templissänsä, ja minun parkuni tulee hänen korviinsa.","Ahdistuksessani minä avukseni huudan Herraa, ja minun Jumalani tykö minä huudan; niin hän kuulee minun ääneni templissänsä, ja minun parkuni tulee hänen korviinsa."],[22,8,"Maa järisi ja vapisi, ja taivaan perustukset liikkuivat; he värisivät, kuin hän vihastui.","Maa järisi ja vapisi, ja taivaan perustukset liikkuivat; he värisivät, kuin hän vihastui."],[22,9,"Savu suitsi hänen sieramistansa ja kuluttavainen tuli hänen suustansa, niin että hiilet siitä syttyivät.","Savu suitsi hänen sieramistansa ja kuluttavainen tuli hänen suustansa, niin että hiilet siitä syttyivät."],[22,10,"Hän notkisti taivaat ja astui alas; ja synkiä pimeys oli hänen jalkainsa alla.","Hän notkisti taivaat ja astui alas; ja synkiä pimeys oli hänen jalkainsa alla."],[22,11,"Ja hän astui Kerubimin päälle ja lensi, ja näkyi tuulen sulkain päällä.","Ja hän astui Kerubimin päälle ja lensi, ja näkyi tuulen sulkain päällä."],[22,12,"Hän pani pimeyden majaksi ympärillensä, ja paksut ja vedestä mustat pilvet.","Hän pani pimeyden majaksi ympärillensä, ja paksut ja vedestä mustat pilvet."],[22,13,"Siitä kirkkaudesta hänen edessänsä paloivat tuliset hiilet.","Siitä kirkkaudesta hänen edessänsä paloivat tuliset hiilet."],[22,14,"Herra jylisti taivaassa, Ylimmäinen antoi pauhinansa.","Herra jylisti taivaassa, Ylimmäinen antoi pauhinansa."],[22,15,"Hän ampui nuolia ja hajoitti heitä, hän iski leimaukset ja peljätti heitä.","Hän ampui nuolia ja hajoitti heitä, hän iski leimaukset ja peljätti heitä."],[22,16,"Ja niin ilmestyivät meren kuljut, ja maan perustukset ilmaantuivat Herran kovasta nuhtelemisesta ja hänen sieramiensa hengen puhalluksesta.","Ja niin ilmestyivät meren kuljut, ja maan perustukset ilmaantuivat Herran kovasta nuhtelemisesta ja hänen sieramiensa hengen puhalluksesta."],[22,17,"Hän lähetti korkeudesta ja otti minun ja veti minun ulos suurista vesistä.","Hän lähetti korkeudesta ja otti minun ja veti minun ulos suurista vesistä."],[22,18,"Hän vapahti minun väkevistä vihollisistani, vainollisiltani, jotka olivat minua väkevämmät.","Hän vapahti minun väkevistä vihollisistani, vainollisiltani, jotka olivat minua väkevämmät."],[22,19,"Ne ennättivät minun tuskapäivänäni; mutta Herra tuli minun turvakseni.","Ne ennättivät minun tuskapäivänäni; mutta Herra tuli minun turvakseni."],[22,20,"Hän vei minun ulos lakialle, ja pelasti minun; sillä hän mielistyi minuun.","Hän vei minun ulos lakialle, ja pelasti minun; sillä hän mielistyi minuun."],[22,21,"Herra maksoi minulle vanhurskauteni jälkeen, hän antoi minulle kätteni puhtauden jälkeen.","Herra maksoi minulle vanhurskauteni jälkeen, hän antoi minulle kätteni puhtauden jälkeen."],[22,22,"Sillä minä pidän Herran tiet ja en ole jumalatoin minun Jumalaani vastaan.","Sillä minä pidän Herran tiet ja en ole jumalatoin minun Jumalaani vastaan."],[22,23,"Sillä kaikki hänen oikeutensa ovat silmäni edessä, ja hänen käskyjänsä en minä tyköäni hylkää,","Sillä kaikki hänen oikeutensa ovat silmäni edessä, ja hänen käskyjänsä en minä tyköäni hylkää,"],[22,24,"Vaan olen vakaa hänen edessänsä, ja vältän vääryyttä:","Vaan olen vakaa hänen edessänsä, ja vältän vääryyttä:"],[22,25,"Sentähden kostaa Herra minulle vanhurskauteni perästä, puhtauteni jälkeen hänen silmäinsä edessä.","Sentähden kostaa Herra minulle vanhurskauteni perästä, puhtauteni jälkeen hänen silmäinsä edessä."],[22,26,"Pyhäin kanssa sinä olet pyhä, ja toimellisten kanssa toimellinen.","Pyhäin kanssa sinä olet pyhä, ja toimellisten kanssa toimellinen."],[22,27,"Puhdasten kanssa sinä olet puhdas, ja nurjain kanssa sinä olet nurja.","Puhdasten kanssa sinä olet puhdas, ja nurjain kanssa sinä olet nurja."],[22,28,"Sinä vapahdat ahdistetun kansan ja sinun silmäs ovat korkeita vastaan, ja sinä nöyryytät ne.","Sinä vapahdat ahdistetun kansan ja sinun silmäs ovat korkeita vastaan, ja sinä nöyryytät ne."],[22,29,"Sillä sinä Herra olet valkeuteni: Herra valaisee pimeyteni.","Sillä sinä Herra olet valkeuteni: Herra valaisee pimeyteni."],[22,30,"Sillä sinun kauttas minä sotaväen lävitse juoksen, ja Jumalassani karkaan muurin ylitse.","Sillä sinun kauttas minä sotaväen lävitse juoksen, ja Jumalassani karkaan muurin ylitse."],[22,31,"Jumalan tie on täydellinen, Herran puhe tulella koeteltu: hän on kaikkein kilpi, jotka hänen päällensä uskaltavat.","Jumalan tie on täydellinen, Herran puhe tulella koeteltu: hän on kaikkein kilpi, jotka hänen päällensä uskaltavat."],[22,32,"Sillä kuka on Jumala, paitsi Herraa? ja kuka on kallio paitsi meidän Jumalaamme?","Sillä kuka on Jumala, paitsi Herraa? ja kuka on kallio paitsi meidän Jumalaamme?"],[22,33,"Jumala on väkevyyteni ja voimani: hän avaa minun tieni täydellisesti.","Jumala on väkevyyteni ja voimani: hän avaa minun tieni täydellisesti."],[22,34,"Hän tekee jalkani peurain kaltaiseksi, ja asettaa minun korkeuteni päälle.","Hän tekee jalkani peurain kaltaiseksi, ja asettaa minun korkeuteni päälle."],[22,35,"Hän opettaa käteni sotimaan ja käsivarteni vaskijoutsea jännittämään.","Hän opettaa käteni sotimaan ja käsivarteni vaskijoutsea jännittämään."],[22,36,"Ja sinä annoit minulle sinun autuutes kilven: Ja kuin sinä nöyryytät minun, teet sinä minun suureksi.","Ja sinä annoit minulle sinun autuutes kilven: Ja kuin sinä nöyryytät minun, teet sinä minun suureksi."],[22,37,"Sinä levitit minun askeleeni minun allani, ja ei minun kantapääni livistyneet.","Sinä levitit minun askeleeni minun allani, ja ei minun kantapääni livistyneet."],[22,38,"Minä ajan vihollisiani takaa ja hävitän heitä, Ja en palaja ennenkuin minä heidät hukutan.","Minä ajan vihollisiani takaa ja hävitän heitä, Ja en palaja ennenkuin minä heidät hukutan."],[22,39,"Minä hukutan heidät ja runtelen, ettei heidän pidä nouseman; heidän täytyy kaatua jalkaini alle.","Minä hukutan heidät ja runtelen, ettei heidän pidä nouseman; heidän täytyy kaatua jalkaini alle."],[22,40,"Sinä valmistat minun voimalla sotaan, sinä taivutat minun alleni ne, jotka nousevat minua vastaan.","Sinä valmistat minun voimalla sotaan, sinä taivutat minun alleni ne, jotka nousevat minua vastaan."],[22,41,"Ja sinä annat minulle viholliseni kaulan; ja minä kadotan vainoojani.","Ja sinä annat minulle viholliseni kaulan; ja minä kadotan vainoojani."],[22,42,"He huutavat, vaan ei ole auttajaa: Herran tykö, mutta ei hän vastaa heitä.","He huutavat, vaan ei ole auttajaa: Herran tykö, mutta ei hän vastaa heitä."],[22,43,"Minä survon heitä niinkuin maan tomun, ja muserran heidän rikki ja hajoitan heidät niinkuin loan kaduilta.","Minä survon heitä niinkuin maan tomun, ja muserran heidän rikki ja hajoitan heidät niinkuin loan kaduilta."],[22,44,"Sinä pelastat minua riitaisesta kansasta, ja asetat minun pakanain pääksi: se kansa, jota en minä tuntenut, palvelee minua.","Sinä pelastat minua riitaisesta kansasta, ja asetat minun pakanain pääksi: se kansa, jota en minä tuntenut, palvelee minua."],[22,45,"Muukalaiset lapset viekastelevat minua, korvan kuuloon he kuulevat minua.","Muukalaiset lapset viekastelevat minua, korvan kuuloon he kuulevat minua."],[22,46,"Muukalaiset lapset vaipuvat ja vapisevat siteistänsä.","Muukalaiset lapset vaipuvat ja vapisevat siteistänsä."],[22,47,"Herra elää, ja kiitetty olkoon minun kallioni, ja ylistetty olkoon Jumala, minun autuuteni kallio!","Herra elää, ja kiitetty olkoon minun kallioni, ja ylistetty olkoon Jumala, minun autuuteni kallio!"],[22,48,"Jumala, joka minulle koston antaa ja vaatii kansat minun alleni,","Jumala, joka minulle koston antaa ja vaatii kansat minun alleni,"],[22,49,"Joka minua johdatat ulos vihollisistani ja korotat minun niistä, jotka karkaavat minua vastaan, sinä pelastat minua väkivaltaisesta miehestä.","Joka minua johdatat ulos vihollisistani ja korotat minun niistä, jotka karkaavat minua vastaan, sinä pelastat minua väkivaltaisesta miehestä."],[22,50,"Sentähden minä kiitän sinua Herra pakanain seassa, ja sinun nimelles kiitoksen veisaan.","Sentähden minä kiitän sinua Herra pakanain seassa, ja sinun nimelles kiitoksen veisaan."],[22,51,"Joka kuninkaallensa suuren autuuden osoittaa ja tekee laupiuden voidellullensa, Davidille ja hänen siemenellensä ijankaikkisesti.","Joka kuninkaallensa suuren autuuden osoittaa ja tekee laupiuden voidellullensa, Davidille ja hänen siemenellensä ijankaikkisesti."],[23,1,"Ja nämät ovat Davidin viimeiset sanat. David, Isain poika, sanoi, se mies sanoi, joka korotettu on, Jakobin Jumalan voideltu, ja suloinen Israelin psalmein veisaaja:","Ja nämät ovat Davidin viimeiset sanat. David, Isain poika, sanoi, se mies sanoi, joka korotettu on, Jakobin Jumalan voideltu, ja suloinen Israelin psalmein veisaaja:"],[23,2,"Herran Henki on puhunut minun kauttani, ja hänen sanansa on tapahtunut minun kieleni kautta.","Herran Henki on puhunut minun kauttani, ja hänen sanansa on tapahtunut minun kieleni kautta."],[23,3,"Israelin Jumala on sanonut minulle, Israelin turva on minulle puhunut, ihmisten hallitsiasta, vanhurskaasta, joka hallitsee Jumalan pelvossa.","Israelin Jumala on sanonut minulle, Israelin turva on minulle puhunut, ihmisten hallitsiasta, vanhurskaasta, joka hallitsee Jumalan pelvossa."],[23,4,"Niinkuin valkeus on aamulla, kuin aurinko koittaa, varhain ilman pilvetä, ja paisteesta sateen jälkeen ruoho kasvaa maasta.","Niinkuin valkeus on aamulla, kuin aurinko koittaa, varhain ilman pilvetä, ja paisteesta sateen jälkeen ruoho kasvaa maasta."],[23,5,"Eikö minun huoneeni ole niin Jumalan tykönä? Sillä hän on tehnyt ijankaikkisen liiton minun kanssani, kaikella muodolla lujan ja vahvan; sillä se on kaikki minun autuuteni ja haluni; eikö se ole kasvava?","Eikö minun huoneeni ole niin Jumalan tykönä? Sillä hän on tehnyt ijankaikkisen liiton minun kanssani, kaikella muodolla lujan ja vahvan; sillä se on kaikki minun autuuteni ja haluni; eikö se ole kasvava?"],[23,6,"Mutta ilkiät ihmiset kaikki hävitetään niinkuin orjantappurat, joihin ei taideta käsin ruveta.","Mutta ilkiät ihmiset kaikki hävitetään niinkuin orjantappurat, joihin ei taideta käsin ruveta."],[23,7,"Mutta jos joku tahtoo tarttua niihin, hänellä pitää täydellisesti oleman rauta ja keihään varsi; ja ne pitää kokonansa poltettaman tulella heidän sioissansa.","Mutta jos joku tahtoo tarttua niihin, hänellä pitää täydellisesti oleman rauta ja keihään varsi; ja ne pitää kokonansa poltettaman tulella heidän sioissansa."],[23,8,"Nämät ovat Davidin sankarien nimet: Josebbaselet Tahkemonilainen, ylimmäinen päämiehistä: hän oli se AdoniEtsniläinen, joka nousi kahdeksaasataa vastaan, jotka tapettiin yhdellä erällä.","Nämät ovat Davidin sankarien nimet: Josebbaselet Tahkemonilainen, ylimmäinen päämiehistä: hän oli se AdoniEtsniläinen, joka nousi kahdeksaasataa vastaan, jotka tapettiin yhdellä erällä."],[23,9,"Sitälähin oli Eleatsar Dodon poika Ahohin pojan, niiden kolmen sankarien keskellä Davidin kanssa, kuin he pilkkasivat Philistealaisia, jotka olivat sinne kokoontuneet sotaan, ja Israelin miehet menivät ylös.","Sitälähin oli Eleatsar Dodon poika Ahohin pojan, niiden kolmen sankarien keskellä Davidin kanssa, kuin he pilkkasivat Philistealaisia, jotka olivat sinne kokoontuneet sotaan, ja Israelin miehet menivät ylös."],[23,10,"Se nousi ja löi Philistealaiset, siihenasti että hänen kätensä väsyi ja puuntui miekasta. Ja Herra antoi suuren autuuden siihen aikaan, niin että kansa palasi hänen jälkeensä ainoasti ryöstämään.","Se nousi ja löi Philistealaiset, siihenasti että hänen kätensä väsyi ja puuntui miekasta. Ja Herra antoi suuren autuuden siihen aikaan, niin että kansa palasi hänen jälkeensä ainoasti ryöstämään."],[23,11,"Hänen jälkeensä oli Samma Agen Hararilaisen poika: koska Philistealaiset kokosivat itsensä yhteen kylään ja siellä oli yksi peltosarka täynnä herneitä, ja kansa pakeni Philistealaisia;","Hänen jälkeensä oli Samma Agen Hararilaisen poika: koska Philistealaiset kokosivat itsensä yhteen kylään ja siellä oli yksi peltosarka täynnä herneitä, ja kansa pakeni Philistealaisia;"],[23,12,"Silloin seisoi hän keskellä sarkaa ja varjeli sen, löi Philistealaiset, ja Herra antoi suuren autuuden.","Silloin seisoi hän keskellä sarkaa ja varjeli sen, löi Philistealaiset, ja Herra antoi suuren autuuden."],[23,13,"Ja nämät kolme ylimmäistä kolmenkymmenen keskellä tulivat alas elonaikana Davidin tykö Adullamin luolaan; ja Philistealaisten leiri oli Rephaimin laaksossa.","Ja nämät kolme ylimmäistä kolmenkymmenen keskellä tulivat alas elonaikana Davidin tykö Adullamin luolaan; ja Philistealaisten leiri oli Rephaimin laaksossa."],[23,14,"Mutta David oli siihen aikaan linnassa, ja Philistealaisten kansa oli Betlehemissä.","Mutta David oli siihen aikaan linnassa, ja Philistealaisten kansa oli Betlehemissä."],[23,15,"Ja David himoitsi ja sanoi: kuka tuo minulle juoda vettä Betlehemin kaivosta portin tyköä.","Ja David himoitsi ja sanoi: kuka tuo minulle juoda vettä Betlehemin kaivosta portin tyköä."],[23,16,"Niin ne kolme sankaria menivät Philistealaisten leiriin ja ammensivat vettä Betlehemin kaivosta, joka on portin tykönä, kantoivat ja toivat Davidille; mutta ei hän tahtonut sitä juoda, vaan kaasi Herran eteen,","Niin ne kolme sankaria menivät Philistealaisten leiriin ja ammensivat vettä Betlehemin kaivosta, joka on portin tykönä, kantoivat ja toivat Davidille; mutta ei hän tahtonut sitä juoda, vaan kaasi Herran eteen,"],[23,17,"Ja sanoi: Herra, olkoon se minusta kaukana, että minä se tekisin: eikö tämä ole niiden miesten veri, jotka itsensä antoivat hengenvaaraan ja sinne menivät? Ja ei tahtonut sitä juoda. Tämän tekivät ne kolme sankaria.","Ja sanoi: Herra, olkoon se minusta kaukana, että minä se tekisin: eikö tämä ole niiden miesten veri, jotka itsensä antoivat hengenvaaraan ja sinne menivät? Ja ei tahtonut sitä juoda. Tämän tekivät ne kolme sankaria."],[23,18,"Abisai Joabin veli ZeruJan poika oli myös ylimmäinen kolmen keskellä, hän nosti keihäänsä ja löi kolmesataa, ja oli myös ylistetty kolmen keskellä,","Abisai Joabin veli ZeruJan poika oli myös ylimmäinen kolmen keskellä, hän nosti keihäänsä ja löi kolmesataa, ja oli myös ylistetty kolmen keskellä,"],[23,19,"Ja kaikkein jaloin kolmen keskellä ja oli heidän päämiehensä, mutta ei hän tullut niiden kolmen tykö.","Ja kaikkein jaloin kolmen keskellä ja oli heidän päämiehensä, mutta ei hän tullut niiden kolmen tykö."],[23,20,"Ja Benaja Jojadan poika, kuuluisan miehen poika suurista töistänsä Kabselista löi kaksi Moabin väkevää niinkuin jalopeuraa, ja hän meni alas ja löi yhden jalopeuran kaivon tykönä lumen aikana.","Ja Benaja Jojadan poika, kuuluisan miehen poika suurista töistänsä Kabselista löi kaksi Moabin väkevää niinkuin jalopeuraa, ja hän meni alas ja löi yhden jalopeuran kaivon tykönä lumen aikana."],[23,21,"Ja hän löi hirmuisen Egyptin miehen, jolla oli keihäs kädessä, mutta hän meni hänen tykönsä seipäällä, ja tempasi Egyptin miehen kädestä keihään, ja löi hänen kuoliaaksi omalla keihäällänsä.","Ja hän löi hirmuisen Egyptin miehen, jolla oli keihäs kädessä, mutta hän meni hänen tykönsä seipäällä, ja tempasi Egyptin miehen kädestä keihään, ja löi hänen kuoliaaksi omalla keihäällänsä."],[23,22,"Nämät teki Benaja Jojadan poika, ja oli ylistetty kolmen sankarin keskellä,","Nämät teki Benaja Jojadan poika, ja oli ylistetty kolmen sankarin keskellä,"],[23,23,"Ja oli jalompi kuin ne kolmekymmentä mutta ei hän tullut niiden kolmen tykö; ja David asetti hänen salaiseksi neuvonantajaksensa.","Ja oli jalompi kuin ne kolmekymmentä mutta ei hän tullut niiden kolmen tykö; ja David asetti hänen salaiseksi neuvonantajaksensa."],[23,24,"Asahel, Joabin veli, kolmenkymmenen keskellä, Elhanan Dodonin poika Betlehemistä;","Asahel, Joabin veli, kolmenkymmenen keskellä, Elhanan Dodonin poika Betlehemistä;"],[23,25,"Samma Harodilainen, Elika Harodilainen;","Samma Harodilainen, Elika Harodilainen;"],[23,26,"Helets Paltilainen, Ira Ikeksen Tekoalaisen poika;","Helets Paltilainen, Ira Ikeksen Tekoalaisen poika;"],[23,27,"Abieser Anatotilainen, Mebunai Husatilainen;","Abieser Anatotilainen, Mebunai Husatilainen;"],[23,28,"Salmon Ahohilainen, Maharai Netophatilainen;","Salmon Ahohilainen, Maharai Netophatilainen;"],[23,29,"Heleb Baenan poika Netophatilainen, Ittai Ribain poika BenJaminin lasten Gibeasta;","Heleb Baenan poika Netophatilainen, Ittai Ribain poika BenJaminin lasten Gibeasta;"],[23,30,"Benaja Pirtagonilainen, Hiddai Gasin ojista;","Benaja Pirtagonilainen, Hiddai Gasin ojista;"],[23,31,"Abialbon Arbatilainen, Asmavet Barhumilainen;","Abialbon Arbatilainen, Asmavet Barhumilainen;"],[23,32,"Eliaheba Saalbonilainen Jasennin Jonathanin pojan;","Eliaheba Saalbonilainen Jasennin Jonathanin pojan;"],[23,33,"Samma Hararilainen, Ahiam Sararin poika Ararilainen;","Samma Hararilainen, Ahiam Sararin poika Ararilainen;"],[23,34,"Eliphelet Maakatin pojan Ahasbain poika, Eliam Ahitophelin Gilonilaisen poika;","Eliphelet Maakatin pojan Ahasbain poika, Eliam Ahitophelin Gilonilaisen poika;"],[23,35,"Hesrai Karmelilainen, Paerai Arbilainen;","Hesrai Karmelilainen, Paerai Arbilainen;"],[23,36,"Jigal Natanin poika Zobasta, Bani Gadilainen;","Jigal Natanin poika Zobasta, Bani Gadilainen;"],[23,37,"Zelek Ammonilainen; Naharai Beerotilainen, Joabin ZeruJan pojan sota-asetten kantaja,","Zelek Ammonilainen; Naharai Beerotilainen, Joabin ZeruJan pojan sota-asetten kantaja,"],[23,38,"Ira Jitriläinen, Gareb Jitriläinen;","Ira Jitriläinen, Gareb Jitriläinen;"],[23,39,"Uria Hetiläinen. Kaikki yhteen seitsemänneljättäkymmentä.","Uria Hetiläinen. Kaikki yhteen seitsemänneljättäkymmentä."],[24,1,"Ja Herran viha taas julmistui Israelia vastaan ja hän kehoitti Davidin heidän keskellensä, sanoen: mene ja lue Israel ja Juuda.","Ja Herran viha taas julmistui Israelia vastaan ja hän kehoitti Davidin heidän keskellensä, sanoen: mene ja lue Israel ja Juuda."],[24,2,"Ja kuningas sanoi Joabille sodanpäämiehellensä: mene nyt kaikkein Israelin sukukuntain ympäri, ruveten Danista BerSebaan asti, ja lue kansa, että minä tietäisin kansan paljouden.","Ja kuningas sanoi Joabille sodanpäämiehellensä: mene nyt kaikkein Israelin sukukuntain ympäri, ruveten Danista BerSebaan asti, ja lue kansa, että minä tietäisin kansan paljouden."],[24,3,"Joab sanoi kuninkaalle: Herra sinun Jumalas enetköön siihen kansaan sata kertaa sen verran kuin siinä nyt on, että herrani kuninkaan silmät sen näkisivät; mutta mitä iloa on herrallani kuninkaalla siitä asiasta?","Joab sanoi kuninkaalle: Herra sinun Jumalas enetköön siihen kansaan sata kertaa sen verran kuin siinä nyt on, että herrani kuninkaan silmät sen näkisivät; mutta mitä iloa on herrallani kuninkaalla siitä asiasta?"],[24,4,"Mutta kuninkaan sana vahvistui Joabia ja sodanpäämiehiä vastaan. Niin Joab ja sotajoukon päämiehet menivät kuninkaan tyköä lukemaan Israelin kansaa.","Mutta kuninkaan sana vahvistui Joabia ja sodanpäämiehiä vastaan. Niin Joab ja sotajoukon päämiehet menivät kuninkaan tyköä lukemaan Israelin kansaa."],[24,5,"Ja he menivät Jordanin ylitse ja sioittivat itsensä Aroeriin, oikialle puolelle sitä paikkaa, joka on keskellä Gadin ojaa, Jaeserin tykönä;","Ja he menivät Jordanin ylitse ja sioittivat itsensä Aroeriin, oikialle puolelle sitä paikkaa, joka on keskellä Gadin ojaa, Jaeserin tykönä;"],[24,6,"Ja tulivat Gileadiin ja alhaiseen maahan Hadsiin, sitte tulivat he DanJaniin ja Zidonia ympärinsä;","Ja tulivat Gileadiin ja alhaiseen maahan Hadsiin, sitte tulivat he DanJaniin ja Zidonia ympärinsä;"],[24,7,"Ja tulivat vahvaan kaupunkiin Tyroon ja kaikkiin Heviläisten ja Kanaanealaisten kaupunkeihin. Sitte he läksivät sieltä etelän puolelle Juudaa BerSebaan asti;","Ja tulivat vahvaan kaupunkiin Tyroon ja kaikkiin Heviläisten ja Kanaanealaisten kaupunkeihin. Sitte he läksivät sieltä etelän puolelle Juudaa BerSebaan asti;"],[24,8,"Ja kävivät kaiken maan ympäri, ja tulivat yhdeksän kuukauden ja kahdenkymmenen päivän perästä Jerusalemiin jällensä.","Ja kävivät kaiken maan ympäri, ja tulivat yhdeksän kuukauden ja kahdenkymmenen päivän perästä Jerusalemiin jällensä."],[24,9,"Ja Joab antoi kuninkaalle kansan luvun, ja Israelissa oli kahdeksansataa tuhatta vahvaa miekan ulosvetävää sotamiestä; mutta Juudassa oli viisisataa tuhatta miestä.","Ja Joab antoi kuninkaalle kansan luvun, ja Israelissa oli kahdeksansataa tuhatta vahvaa miekan ulosvetävää sotamiestä; mutta Juudassa oli viisisataa tuhatta miestä."],[24,10,"Ja Davidin sydän tykytti sitte kuin kansa luettu oli, ja David sanoi Herralle: minä olen sangen suuresti syntiä tehnyt, että minä sen tein. Herra, käännä nyt palvelias pahateko pois; sillä minä olen tehnyt sangen tyhmästi.","Ja Davidin sydän tykytti sitte kuin kansa luettu oli, ja David sanoi Herralle: minä olen sangen suuresti syntiä tehnyt, että minä sen tein. Herra, käännä nyt palvelias pahateko pois; sillä minä olen tehnyt sangen tyhmästi."],[24,11,"Ja kuin David huomeneltain nousi, tuli Herran sana prophetan Gadin Davidin näkiän tykö, sanoen:","Ja kuin David huomeneltain nousi, tuli Herran sana prophetan Gadin Davidin näkiän tykö, sanoen:"],[24,12,"Mene ja puhu Davidille: näin sanoo Herra: kolme minä panen sinun etees; valitse itselles niistä yksi, jonka minä sinulle teen.","Mene ja puhu Davidille: näin sanoo Herra: kolme minä panen sinun etees; valitse itselles niistä yksi, jonka minä sinulle teen."],[24,13,"Gad tuli Davidin tykö, ilmoitti ja sanoi hänelle: tahdotkos että nälkä tulee seitsemäksi ajastajaksi maakunnalles, taikka ettäs kolme kuukautta pakenet vihamiestes edellä ja he ajavat sinua takaa, eli että rutto on kolme päivää sinun maallas? Niin ota nyt vaari, ja katso, mitä minä hänelle vastaan, joka minun lähetti.","Gad tuli Davidin tykö, ilmoitti ja sanoi hänelle: tahdotkos että nälkä tulee seitsemäksi ajastajaksi maakunnalles, taikka ettäs kolme kuukautta pakenet vihamiestes edellä ja he ajavat sinua takaa, eli että rutto on kolme päivää sinun maallas? Niin ota nyt vaari, ja katso, mitä minä hänelle vastaan, joka minun lähetti."],[24,14,"David sanoi Gadille: minulla on sangen suuri ahdistus; mutta salli meidän langeta Herran käsiin, sillä Herran armo on suuri. En minä tahdo langeta ihmisten käsiin.","David sanoi Gadille: minulla on sangen suuri ahdistus; mutta salli meidän langeta Herran käsiin, sillä Herran armo on suuri. En minä tahdo langeta ihmisten käsiin."],[24,15,"Ja Herra antoi ruttotaudin tulla Israeliin, ruveten aamulla niin määrättyyn aikaan asti; ja kansaa kuoli Danista niin BerSebaan asti, seitsemänkymmentä tuhatta miestä.","Ja Herra antoi ruttotaudin tulla Israeliin, ruveten aamulla niin määrättyyn aikaan asti; ja kansaa kuoli Danista niin BerSebaan asti, seitsemänkymmentä tuhatta miestä."],[24,16,"Ja kuin enkeli ojensi kätensä Jerusalemin ylitse, kadottaaksensa häntä, niin Herra katui sitä pahaa ja sanoi enkelille, joka kansaa hävitti: kyllä jo on; pidä nyt kätes alallansa. Ja Herran enkeli oli Araunan Jebusilaisen riihen tykönä.","Ja kuin enkeli ojensi kätensä Jerusalemin ylitse, kadottaaksensa häntä, niin Herra katui sitä pahaa ja sanoi enkelille, joka kansaa hävitti: kyllä jo on; pidä nyt kätes alallansa. Ja Herran enkeli oli Araunan Jebusilaisen riihen tykönä."],[24,17,"Kuin David näki enkelin, joka kansaa löi, sanoi hän Herralle: katso, minä olen syntiä tehnyt ja minä olen sen pahan tehnyt: mitä nämät lampaat ovat tehneet? Anna siis kätes olla minua vastaan ja minun isäni huonetta vastaan.","Kuin David näki enkelin, joka kansaa löi, sanoi hän Herralle: katso, minä olen syntiä tehnyt ja minä olen sen pahan tehnyt: mitä nämät lampaat ovat tehneet? Anna siis kätes olla minua vastaan ja minun isäni huonetta vastaan."],[24,18,"Ja sinä päivänä tuli Gad Davidin tykö ja sanoi hänelle: mene ja rakenna Herralle alttari Jebusilaisen Araunan riiheen.","Ja sinä päivänä tuli Gad Davidin tykö ja sanoi hänelle: mene ja rakenna Herralle alttari Jebusilaisen Araunan riiheen."],[24,19,"Ja David meni kohta niinkuin Gad sanoi ja Herra oli käskenyt.","Ja David meni kohta niinkuin Gad sanoi ja Herra oli käskenyt."],[24,20,"Mutta kuin Arauna käänsi itsensä, näki hän kuninkaan palvelioinensa tulevan tykönsä; niin Arauna läksi ulos ja lankesi kasvoillensa maahan kuninkaan eteen,","Mutta kuin Arauna käänsi itsensä, näki hän kuninkaan palvelioinensa tulevan tykönsä; niin Arauna läksi ulos ja lankesi kasvoillensa maahan kuninkaan eteen,"],[24,21,"Ja sanoi: miksi herrani kuningas tulee palveliansa tykö? David sanoi: riihtä ostamaan sinulta, rakentaakseni Herralle alttaria, että vitsaus lakkais kansasta.","Ja sanoi: miksi herrani kuningas tulee palveliansa tykö? David sanoi: riihtä ostamaan sinulta, rakentaakseni Herralle alttaria, että vitsaus lakkais kansasta."],[24,22,"Arauna sanoi Davidille: herrani kuningas ottakaan ja uhratkaan niinkuin hänelle kelpaa. Katso, tässä on härkä polttouhriksi, reet ja kaikki härkäin kalut haloiksi.","Arauna sanoi Davidille: herrani kuningas ottakaan ja uhratkaan niinkuin hänelle kelpaa. Katso, tässä on härkä polttouhriksi, reet ja kaikki härkäin kalut haloiksi."],[24,23,"Nämät kaikki, kuningas, antaa Arauna kuninkaalle. Ja Arauna sanoi kuninkaalle: Herra sinun Jumalas leppyköön sinulle.","Nämät kaikki, kuningas, antaa Arauna kuninkaalle. Ja Arauna sanoi kuninkaalle: Herra sinun Jumalas leppyköön sinulle."],[24,24,"Mutta kuningas sanoi Araunalle: ei suinkaan, vaan minä ostan sen täydellisesti sinulta hinnalla; sillä en minä tee Herralle polttouhria siitä, joka minulle lahjaksi on annettu. Niin osti David riihen ja härjän viidelläkymmenellä hopiasiklillä,","Mutta kuningas sanoi Araunalle: ei suinkaan, vaan minä ostan sen täydellisesti sinulta hinnalla; sillä en minä tee Herralle polttouhria siitä, joka minulle lahjaksi on annettu. Niin osti David riihen ja härjän viidelläkymmenellä hopiasiklillä,"],[24,25,"Ja rakensi Herralle siinä alttarin ja uhrasi polttouhreja ja kiitosuhreja; ja Herra leppyi maakunnalle, ja vitsaus lakkasi Israelissa.","Ja rakensi Herralle siinä alttarin ja uhrasi polttouhreja ja kiitosuhreja; ja Herra leppyi maakunnalle, ja vitsaus lakkasi Israelissa."]]}};